// Define GPIO pins using BCM numbering
#define GPIO_2 2
#define GPIO_3 3

// Global variable to track program state for signal handling
volatile sig_atomic_t program_running = 1;

// Signal handler function
void signal_handler(int signal) {
    program_running = 0;
    printf("\nCaught signal %d, exiting gracefully...\n", signal);
}

int main() {
    // Register signal handlers for SIGINT and SIGTERM
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize the pigpio library
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Configure GPIO pins as outputs
    gpioSetMode(GPIO_2, PI_OUTPUT);
    gpioSetMode(GPIO_3, PI_OUTPUT);

    // Main loop to toggle GPIO pins
    while (program_running) {
        // Set GPIO 2 HIGH
        gpioWrite(GPIO_2, 1);
        printf("GPIO 2 HIGH, GPIO 3 LOW\n");

        // Wait for 0.1 seconds
        gpioDelay(100000); // 100000 microseconds = 0.1 seconds

        // Set GPIO 2 LOW and GPIO 3 HIGH
        gpioWrite(GPIO_2, 0);
        gpioWrite(GPIO_3, 1);
        printf("GPIO 2 LOW, GPIO 3 HIGH\n");

        // Wait for 0.1 seconds
        gpioDelay(100000);
    }

    // Clean up and terminate the pigpio library
    gpioTerminate();
    printf("pigpio terminated.\n");

    return 0;
}

