    // Get GPIO lines for GPIO 17 and GPIO 18
    line17 = gpiod_chip_get_line(chip, GPIO_17);
    if (!line17) {
        perror("Error getting GPIO 17 line");
        gpiod_chip_close(chip);
        return 1;
    }

    line18 = gpiod_chip_get_line(chip, GPIO_18);
    if (!line18) {
        perror("Error getting GPIO 18 line");
        gpiod_line_release(line17);
        gpiod_chip_close(chip);
        return 1;
    }

    // Request GPIO lines for output
    if (gpiod_line_request_output(line17, "gpio17_output", 0) < 0) {
        perror("Error requesting GPIO 17 for output");
        gpiod_line_release(line17);
        gpiod_line_release(line18);
        gpiod_chip_close(chip);
        return 1;
    }

    if (gpiod_line_request_output(line18, "gpio18_output", 0) < 0) {
        perror("Error requesting GPIO 18 for output");
        gpiod_line_release(line17);
        gpiod_line_release(line18);
        gpiod_chip_close(chip);
        return 1;
    }

    // Set GPIO 17 to HIGH
    if (gpiod_line_set_value(line17, 1) < 0) {
        perror("Error setting GPIO 17 to HIGH");
        gpiod_line_release(line17);
        gpiod_line_release(line18);
        gpiod_chip_close(chip);
        return 1;
    }
    printf("GPIO 17 set to HIGH\n");

    // Set GPIO 18 to LOW
    if (gpiod_line_set_value(line18, 0) < 0) {
        perror("Error setting GPIO 18 to LOW");
        gpiod_line_release(line17);
        gpiod_line_release(line18);
        gpiod_chip_close(chip);
        return 1;
    }
    printf("GPIO 18 set to LOW\n");

    // Wait for 1 second
    sleep(1);

    // Release GPIO lines
    gpiod_line_release(line17);
    gpiod_line_release(line18);

    // Close GPIO chip
    gpiod_chip_close(chip);

    printf("GPIO lines released and chip closed. Exiting.\n");

    return 0;
}

