#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

// Define GPIO pins
#define TRIGGER_PIN 17
#define ECHO_PIN 27

// Define constants
#define SPEED_OF_SOUND 34300.0 // Speed of sound in cm/s
#define TIMEOUT_US 500000      // Timeout for echo pulse in microseconds (0.5 seconds)
#define MAX_DISTANCE 400.0    // Maximum measurable distance in cm
#define MIN_DISTANCE 2.0      // Minimum measurable distance in cm

// Global variables
static volatile int running = 1;
static int pi;

// Function prototypes
int initialize_gpio();
float measure_distance();
void log_distance(float distance);
void signal_handler(int signal);
void cleanup();

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    running = 0;
    printf("\nCaught signal %d, exiting gracefully...\n", signal);
}

// Initialize GPIO pins
int initialize_gpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return -1;
    }

    pi = 1; //pigpio is always initialized

    gpioSetMode(TRIGGER_PIN, PI_OUTPUT);
    gpioSetMode(ECHO_PIN, PI_INPUT);

    // Ensure trigger is low initially
    gpioWrite(TRIGGER_PIN, 0);
    gpioDelay(1000); // Wait 1ms

    return 0;
}

// Measure distance using HC-SR04
float measure_distance() {
    long long start_tick, end_tick, diff_tick;

    // Trigger the sensor
    gpioWrite(TRIGGER_PIN, 1);
    gpioDelay(10); // 10us trigger pulse
    gpioWrite(TRIGGER_PIN, 0);

    // Measure echo pulse width
    start_tick = gpioTick();
    while (gpioRead(ECHO_PIN) == 0) {
        if (gpioTick() - start_tick > TIMEOUT_US) {
            fprintf(stderr, "Timeout waiting for echo start\n");
            return -1.0; // Timeout
        }
    }
    start_tick = gpioTick();

    while (gpioRead(ECHO_PIN) == 1) {
        if (gpioTick() - start_tick > TIMEOUT_US) {
            fprintf(stderr, "Timeout waiting for echo end\n");
            return -1.0; // Timeout
        }
    }
    end_tick = gpioTick();

    diff_tick = end_tick - start_tick;

    // Calculate distance in centimeters
    float distance = (float)diff_tick * SPEED_OF_SOUND / 2000000.0; // Divide by 1000000.0 to convert us to s and by 2 for one-way distance

    // Validate distance
    if (distance < MIN_DISTANCE || distance > MAX_DISTANCE) {
        fprintf(stderr, "Invalid distance reading: %.2f cm\n", distance);
        return -1.0; // Invalid distance
    }

    return distance;
}

// Log distance to file
void log_distance(float distance) {
    FILE *fp = fopen("distance.log", "a");
    if (fp == NULL) {
        fprintf(stderr, "Error opening log file!\n");
        return;
    }

    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    fprintf(fp, "%d-%02d-%02d %02d:%02d:%02d, Distance: %.2f cm\n", tm.tm_year + 1900, tm.tm_mon + 1, tm.tm_mday, tm.tm_hour, tm.tm_min, tm.tm_sec, distance);
    fclose(fp);
}

// Cleanup GPIO resources
void cleanup() {
    gpioWrite(TRIGGER_PIN, 0); // Ensure trigger is low
    gpioTerminate();
}

int main() {
    // Register signal handler
    signal(SIGINT, signal_handler);

    // Initialize GPIO
    if (initialize_gpio() != 0) {
        return 1;
    }

    printf("HC-SR04 distance measurement started. Press Ctrl+C to exit.\n");

    // Main loop
    while (running) {
        float distance = measure_distance();
        if (distance > 0) {
            printf("Distance: %.2f cm\n", distance);
            log_distance(distance);
        } else {
            fprintf(stderr, "Failed to measure distance\n");
        }

        sleep(60); // Wait 60 seconds
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <fcntl.h>
#include <unistd.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <signal.h>
#include <time.h>
#include <errno.h>
#include <string.h>

// ADS1115 I2C address
#define ADS1115_ADDR 0x28

// ADS1115 register addresses
#define ADS1115_REG_CONFIG 0x01
#define ADS1115_REG_CONVERT 0x00

// Configuration register values
#define ADS1115_CONFIG_OS_SINGLE 0x8000  // Start single conversion
#define ADS1115_CONFIG_MUX_SINGLE_0 0x4000 // AIN0 single-ended
#define ADS1115_CONFIG_PGA_4_096V 0x0000  // +/-4.096V range
#define ADS1115_CONFIG_MODE_SINGLE 0x0100 // Single-shot mode
#define ADS1115_CONFIG_DR_128SPS 0x0060   // 128 SPS
#define ADS1115_CONFIG_COMP_MODE_TRAD 0x0000 // Traditional comparator
#define ADS1115_CONFIG_COMP_POL_LOW 0x0000  // Active low comparator
#define ADS1115_CONFIG_COMP_LAT_NON 0x0000  // Non-latching comparator
#define ADS1115_CONFIG_COMP_QUE_DISABLE 0x0003 // Disable comparator

// Global variable for I2C file descriptor
int i2c_fd = -1;

// Signal handler for Ctrl+C
void signal_handler(int sig) {
    printf("\nExiting program...\n");
    if (i2c_fd != -1) {
        close(i2c_fd);
    }
    exit(0);
}

// Function to write a 16-bit value to an I2C register
int write_i2c_register(int fd, uint8_t reg, uint16_t value) {
    uint8_t buf[3];
    buf[0] = reg;
    buf[1] = (value >> 8) & 0xFF; // MSB
    buf[2] = value & 0xFF;        // LSB

    if (write(fd, buf, 3) != 3) {
        perror("Failed to write to I2C device");
        return -1;
    }
    return 0;
}

// Function to read a 16-bit value from an I2C register
int read_i2c_register(int fd, uint8_t reg, uint16_t *value) {
    uint8_t buf[1];
    buf[0] = reg;

    if (write(fd, buf, 1) != 1) {
        perror("Failed to write register address for read");
        return -1;
    }

    uint8_t read_buf[2];
    if (read(fd, read_buf, 2) != 2) {
        perror("Failed to read from I2C device");
        return -1;
    }

    *value = (read_buf[0] << 8) | read_buf[1];
    return 0;
}

// Function to read the ADC value from the ADS1115
int read_adc(int fd) {
    uint16_t config = ADS1115_CONFIG_OS_SINGLE | ADS1115_CONFIG_MUX_SINGLE_0 | ADS1115_CONFIG_PGA_4_096V | ADS1115_CONFIG_MODE_SINGLE | ADS1115_CONFIG_DR_128SPS | ADS1115_CONFIG_COMP_MODE_TRAD | ADS1115_CONFIG_COMP_POL_LOW | ADS1115_CONFIG_COMP_LAT_NON | ADS1115_CONFIG_COMP_QUE_DISABLE;

    if (write_i2c_register(fd, ADS1115_REG_CONFIG, config) != 0) {
        fprintf(stderr, "Failed to write configuration register.\n");
        return -1;
    }

    // Wait for conversion to complete (at least 8ms for 128 SPS)
    usleep(10000); // 10ms

    uint16_t conversion;
    if (read_i2c_register(fd, ADS1115_REG_CONVERT, &conversion) != 0) {
        fprintf(stderr, "Failed to read conversion register.\n");
        return -1;
    }

    // Check for valid reading (ADS1115 is right-aligned)
    if ((conversion & 0x8000) != 0) {
        fprintf(stderr, "Invalid reading: Sign bit is set.\n");
        return -1;
    }

    return (int16_t)conversion;
}

int main() {
    // Register signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    // Open I2C device
    i2c_fd = open("/dev/i2c-1", O_RDWR);
    if (i2c_fd < 0) {
        perror("Failed to open I2C device");
        return 1;
    }

    // Specify slave address
    if (ioctl(i2c_fd, I2C_SLAVE, ADS1115_ADDR) < 0) {
        perror("Failed to acquire bus access and/or talk to slave");
        close(i2c_fd);
        return 1;
    }

    printf("ADS1115 ADC Reader\n");

    // Main loop
    while (1) {
        int adc_value = read_adc(i2c_fd);
        if (adc_value != -1) {
            printf("ADC Value: %d\n", adc_value);
        } else {
            fprintf(stderr, "Failed to read ADC value.\n");
        }

        sleep(5);
    }

    // The following lines will never be reached due to the infinite loop,
    // but are included for completeness.
    close(i2c_fd);
    return 0;
}

