#include <errno.h>

#define GPIO_CHIP "gpiochip0"
#define GPIO_PIN 18

static struct gpiod_chip *chip;
static struct gpiod_line *line;
static volatile sig_atomic_t terminate = 0;

// Signal handler for Ctrl+C
void sigint_handler(int sig)
{
    terminate = 1;
}

// Function to set the GPIO pin state
int set_gpio_state(struct gpiod_line *line, int value)
{
    int ret;

    ret = gpiod_line_set_value(line, value);
    if (ret < 0) {
        fprintf(stderr, "Error setting GPIO value: %s\n", strerror(-ret));
        return -1;
    }

    return 0;
}

// Function to get the GPIO pin state
int get_gpio_state(struct gpiod_line *line)
{
    int ret;

    ret = gpiod_line_get_value(line);
    if (ret < 0) {
        fprintf(stderr, "Error getting GPIO value: %s\n", strerror(-ret));
        return -1;
    }

    return ret;
}

int main()
{
    int i, current_state, ret;

    // Register signal handler for Ctrl+C
    signal(SIGINT, sigint_handler);

    // Open GPIO chip
    chip = gpiod_chip_open_by_name(GPIO_CHIP);
    if (!chip) {
        fprintf(stderr, "Error opening GPIO chip: %s\n", strerror(errno));
        return 1;
    }

    // Get GPIO line
    line = gpiod_chip_get_line(chip, GPIO_PIN);
    if (!line) {
        fprintf(stderr, "Error getting GPIO line: %s\n", strerror(errno));
        gpiod_chip_close(chip);
        return 1;
    }

    // Request GPIO line for output
    ret = gpiod_line_request_output(line, "gpio-example", 0);
    if (ret < 0) {
        fprintf(stderr, "Error requesting GPIO line for output: %s\n", strerror(-ret));
        gpiod_chip_close(chip);
        return 1;
    }

    // Get initial state
    current_state = get_gpio_state(line);
    if (current_state < 0) {
        gpiod_line_release(line);
        gpiod_chip_close(chip);
        return 1;
    }

    printf("Initial GPIO state: %d\n", current_state);

    // Main loop
    for (i = 0; i < 3 && !terminate; i++) {
        // Toggle GPIO state
        current_state = !current_state;

        // Set GPIO state
        if (set_gpio_state(line, current_state) < 0) {
            break;
        }

        // Report GPIO state
        printf("GPIO state: %d\n", current_state);

        // Wait for 2 seconds
        sleep(2);
    }

    // Release GPIO line
    if (gpiod_line_release(line) < 0) {
        fprintf(stderr, "Error releasing GPIO line: %s\n", strerror(errno));
    }

    // Close GPIO chip
    if (gpiod_chip_close(chip) < 0) {
        fprintf(stderr, "Error closing GPIO chip: %s\n", strerror(errno));
    }

    printf("Program terminated.\n");

    return 0;
}

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <fcntl.h>
#include <unistd.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <signal.h>
#include <errno.h>
#include <string.h>

// ADS1115 I2C address
#define ADS1115_ADDR 0x48

// ADS1115 register addresses
#define ADS1115_REG_CONFIG 0x01
#define ADS1115_REG_CONVERT 0x00

// Configuration register values
#define CONFIG_OS_SINGLE 0x8000  // Start single conversion
#define CONFIG_MUX_SINGLE_0 0x4000 // AIN0 single-ended
#define CONFIG_PGA_4_096V 0x0000  // +/-4.096V range
#define CONFIG_MODE_SINGLE 0x0100 // Single-shot mode
#define CONFIG_DR_128SPS 0x0060   // 128 SPS
#define CONFIG_COMP_MODE_TRAD 0x0000 // Traditional comparator
#define CONFIG_COMP_POL_LOW 0x0000  // Active low comparator
#define CONFIG_COMP_LAT_NON 0x0000  // Non-latching comparator
#define CONFIG_COMP_QUE_DISABLE 0x0003 // Disable comparator

// Global variable for I2C file descriptor
int i2c_fd = -1;

// Signal handler for Ctrl+C
void signal_handler(int sig) {
    printf("\nExiting program...\n");
    if (i2c_fd != -1) {
        close(i2c_fd);
    }
    exit(0);
}

// Function to read a 16-bit value from the ADS1115
int16_t read_ads1115(int fd) {
    uint8_t config[3];
    uint8_t buffer[2];
    int16_t reading;

    // Configure the ADS1115 for single-ended AIN0, +/-4.096V, 128 SPS
    config[0] = ADS1115_REG_CONFIG;
    config[1] = (CONFIG_OS_SINGLE | CONFIG_MUX_SINGLE_0 | CONFIG_PGA_4_096V | CONFIG_MODE_SINGLE | CONFIG_DR_128SPS | CONFIG_COMP_MODE_TRAD | CONFIG_COMP_POL_LOW | CONFIG_COMP_LAT_NON | CONFIG_COMP_QUE_DISABLE) >> 8;
    config[2] = CONFIG_OS_SINGLE | CONFIG_MUX_SINGLE_0 | CONFIG_PGA_4_096V | CONFIG_MODE_SINGLE | CONFIG_DR_128SPS | CONFIG_COMP_MODE_TRAD | CONFIG_COMP_POL_LOW | CONFIG_COMP_LAT_NON | CONFIG_COMP_QUE_DISABLE;

    if (write(fd, config, 3) != 3) {
        perror("Failed to write to I2C device");
        return -1;
    }

    // Wait for conversion to complete (at least 8ms for 128 SPS)
    usleep(10000); // 10ms

    // Read the conversion register
    config[0] = ADS1115_REG_CONVERT;
    if (write(fd, config, 1) != 1) {
        perror("Failed to write to I2C device");
        return -1;
    }

    if (read(fd, buffer, 2) != 2) {
        perror("Failed to read from I2C device");
        return -1;
    }

    // Combine the two bytes to form the 16-bit reading
    reading = (buffer[0] << 8) | buffer[1];

    return reading;
}

int main() {
    // Register signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    // Open I2C device
    i2c_fd = open("/dev/i2c-1", O_RDWR);
    if (i2c_fd < 0) {
        perror("Failed to open I2C device");
        return 1;
    }

    // Specify the address of the slave device
    if (ioctl(i2c_fd, I2C_SLAVE, ADS1115_ADDR) < 0) {
        perror("Failed to acquire bus access and/or talk to slave");
        close(i2c_fd);
        return 1;
    }

    // Main loop
    while (1) {
        int16_t reading = read_ads1115(i2c_fd);
        if (reading != -1) {
            printf("Reading: %d\n", reading);
        } else {
            fprintf(stderr, "Failed to read ADS1115. Retrying...\n");
        }
        usleep(100000); // 100ms delay
    }

    // Close I2C device (this will not be reached in the infinite loop)
    close(i2c_fd);

    return 0;
}

