// Function to handle signals (e.g., Ctrl+C)
void signal_handler(int sig) {
    terminate = 1;
    fprintf(stderr, "\nCaught signal %d, exiting gracefully.\n", sig);
}

// Function to log messages to a file
void log_message(const char *message) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[26];
    strftime(timestamp, sizeof(timestamp)-1, "%Y-%m-%d %H:%M:%S", t);

    fprintf(log_file, "[%s] %s\n", timestamp, message);
    fflush(log_file); // Ensure the log is written immediately
}

// Function to export the GPIO pin
int export_gpio(int pin) {
    char buffer[64];
    int len;
    FILE *fp = fopen("/sys/class/gpio/export", "w");
    if (fp == NULL) {
        perror("Failed to open /sys/class/gpio/export");
        return -1;
    }

    len = snprintf(buffer, sizeof(buffer), "%d", pin);
    if (fwrite(buffer, 1, len, fp) != len) {
        perror("Failed to write to /sys/class/gpio/export");
        fclose(fp);
        return -1;
    }

    fclose(fp);
    return 0;
}

// Function to unexport the GPIO pin
int unexport_gpio(int pin) {
    char buffer[64];
    int len;
    FILE *fp = fopen("/sys/class/gpio/unexport", "w");
    if (fp == NULL) {
        perror("Failed to open /sys/class/gpio/unexport");
        return -1;
    }

    len = snprintf(buffer, sizeof(buffer), "%d", pin);
    if (fwrite(buffer, 1, len, fp) != len) {
        perror("Failed to write to /sys/class/gpio/unexport");
        fclose(fp);
        return -1;
    }

    fclose(fp);
    return 0;
}

// Function to set the GPIO direction
int set_gpio_direction(int pin, const char *direction) {
    char path[64];
    FILE *fp;

    snprintf(path, sizeof(path), "/sys/class/gpio/gpio%d/direction", pin);
    fp = fopen(path, "w");
    if (fp == NULL) {
        perror("Failed to open GPIO direction file");
        return -1;
    }

    if (fprintf(fp, "%s", direction) < 0) {
        perror("Failed to write to GPIO direction file");
        fclose(fp);
        return -1;
    }

    fclose(fp);
    return 0;
}

// Function to set the GPIO value
int set_gpio_value(int pin, int value) {
    char path[64];
    FILE *fp;

    snprintf(path, sizeof(path), "/sys/class/gpio/gpio%d/value", pin);
    fp = fopen(path, "w");
    if (fp == NULL) {
        perror("Failed to open GPIO value file");
        return -1;
    }

    if (fprintf(fp, "%d", value) < 0) {
        perror("Failed to write to GPIO value file");
        fclose(fp);
        return -1;
    }

    fclose(fp);
    return 0;
}

// Function to read the GPIO value
int read_gpio_value(int pin) {
    char path[64];
    FILE *fp;
    int value;

    snprintf(path, sizeof(path), "/sys/class/gpio/gpio%d/value", pin);
    fp = fopen(path, "r");
    if (fp == NULL) {
        perror("Failed to open GPIO value file for reading");
        return -1;
    }

    if (fscanf(fp, "%d", &value) != 1) {
        perror("Failed to read GPIO value");
        fclose(fp);
        return -1;
    }

    fclose(fp);
    return value;
}

// Function to validate the GPIO value
int validate_gpio_value(int value) {
    return (value == 0 || value == 1) ? 0 : -1;
}

int main() {
    int gpio_value;
    int ret;

    // Open the log file
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        perror("Failed to open log file");
        return EXIT_FAILURE;
    }

    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Export the GPIO pin
    if (export_gpio(GPIO_PIN) != 0) {
        log_message("Failed to export GPIO pin");
        fclose(log_file);
        return EXIT_FAILURE;
    }

    // Set the GPIO direction to output
    if (set_gpio_direction(GPIO_PIN, "out") != 0) {
        log_message("Failed to set GPIO direction to output");
        unexport_gpio(GPIO_PIN);
        fclose(log_file);
        return EXIT_FAILURE;
    }

    // Main loop
    while (!terminate) {
        // Read the GPIO value from the user
        printf("Enter GPIO value (0 or 1): ");
        if (scanf("%d", &gpio_value) != 1) {
            fprintf(stderr, "Invalid input. Please enter 0 or 1.\n");
            log_message("Invalid input received");
            while (getchar() != '\n'); // Clear the input buffer
            continue;
        }

        // Validate the GPIO value
        if (validate_gpio_value(gpio_value) != 0) {
            fprintf(stderr, "Invalid GPIO value. Please enter 0 or 1.\n");
            log_message("Invalid GPIO value received");
            continue;
        }

        // Set the GPIO value
        if (set_gpio_value(GPIO_PIN, gpio_value) != 0) {
            log_message("Failed to set GPIO value");
            continue;
        }

        // Read the GPIO value back to confirm
        int read_value = read_gpio_value(GPIO_PIN);
        if (read_value == -1) {
            log_message("Failed to read GPIO value");
            continue;
        }

        // Validate the read value
        if (validate_gpio_value(read_value) != 0) {
            log_message("Invalid read GPIO value");
            continue;
        }

        // Check if the write was successful
        if (read_value != gpio_value) {
            fprintf(stderr, "Error: GPIO value write failed. Expected %d, got %d.\n", gpio_value, read_value);
            log_message("GPIO value write failed");
        } else {
            printf("GPIO value set to %d\n", gpio_value);
            char log_message_buffer[128];
            snprintf(log_message_buffer, sizeof(log_message_buffer), "GPIO value set to %d", gpio_value);
            log_message(log_message_buffer);
        }

        sleep(1); // Wait for 1 second
    }

    // Unexport the GPIO pin
    if (unexport_gpio(GPIO_PIN) != 0) {
        log_message("Failed to unexport GPIO pin");
    }

    // Close the log file
    fclose(log_file);

    return EXIT_SUCCESS;
}

#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define GPIO_PIN 17

volatile sig_atomic_t program_running = 1;

void signal_handler(int signal) {
    program_running = 0;
    printf("\nCaught signal %d, exiting gracefully...\n", signal);
}

int main() {
    int gpio_status;

    // Register signal handlers for SIGINT and SIGTERM
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize pigpio library
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO 17 as an output
    gpioSetMode(GPIO_PIN, PI_OUTPUT);

    printf("GPIO %d set as output.  Toggling every 0.1 seconds. Press Ctrl+C to exit.\n", GPIO_PIN);

    // Main loop to toggle the GPIO state
    while (program_running) {
        // Set GPIO high
        gpioWrite(GPIO_PIN, 1);
        gpio_status = gpioRead(GPIO_PIN);
        printf("GPIO %d set to HIGH (read: %d)\n", GPIO_PIN, gpio_status);

        // Wait for 100 milliseconds
        gpioDelay(100000); // 100 milliseconds = 100000 microseconds

        // Set GPIO low
        gpioWrite(GPIO_PIN, 0);
        gpio_status = gpioRead(GPIO_PIN);
        printf("GPIO %d set to LOW (read: %d)\n", GPIO_PIN, gpio_status);

        // Wait for 100 milliseconds
        gpioDelay(100000); // 100 milliseconds = 100000 microseconds
    }

    // Clean up and terminate pigpio library
    gpioTerminate();
    printf("pigpio terminated.\n");

    return 0;
}

