// Global variable to track program state for signal handling
volatile sig_atomic_t program_running = 1;

// Signal handler function
void signal_handler(int signal) {
    program_running = 0;
    printf("\nCaught signal %d, exiting gracefully...\n", signal);
}

// Function to set the state of a GPIO pin
int set_gpio_state(int gpio, int state) {
    if (gpioWrite(gpio, state) != 0) {
        fprintf(stderr, "Error writing to GPIO %d\n", gpio);
        return -1;
    }
    return 0;
}

// Function to report the state of a GPIO pin
void report_gpio_state(int gpio, int state) {
    printf("GPIO %d: %s\n", gpio, state ? "HIGH" : "LOW");
}

int main() {
    // Initialize pigpio library
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO pins as outputs
    gpioSetMode(GPIO_4, PI_OUTPUT);
    gpioSetMode(GPIO_17, PI_OUTPUT);
    gpioSetMode(GPIO_22, PI_OUTPUT);
    gpioSetMode(GPIO_27, PI_OUTPUT);

    // Register signal handler for SIGINT (Ctrl+C)
    signal(SIGINT, signal_handler);

    // Main loop
    while (program_running) {
        // Set GPIO 4 HIGH
        if (set_gpio_state(GPIO_4, 1) == 0) {
            report_gpio_state(GPIO_4, 1);
        }

        // Set GPIO 17 HIGH
        if (set_gpio_state(GPIO_17, 1) == 0) {
            report_gpio_state(GPIO_17, 1);
        }

        // Set GPIO 22 HIGH
        if (set_gpio_state(GPIO_22, 1) == 0) {
            report_gpio_state(GPIO_22, 1);
        }

        // Set GPIO 27 HIGH
        if (set_gpio_state(GPIO_27, 1) == 0) {
            report_gpio_state(GPIO_27, 1);
        }

        // Wait for 2 seconds
        sleep(2);

        // Set GPIO 4 LOW
        if (set_gpio_state(GPIO_4, 0) == 0) {
            report_gpio_state(GPIO_4, 0);
        }

        // Set GPIO 17 LOW
        if (set_gpio_state(GPIO_17, 0) == 0) {
            report_gpio_state(GPIO_17, 0);
