#include <stdio.h>
#include <stdlib.h>
#include <gpiod.h>
#include <unistd.h>
#include <signal.h>
#include <errno.h>
#include <string.h>

// Define GPIO pins
#define GPIO_4 4
#define GPIO_18 18

// Define chip name
#define CHIP_NAME "gpiochip0"

// Global variables for GPIO lines and chip
struct gpiod_line *gpio4_line = NULL;
struct gpiod_line *gpio18_line = NULL;
struct gpiod_chip *chip = NULL;

// Signal handler for Ctrl+C
void signal_handler(int sig) {
    printf("\nCaught signal %d, cleaning up...\n", sig);

    // Release GPIO lines
    if (gpio4_line) {
        gpiod_line_release(gpio4_line);
    }
    if (gpio18_line) {
        gpiod_line_release(gpio18_line);
    }

    // Close GPIO chip
    if (chip) {
        gpiod_chip_close(chip);
    }

    exit(0);
}

int main() {
    // Register signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    // Open GPIO chip
    chip = gpiod_chip_open_by_name(CHIP_NAME);
    if (!chip) {
        fprintf(stderr, "Error opening GPIO chip '%s': %s\n", CHIP_NAME, strerror(errno));
        return 1;
    }

    // Get GPIO line for GPIO 4
    gpio4_line = gpiod_chip_get_line(chip, GPIO_4);
    if (!gpio4_line) {
        fprintf(stderr, "Error getting GPIO line %d: %s\n", GPIO_4, strerror(errno));
        gpiod_chip_close(chip);
        return 1;
    }

    // Get GPIO line for GPIO 18
    gpio18_line = gpiod_chip_get_line(chip, GPIO_18);
    if (!gpio18_line) {
        fprintf(stderr, "Error getting GPIO line %d: %s\n", GPIO_18, strerror(errno));
        gpiod_line_release(gpio4_line);
        gpiod_chip_close(chip);
        return 1;
    }

    // Request GPIO lines for output
    if (gpiod_line_request_output(gpio4_line, "gpio4_output", 0) < 0) {
        fprintf(stderr, "Error requesting GPIO %d for output: %s\n", GPIO_4, strerror(errno));
        gpiod_line_release(gpio4_line);
        gpiod_line_release(gpio18_line);
        gpiod_chip_close(chip);
        return 1;
    }

    if (gpiod_line_request_output(gpio18_line, "gpio18_output", 0) < 0) {
        fprintf(stderr, "Error requesting GPIO %d for output: %s\n", GPIO_18, strerror(errno));
        gpiod_line_release(gpio4_line);
        gpiod_line_release(gpio18_line);
        gpiod_chip_close(chip);
        return 1;
    }

    // Main loop
    while (1) {
        // Set GPIO 4 to HIGH
        if (gpiod_line_set_value(gpio4_line, 1) < 0) {
            fprintf(stderr, "Error setting GPIO %d to HIGH: %s\n", GPIO_4, strerror(errno));
            break; // Exit loop on error
        }
        printf("GPIO %d: HIGH\n", GPIO_4);

        // Set GPIO 18 to LOW
        if (gpiod_line_set_value(gpio18_line, 0) < 0) {
            fprintf(stderr, "Error setting GPIO %d to LOW: %s\n", GPIO_18, strerror(errno));
            break; // Exit loop on error
        }
        printf("GPIO %d: LOW\n", GPIO_18);

        // Wait for 50 milliseconds
        struct timespec sleep_time;
        sleep_time.tv_sec = 0;
        sleep_time.tv_nsec = 50 * 1000 * 1000; // 50 milliseconds
        nanosleep(&sleep_time, NULL);

        // Set GPIO 4 to LOW
        if (gpiod_line_set_value(gpio4_line, 0) < 0) {
            fprintf(stderr, "Error setting GPIO %d to LOW: %s\n", GPIO_4, strerror(errno));
            break; // Exit loop on error
        }
        printf("GPIO %d: LOW\n", GPIO_4);

        // Set GPIO 18 to HIGH
        if (gpiod_line_set_value(gpio18_line, 1) < 0) {
            fprintf(stderr, "Error setting GPIO %d to HIGH: %s\n", GPIO_18, strerror(errno));
            break; // Exit loop on error
        }
        printf("GPIO %d: HIGH\n", GPIO_18);

        // Wait for 50 milliseconds
        nanosleep(&sleep_time, NULL);
    }

    // Cleanup (should not reach here if signal handler works correctly)
    gpiod_line_release(gpio4_line);
    gpiod_line_release(gpio18_line);
    gpiod_chip_close(chip);

    return 1;
}

