#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <fcntl.h>
#include <unistd.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <signal.h>
#include <time.h>
#include <errno.h>
#include <string.h>

// Constants
#define I2C_BUS "/dev/i2c-1"
#define SI7021_ADDR 0x40
#define TEMP_MEASURE_CMD 0xE3
#define TEMP_READ_DELAY_MS 30
#define MAX_RETRIES 3
#define RETRY_DELAY_MS 10

// Global variables
int i2c_fd = -1;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int init_i2c(const char *bus);
int read_temperature(int fd, float *temperature);
void signal_handler(int sig);
void cleanup(int fd);

// Signal handler
void signal_handler(int sig) {
    terminate = 1;
    printf("\nCaught signal %d, exiting gracefully...\n", sig);
}

// Initialize I2C bus
int init_i2c(const char *bus) {
    int fd = open(bus, O_RDWR);
    if (fd < 0) {
        perror("Error opening I2C bus");
        return -1;
    }

    if (ioctl(fd, I2C_SLAVE, SI7021_ADDR) < 0) {
        perror("Error setting I2C slave address");
        close(fd);
        return -1;
    }

    return fd;
}

// Read temperature from SI7021
int read_temperature(int fd, float *temperature) {
    uint8_t cmd = TEMP_MEASURE_CMD;
    uint8_t data[2];
    int retries = 0;

    while (retries < MAX_RETRIES) {
        if (write(fd, &cmd, 1) != 1) {
            perror("Error writing temperature measurement command");
            retries++;
            usleep(RETRY_DELAY_MS * 1000); // Exponential backoff
            continue;
        }

        usleep(TEMP_READ_DELAY_MS * 1000); // Wait for measurement

        if (read(fd, data, 2) != 2) {
            perror("Error reading temperature data");
            retries++;
            usleep(RETRY_DELAY_MS * 1000); // Exponential backoff
            continue;
        }

        // Convert raw data to temperature (Celsius)
        uint16_t raw_temp = (data[0] << 8) | data[1];
        *temperature = (175.72 * raw_temp / 65536.0) - 46.85;

        // Validate temperature reading
        if (*temperature < -40.0 || *temperature > 125.0) {
            fprintf(stderr, "Error: Invalid temperature reading: %.2f\n", *temperature);
            return -1; // Indicate invalid reading
        }

        return 0; // Success
    }

    fprintf(stderr, "Error: Failed to read temperature after %d retries.\n", MAX_RETRIES);
    return -1; // Indicate failure
}

// Cleanup resources
void cleanup(int fd) {
    if (fd != -1) {
        close(fd);
    }
}

int main() {
    // Install signal handler
    signal(SIGINT, signal_handler);

    // Initialize I2C
    i2c_fd = init_i2c(I2C_BUS);
    if (i2c_fd < 0) {
        return EXIT_FAILURE;
    }

    printf("SI7021 temperature sensor reader started. Press Ctrl+C to exit.\n");

    // Main loop
    while (!terminate) {
        float temperature;

        if (read_temperature(i2c_fd, &temperature) == 0) {
            printf("Temperature: %.2f °C\n", temperature);
        } else {
            fprintf(stderr, "Failed to read temperature.\n");
        }

        sleep(5);
    }

    // Cleanup and exit
    cleanup(i2c_fd);
    return EXIT_SUCCESS;
}

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
