{
    fprintf(stderr, "\nCaught signal %d, terminating...\n", sig);
    terminate = 1;
}

// Function to read the GPIO state
int read_gpio_state()
{
    int value;

    value = gpiod_line_get_value(line);
    if (value < 0) {
        fprintf(stderr, "Error reading GPIO value: %d\n", value);
        return -1; // Indicate error
    }

    return value;
}

// Function to validate the GPIO state
int validate_gpio_state(int state)
{
    if (state < MIN_STATE || state > MAX_STATE) {
        fprintf(stderr, "Invalid GPIO state: %d\n", state);
        return -1; // Indicate invalid state
    }
    return 0; // Indicate valid state
}

// Function to set the GPIO state
int set_gpio_state(int state)
{
    int ret;

    ret = gpiod_line_set_value(line, state);
    if (ret < 0) {
        fprintf(stderr, "Error setting GPIO value: %d\n", ret);
        return -1; // Indicate error
    }

    return 0; // Indicate success
}

// Function to report the GPIO state
void report_gpio_state(int state)
{
    printf("GPIO state: %d\n", state);
}

int main()
{
    int current_state, new_state;
    struct timespec sleep_time;

    // Set up signal handling
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Open GPIO chip
    chip = gpiod_chip_open_by_name(GPIO_CHIP);
    if (!chip) {
        fprintf(stderr, "Error opening GPIO chip: %s\n", GPIO_CHIP);
        return 1;
    }

    // Get GPIO line
    line = gpiod_chip_get_line(chip, GPIO_PIN);
    if (!line) {
        fprintf(stderr, "Error getting GPIO line: %d\n", GPIO_PIN);
        gpiod_chip_close(chip);
        return 1;
    }

    // Request GPIO line for output
    if (gpiod_line_request_output(line, "gpio_control", 0) < 0) {
        fprintf(stderr, "Error requesting GPIO line for output\n");
        gpiod_chip_close(chip);
        return 1;
    }

    // Main loop
    while (!terminate) {
        // Read current GPIO state
        current_state = read_gpio_state();
        if (current_state < 0) {
            fprintf(stderr, "Error reading current GPIO state, exiting...\n");
            break;
        }

        // Validate GPIO state
        if (validate_gpio_state(current_state) < 0) {
            fprintf(stderr, "Invalid GPIO state, exiting...\n");
            break;
        }

        // Calculate new state (toggle)
        new_state = (current_state == 0) ? 1 : 0;

        // Set GPIO state
        if (set_gpio_state(new_state) < 0) {
            fprintf(stderr, "Error setting GPIO state, exiting...\n");
            break;
        }

        // Report GPIO state
        report_gpio_state(new_state);

        // Sleep for 1 second
        sleep_time.tv_sec = 1;
        sleep_time.tv_nsec = 0;
        nanosleep(&sleep_time, NULL);
    }

    // Clean up
    if (line) {
        gpiod_line_release(line);
    }
    if (chip) {
        gpiod_chip_close(chip);
    }

    return 0;
}

