#define MAX_SENSOR_VALUE 1023

// Global variable to indicate program termination
volatile sig_atomic_t program_running = 1;

// Signal handler for SIGINT (Ctrl+C)
void signal_handler(int signal) {
    program_running = 0;
    printf("\nCaught signal %d, exiting gracefully...\n", signal);
}

// Function to read the sensor value from the specified GPIO pin
int read_sensor(int gpio_pin) {
    int sensor_value = gpioRead(gpio_pin);
    if (sensor_value < 0) {
        fprintf(stderr, "Error reading sensor value from GPIO %d: %d\n", gpio_pin, sensor_value);
        return -1; // Indicate an error
    }
    return sensor_value;
}

// Function to apply the sensor reading to the specified GPIO pin
void apply_reading(int gpio_pin, int sensor_value) {
    if (sensor_value >= MIN_SENSOR_VALUE && sensor_value <= MAX_SENSOR_VALUE) {
        gpioWrite(gpio_pin, sensor_value);
        printf("GPIO %d set to %d\n", gpio_pin, sensor_value);
    } else {
        fprintf(stderr, "Invalid sensor reading: %d. Value must be between %d and %d.\n", sensor_value, MIN_SENSOR_VALUE, MAX_SENSOR_VALUE);
    }
}

