    }

    // Set GPIO 2 and GPIO 3 as outputs
    gpioSetMode(GPIO_2, PI_OUTPUT);
    gpioSetMode(GPIO_3, PI_OUTPUT);

    // Register the signal handler for SIGINT
    signal(SIGINT, signal_handler);

    printf("Program started. Press Ctrl+C to exit.\n");

    // Main loop
    while (program_running) {
        // Read sensor values from GPIO 2 and GPIO 3
        int sensor_value_2 = read_sensor(GPIO_2);
        int sensor_value_3 = read_sensor(GPIO_3);

        // Apply sensor readings to GPIO 2 and GPIO 3
        if (sensor_value_2 != -1) {
            apply_reading(GPIO_2, sensor_value_2);
        }
        if (sensor_value_3 != -1) {
            apply_reading(GPIO_3, sensor_value_3);
        }

        // Wait for 5 seconds
        sleep(5);
    }

    // Clean up and terminate the pigpio library
    gpioTerminate();
    printf("Program terminated.\n");
    return 0;
}

