#include <stdio.h>
#include <stdlib.h>
#include <gpiod.h>
#include <unistd.h>
#include <signal.h>
#include <time.h>
#include <errno.h>

// Define GPIO pins
#define GPIO_PIN_1 2
#define GPIO_PIN_2 3

// Define GPIO chip name
#define GPIO_CHIP "gpiochip0"

// Define valid range for GPIO value
#define GPIO_MIN 0
#define GPIO_MAX 1

// Global variables for GPIO lines and chip
struct gpiod_line *gpio_line_1 = NULL;
struct gpiod_line *gpio_line_2 = NULL;
struct gpiod_chip *gpio_chip = NULL;

// Signal handler for Ctrl+C
void signal_handler(int sig) {
    printf("\nCaught signal %d, cleaning up...\n", sig);

    // Release GPIO lines
    if (gpio_line_1) {
        gpiod_line_release(gpio_line_1);
    }
    if (gpio_line_2) {
        gpiod_line_release(gpio_line_2);
    }

    // Close GPIO chip
    if (gpio_chip) {
        gpiod_chip_close(gpio_chip);
    }

    exit(0);
}

// Function to set GPIO value
int set_gpio_value(struct gpiod_line *line, int value) {
    if (value < GPIO_MIN || value > GPIO_MAX) {
        fprintf(stderr, "Error: Invalid GPIO value %d. Value must be between %d and %d.\n", value, GPIO_MIN, GPIO_MAX);
        return -1;
    }

    int ret = gpiod_line_set_value(line, value);
    if (ret < 0) {
        fprintf(stderr, "Error: Failed to set GPIO value: %s\n", strerror(errno));
        return -1;
    }

    return 0;
}

// Function to get GPIO value
int get_gpio_value(struct gpiod_line *line) {
    int value = gpiod_line_get_value(line);
    if (value < 0) {
        fprintf(stderr, "Error: Failed to get GPIO value: %s\n", strerror(errno));
        return -1;
    }

    return value;
}

int main() {
    // Install signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    // Open GPIO chip
    gpio_chip = gpiod_chip_open_by_name(GPIO_CHIP);
    if (!gpio_chip) {
        fprintf(stderr, "Error: Failed to open GPIO chip '%s': %s\n", GPIO_CHIP, strerror(errno));
        return 1;
    }

    // Get GPIO lines
    gpio_line_1 = gpiod_chip_get_line(gpio_chip, GPIO_PIN_1);
    if (!gpio_line_1) {
        fprintf(stderr, "Error: Failed to get GPIO line %d: %s\n", GPIO_PIN_1, strerror(errno));
        gpiod_chip_close(gpio_chip);
        return 1;
    }

    gpio_line_2 = gpiod_chip_get_line(gpio_chip, GPIO_PIN_2);
    if (!gpio_line_2) {
        fprintf(stderr, "Error: Failed to get GPIO line %d: %s\n", GPIO_PIN_2, strerror(errno));
        gpiod_line_release(gpio_line_1);
        gpiod_chip_close(gpio_chip);
        return 1;
    }

    // Request GPIO lines for output
    if (gpiod_line_request_output(gpio_line_1, "gpio_output", 0) < 0) {
        fprintf(stderr, "Error: Failed to request GPIO line %d for output: %s\n", GPIO_PIN_1, strerror(errno));
        gpiod_line_release(gpio_line_1);
        gpiod_line_release(gpio_line_2);
        gpiod_chip_close(gpio_chip);
        return 1;
    }

    if (gpiod_line_request_output(gpio_line_2, "gpio_output", 0) < 0) {
        fprintf(stderr, "Error: Failed to request GPIO line %d for output: %s\n", GPIO_PIN_2, strerror(errno));
        gpiod_line_release(gpio_line_1);
        gpiod_line_release(gpio_line_2);
        gpiod_chip_close(gpio_chip);
        return 1;
    }

    // Main loop
    while (1) {
        // Set GPIO 2 to 1
        if (set_gpio_value(gpio_line_2, 1) < 0) {
            fprintf(stderr, "Error setting GPIO 2 to 1, exiting.\n");
            break;
        }
        printf("GPIO 2 set to 1\n");

        // Get GPIO 1 value
        int gpio_1_value = get_gpio_value(gpio_line_1);
        if (gpio_1_value < 0) {
            fprintf(stderr, "Error getting GPIO 1 value, exiting.\n");
            break;
        }
        printf("GPIO 1 value: %d\n", gpio_1_value);

        // Wait for 5 seconds
        sleep(5);

        // Set GPIO 2 to 0
        if (set_gpio_value(gpio_line_2, 0) < 0) {
            fprintf(stderr, "Error setting GPIO 2 to 0, exiting.\n");
            break;
        }
        printf("GPIO 2 set to 0\n");

        // Get GPIO 1 value
        gpio_1_value = get_gpio_value(gpio_line_1);
        if (gpio_1_value < 0) {
            fprintf(stderr, "Error getting GPIO 1 value, exiting.\n");
            break;
        }
        printf("GPIO 1 value: %d\n", gpio_1_value);

        // Wait for 5 seconds
        sleep(5);
    }

    // Cleanup (should not reach here if signal handler works correctly)
    gpiod_line_release(gpio_line_1);
    gpiod_line_release(gpio_line_2);
    gpiod_chip_close(gpio_chip);

    return 0;
}

#include <stdio.h>
#include <stdlib.h>
