#include <unistd.h>
#include <signal.h>
#include <errno.h>

// Define GPIO pins
#define GPIO_2 2
#define GPIO_3 3

// Define the number of cycles
#define NUM_CYCLES 3

// Global variables for GPIO lines and chip
struct gpiod_line *gpio_line_2 = NULL;
struct gpiod_line *gpio_line_3 = NULL;
struct gpiod_chip *chip = NULL;

// Signal handler for Ctrl+C
void signal_handler(int sig) {
    printf("\nCaught signal %d, cleaning up...\n", sig);

    // Release GPIO lines
    if (gpio_line_2) {
        gpiod_line_release(gpio_line_2);
    }
    if (gpio_line_3) {
        gpiod_line_release(gpio_line_3);
    }

    // Close GPIO chip
    if (chip) {
        gpiod_chip_close(chip);
    }

    exit(0);
}

int main() {
    int i;
    int ret;

    // Register signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    // Open GPIO chip
    chip = gpiod_chip_open_by_name("gpiochip0");
    if (!chip) {
        perror("Error opening GPIO chip");
        return 1;
    }

    // Get GPIO lines for GPIO 2 and GPIO 3
    gpio_line_2 = gpiod_chip_get_line(chip, GPIO_2);
    if (!gpio_line_2) {
        perror("Error getting GPIO line 2");
        gpiod_chip_close(chip);
        return 1;
    }

    gpio_line_3 = gpiod_chip_get_line(chip, GPIO_3);
    if (!gpio_line_3) {
        perror("Error getting GPIO line 3");
        gpiod_line_release(gpio_line_2);
        gpiod_chip_close(chip);
        return 1;
    }

    // Request GPIO lines for output
    ret = gpiod_line_request_output(gpio_line_2, "gpio_output", 0);
    if (ret < 0) {
        perror("Error requesting GPIO line 2 for output");
        gpiod_line_release(gpio_line_2);
        gpiod_line_release(gpio_line_3);
        gpiod_chip_close(chip);
        return 1;
    }

    ret = gpiod_line_request_output(gpio_line_3, "gpio_output", 0);
    if (ret < 0) {
        perror("Error requesting GPIO line 3 for output");
        gpiod_line_release(gpio_line_2);
        gpiod_line_release(gpio_line_3);
        gpiod_chip_close(chip);
        return 1;
    }

    // Perform the cycles
    for (i = 0; i < NUM_CYCLES; i++) {
        // Set GPIO 2 HIGH
        ret = gpiod_line_set_value(gpio_line_2, 1);
        if (ret < 0) {
            perror("Error setting GPIO line 2 HIGH");
            gpiod_line_release(gpio_line_2);
            gpiod_line_release(gpio_line_3);
            gpiod_chip_close(chip);
            return 1;
        }
        printf("GPIO 2 HIGH\n");

        // Set GPIO 3 LOW
        ret = gpiod_line_set_value(gpio_line_3, 0);
        if (ret < 0) {
            perror("Error setting GPIO line 3 LOW");
            gpiod_line_release(gpio_line_2);
            gpiod_line_release(gpio_line_3);
            gpiod_chip_close(chip);
            return 1;
        }
        printf("GPIO 3 LOW\n");

        sleep(1);

        // Set GPIO 2 LOW
        ret = gpiod_line_set_value(gpio_line_2, 0);
        if (ret < 0) {
            perror("Error setting GPIO line 2 LOW");
            gpiod_line_release(gpio_line_2);
            gpiod_line_release(gpio_line_3);
            gpiod_chip_close(chip);
            return 1;
        }
        printf("GPIO 2 LOW\n");

        // Set GPIO 3 HIGH
        ret = gpiod_line_set_value(gpio_line_3, 1);
        if (ret < 0) {
            perror("Error setting GPIO line 3 HIGH");
            gpiod_line_release(gpio_line_2);
            gpiod_line_release(gpio_line_3);
            gpiod_chip_close(chip);
            return 1;
        }
        printf("GPIO 3 HIGH\n");

        sleep(1);
    }

    // Release GPIO lines
    gpiod_line_release(gpio_line_2);
    gpiod_line_release(gpio_line_3);

    // Close GPIO chip
    gpiod_chip_close(chip);

    printf("Program finished.\n");
    return 0;
}

