            report_gpio_state(GPIO_4, 1);
        }

        // Set GPIO 17 LOW
        if (set_gpio_state(GPIO_17, 0) == 0) {
            report_gpio_state(GPIO_17, 0);
        }

        // Set GPIO 22 HIGH
        if (set_gpio_state(GPIO_22, 1) == 0) {
            report_gpio_state(GPIO_22, 1);
        }

        // Set GPIO 27 LOW
        if (set_gpio_state(GPIO_27, 0) == 0) {
            report_gpio_state(GPIO_27, 0);
        }

        // Wait for 1 second
        sleep(1);
    }

    // Release GPIO resources
    gpioTerminate();

    return 0;
}

#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define GPIO_PIN 17

volatile sig_atomic_t program_running = 1;

void signal_handler(int signal) {
    program_running = 0;
    printf("\nCaught signal %d, exiting gracefully...\n", signal);
}

int main() {
    int gpio_status;

    // Register signal handlers for SIGINT and SIGTERM
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize pigpio library
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO 17 as an output
    gpioSetMode(GPIO_PIN, PI_OUTPUT);

    printf("GPIO %d set as output.  Toggling every 0.5 seconds...\n", GPIO_PIN);

    // Main loop to toggle the GPIO pin
    while (program_running) {
        // Set GPIO high
        gpioWrite(GPIO_PIN, 1);
        gpio_status = gpioRead(GPIO_PIN);
        if (gpio_status != 1) {
            fprintf(stderr, "Error: GPIO %d read back as %d\n", GPIO_PIN, gpio_status);
        }
        printf("GPIO %d set to HIGH\n", GPIO_PIN);

        // Wait for 500 milliseconds
        gpioDelay(500000);

        // Set GPIO low
        gpioWrite(GPIO_PIN, 0);
        gpio_status = gpioRead(GPIO_PIN);
        if (gpio_status != 0) {
            fprintf(stderr, "Error: GPIO %d read back as %d\n", GPIO_PIN, gpio_status);
        }
        printf("GPIO %d set to LOW\n", GPIO_PIN);

        // Wait for 500 milliseconds
        gpioDelay(500000);
    }

    // Clean up and terminate pigpio library
    gpioTerminate();
    printf("pigpio terminated.\n");

    return 0;
}

#include <stdio.h>
#include <stdlib.h>
