#include <string.h>

// Define GPIO pins
#define GPIO_17 17
#define GPIO_18 18

// Define GPIO chip name
#define GPIO_CHIP "gpiochip0"

// Global variables for GPIO lines and chip
struct gpiod_line *gpio_line_17 = NULL;
struct gpiod_line *gpio_line_18 = NULL;
struct gpiod_chip *gpio_chip = NULL;

// Signal handler for Ctrl+C
void signal_handler(int sig) {
    printf("\nCaught signal %d, cleaning up...\n", sig);

    // Release GPIO lines
    if (gpio_line_17) {
        gpiod_line_release(gpio_line_17);
    }
    if (gpio_line_18) {
        gpiod_line_release(gpio_line_18);
    }

    // Close GPIO chip
    if (gpio_chip) {
        gpiod_chip_close(gpio_chip);
    }

    exit(0);
}

// Function to read GPIO value from a line
int read_gpio(struct gpiod_line *line) {
    int value = gpiod_line_get_value(line);
    if (value < 0) {
        fprintf(stderr, "Error reading GPIO value: %s\n", strerror(-value));
        return -1; // Indicate error
    }
    return value;
}

// Function to write GPIO value to a line
int write_gpio(struct gpiod_line *line, int value) {
    int ret = gpiod_line_set_value(line, value);
    if (ret < 0) {
        fprintf(stderr, "Error writing GPIO value: %s\n", strerror(-ret));
        return -1; // Indicate error
    }
    return 0; // Indicate success
}

// Function to validate the GPIO reading
int validate_reading(int reading) {
    if (reading != 0 && reading != 1) {
        fprintf(stderr, "Invalid GPIO reading: %d\n", reading);
        return -1; // Indicate invalid reading
    }
    return 0; // Indicate valid reading
}

int main() {
    // Install signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    // Open GPIO chip
    gpio_chip = gpiod_chip_open_by_name(GPIO_CHIP);
    if (!gpio_chip) {
        fprintf(stderr, "Error opening GPIO chip: %s\n", strerror(errno));
        return 1;
    }

    // Get GPIO lines
    gpio_line_17 = gpiod_chip_get_line(gpio_chip, GPIO_17);
    gpio_line_18 = gpiod_chip_get_line(gpio_chip, GPIO_18);

    if (!gpio_line_17 || !gpio_line_18) {
        fprintf(stderr, "Error getting GPIO line(s): %s\n", strerror(errno));
        if (gpio_line_17) gpiod_line_release(gpio_line_17);
        if (gpio_line_18) gpiod_line_release(gpio_line_18);
        gpiod_chip_close(gpio_chip);
        return 1;
    }

    // Request GPIO lines for output
    if (gpiod_line_request_output(gpio_line_17, "gpio_output", 0) < 0) {
        fprintf(stderr, "Error requesting GPIO 17 for output: %s\n", strerror(errno));
        gpiod_line_release(gpio_line_17);
        gpiod_line_release(gpio_line_18);
        gpiod_chip_close(gpio_chip);
        return 1;
    }
    if (gpiod_line_request_output(gpio_line_18, "gpio_output", 0) < 0) {
        fprintf(stderr, "Error requesting GPIO 18 for output: %s\n", strerror(errno));
        gpiod_line_release(gpio_line_17);
        gpiod_line_release(gpio_line_18);
        gpiod_chip_close(gpio_chip);
        return 1;
    }

    // Read GPIO values
    int value_17 = read_gpio(gpio_line_17);
    int value_18 = read_gpio(gpio_line_18);

    if (value_17 < 0 || value_18 < 0) {
        // Error already reported in read_gpio function
        gpiod_line_release(gpio_line_17);
        gpiod_line_release(gpio_line_18);
        gpiod_chip_close(gpio_chip);
        return 1;
    }

    // Validate readings
    if (validate_reading(value_17) < 0 || validate_reading(value_18) < 0) {
        // Error already reported in validate_reading function
        gpiod_line_release(gpio_line_17);
        gpiod_line_release(gpio_line_18);
        gpiod_chip_close(gpio_chip);
        return 1;
    }

    // Write GPIO values
    if (write_gpio(gpio_line_17, value_17) < 0 || write_gpio(gpio_line_18, value_18) < 0) {
        // Error already reported in write_gpio function
        gpiod_line_release(gpio_line_17);
        gpiod_line_release(gpio_line_18);
        gpiod_chip_close(gpio_chip);
        return 1;
    }

    // Report GPIO states
    printf("GPIO 17: %d\n", value_17);
    printf("GPIO 18: %d\n", value_18);

    // Release GPIO lines
    gpiod_line_release(gpio_line_17);
    gpiod_line_release(gpio_line_18);

    // Close GPIO chip
    gpiod_chip_close(gpio_chip);

    return 0;
}

#include <stdio.h>
#include <stdlib.h>
#include <gpiod.h>
#include <unistd.h>
#include <signal.h>
#include <time.h>
#include <errno.h>

// Define GPIO pin and chip
#define GPIO_PIN 4
#define GPIO_CHIP "gpiochip0"

// Define DHT11 timings (in microseconds)
#define DHT11_START_SIGNAL 1
#define DHT11_RESPONSE_LOW 80
#define DHT11_RESPONSE_HIGH 80
#define DHT11_DATA_BIT_LOW 50
#define DHT11_DATA_BIT_HIGH_0 26
#define DHT11_DATA_BIT_HIGH_1 70
#define DHT11_PULSES 40

// Global variables for signal handling
static volatile int keep_running = 1;
static struct gpiod_chip *chip = NULL;
static struct gpiod_line *line = NULL;

// Signal handler function
void signal_handler(int sig)
{
    (void)sig; // Suppress unused parameter warning
    keep_running = 0;
    fprintf(stderr, "\nCaught signal, exiting gracefully...\n");
}

// Function to initialize GPIO
int initialize_gpio(void)
{
    chip = gpiod_chip_open_by_name(GPIO_CHIP);
    if (!chip) {
        perror("Error opening GPIO chip");
        return -1;
    }

    line = gpiod_chip_get_line(chip, GPIO_PIN);
    if (!line) {
        perror("Error getting GPIO line");
        gpiod_chip_close(chip);
        return -1;
    }

    if (gpiod_line_request_output(line, "dht11_reader", 0) < 0) {
        perror("Error requesting GPIO line as output");
        gpiod_chip_close(chip);
        return -1;
    }

    return 0;
}

// Function to release GPIO resources
void release_gpio(void)
{
    if (line) {
        gpiod_line_release(line);
    }
    if (chip) {
        gpiod_chip_close(chip);
    }
}

// Function to read DHT11 data
int read_dht11_data(int *humidity, int *temperature)
{
    int data[5] = {0};
    int i, j;

    // Send start signal
    if (gpiod_line_set_value(line, 0) < 0) {
        perror("Error setting GPIO line low");
        return -1;
    }
    usleep(DHT11_START_SIGNAL * 1000); // Convert ms to us
    if (gpiod_line_set_value(line, 1) < 0) {
        perror("Error setting GPIO line high");
        return -1;
    }
    usleep(DHT11_RESPONSE_LOW * 1000); // Convert ms to us

    // Read response
    if (gpiod_line_request_input(line, "dht11_reader") < 0) {
        perror("Error requesting GPIO line as input");
        return -1;
    }
    usleep(DHT11_RESPONSE_HIGH * 1000); // Convert ms to us

    // Read data bits
    for (i = 0; i < DHT11_PULSES; i++) {
        struct timespec start, end;
        long duration;

        // Wait for low
        clock_gettime(CLOCK_MONOTONIC, &start);
        while (gpiod_line_get_value(line) == 0) {
            clock_gettime(CLOCK_MONOTONIC, &end);
            duration = (end.tv_sec - start.tv_sec) * 1000000 + (end.tv_nsec - start.tv_nsec) / 1000;
            if (duration > 100) { // Timeout after 100us
                fprintf(stderr, "Timeout waiting for low pulse\n");
                gpiod_line_release(line);
                return -1;
            }
        }

        // Wait for high
        clock_gettime(CLOCK_MONOTONIC, &start);
        while (gpiod_line_get_value(line) == 1) {
            clock_gettime(CLOCK_MONOTONIC, &end);
            duration = (end.tv_sec - start.tv_sec) * 1000000 + (end.tv_nsec - start.tv_nsec) / 1000;
            if (duration > 100) { // Timeout after 100us
                fprintf(stderr, "Timeout waiting for high pulse\n");
                gpiod_line_release(line);
                return -1;
            }
        }

        // Determine bit value based on pulse duration
        clock_gettime(CLOCK_MONOTONIC, &start);
        while (gpiod_line_get_value(line) == 0) {
            clock_gettime(CLOCK_MONOTONIC, &end);
            duration = (end.tv_sec - start.tv_sec) * 1000000 + (end.tv_nsec - start.tv_nsec) / 1000;
            if (duration > 100) { // Timeout after 100us
                fprintf(stderr, "Timeout waiting for low pulse\n");
                gpiod_line_release(line);
                return -1;
            }
        }
        clock_gettime(CLOCK_MONOTONIC, &end);
        duration = (end.tv_sec - start.tv_sec) * 1000000 + (end.tv_nsec - start.tv_nsec) / 1000;

        if (duration > DHT11_DATA_BIT_HIGH_1) {
            data[i / 8] |= (1 << (7 - (i % 8)));
        }
    }

    gpiod_line_release(line);

    // Validate checksum
    if ((data[0] + data[1] + data[2] + data[3]) != data[4]) {
        fprintf(stderr, "Checksum error\n");
        return -1;
    }

    *humidity = data[0];
    *temperature = data[2];

    return 0;
}

int main(void)
{
    int humidity, temperature;

    // Install signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize GPIO
    if (initialize_gpio() < 0) {
        fprintf(stderr, "GPIO initialization failed\n");
        return EXIT_FAILURE;
    }

    // Read DHT11 data
    if (read_dht11_data(&humidity, &temperature) == 0) {
        printf("Humidity: %d%%, Temperature: %d°C\n", humidity, temperature);
    } else {
        fprintf(stderr, "Failed to read DHT11 data\n");
        release_gpio();
        return EXIT_FAILURE;
    }

    // Release GPIO resources
    release_gpio();

    return EXIT_SUCCESS;
}

