#include <time.h>

// Define GPIO pins
#define GPIO_2 2
#define GPIO_3 3

// Define GPIO chip name
#define GPIO_CHIP "gpiochip0"

// Define the number of cycles
#define NUM_CYCLES 3

// Define the delay between cycles (seconds)
#define CYCLE_DELAY 5

// Global variables for GPIO lines and chip
struct gpiod_line *gpio_line_2 = NULL;
struct gpiod_line *gpio_line_3 = NULL;
struct gpiod_chip *gpio_chip = NULL;

// Signal handler for Ctrl+C
void signal_handler(int sig) {
    printf("\nCaught signal %d, cleaning up...\n", sig);

    // Release GPIO lines
    if (gpio_line_2) {
        gpiod_line_release(gpio_line_2);
    }
    if (gpio_line_3) {
        gpiod_line_release(gpio_line_3);
    }

    // Close GPIO chip
    if (gpio_chip) {
        gpiod_chip_close(gpio_chip);
    }

    exit(0);
}

// Function to set the GPIO value
int set_gpio_value(struct gpiod_line *line, int value) {
    int ret;

    ret = gpiod_line_set_value(line, value);
    if (ret < 0) {
        fprintf(stderr, "Error setting GPIO value: %d\n", ret);
        return -1;
    }

    return 0;
}

// Function to read the GPIO value
int read_gpio_value(struct gpiod_line *line) {
    int value;

    value = gpiod_line_get_value(line);
    if (value < 0) {
        fprintf(stderr, "Error reading GPIO value: %d\n", value);
        return -1;
    }

    return value;
}

// Function to validate the GPIO reading
int validate_gpio_reading(int value) {
    if (value != 0 && value != 1) {
        fprintf(stderr, "Invalid GPIO reading: %d\n", value);
        return -1;
    }
    return 0;
}

int main() {
    int i, ret;
    int current_value_2, current_value_3;
    int new_value_2, new_value_3;

    // Register signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    // Open GPIO chip
    gpio_chip = gpiod_chip_open_by_name(GPIO_CHIP);
    if (!gpio_chip) {
        fprintf(stderr, "Error opening GPIO chip: %s\n", GPIO_CHIP);
        return 1;
    }

    // Get GPIO lines for GPIO 2 and GPIO 3
    gpio_line_2 = gpiod_chip_get_line(gpio_chip, GPIO_2);
    if (!gpio_line_2) {
        fprintf(stderr, "Error getting GPIO line for GPIO 2\n");
        gpiod_chip_close(gpio_chip);
        return 1;
    }

    gpio_line_3 = gpiod_chip_get_line(gpio_chip, GPIO_3);
    if (!gpio_line_3) {
        fprintf(stderr, "Error getting GPIO line for GPIO 3\n");
        gpiod_line_release(gpio_line_2);
        gpiod_chip_close(gpio_chip);
        return 1;
    }

    // Request GPIO lines for output
    ret = gpiod_line_request_output(gpio_line_2, "gpio_output", 0);
    if (ret < 0) {
        fprintf(stderr, "Error requesting GPIO 2 for output: %d\n", ret);
        gpiod_line_release(gpio_line_2);
        gpiod_line_release(gpio_line_3);
        gpiod_chip_close(gpio_chip);
        return 1;
    }

    ret = gpiod_line_request_output(gpio_line_3, "gpio_output", 0);
    if (ret < 0) {
        fprintf(stderr, "Error requesting GPIO 3 for output: %d\n", ret);
        gpiod_line_release(gpio_line_2);
        gpiod_line_release(gpio_line_3);
        gpiod_chip_close(gpio_chip);
        return 1;
    }

    // Initialize GPIO values
    current_value_2 = 0;
    current_value_3 = 0;

    // Main loop
    for (i = 0; i < NUM_CYCLES; i++) {
        // Calculate new GPIO values
        new_value_2 = (current_value_2 == 0) ? 1 : 0;
        new_value_3 = (current_value_3 == 0) ? 1 : 0;

        // Set GPIO values
        if (set_gpio_value(gpio_line_2, new_value_2) < 0) {
            fprintf(stderr, "Error setting GPIO 2 value, exiting\n");
            goto cleanup;
        }
        if (set_gpio_value(gpio_line_3, new_value_3) < 0) {
            fprintf(stderr, "Error setting GPIO 3 value, exiting\n");
            goto cleanup;
        }

        // Read GPIO values
        int read_value_2 = read_gpio_value(gpio_line_2);
        int read_value_3 = read_gpio_value(gpio_line_3);

        if (read_value_2 < 0 || read_value_3 < 0) {
            fprintf(stderr, "Error reading GPIO values, exiting\n");
            goto cleanup;
        }

        // Validate GPIO readings
        if (validate_gpio_reading(read_value_2) < 0 || validate_gpio_reading(read_value_3) < 0) {
            fprintf(stderr, "Invalid GPIO reading, exiting\n");
            goto cleanup;
        }

        // Report GPIO values
        printf("GPIO 2: %d, GPIO 3: %d\n", read_value_2, read_value_3);

        // Update current GPIO values
        current_value_2 = new_value_2;
        current_value_3 = new_value_3;

        // Wait for the specified delay
        sleep(CYCLE_DELAY);
    }

cleanup:
    // Release GPIO lines
    if (gpio_line_2) {
        gpiod_line_release(gpio_line_2);
    }
    if (gpio_line_3) {
        gpiod_line_release(gpio_line_3);
    }

    // Close GPIO chip
    if (gpio_chip) {
        gpiod_chip_close(gpio_chip);
    }

    return 0;
}

