// Define GPIO pins
#define GPIO_PINS {2, 3, 4, 5, 6, 7, 8, 9, 17}
#define NUM_PINS (sizeof(GPIO_PINS) / sizeof(GPIO_PINS[0]))

// Global variables
struct gpiod_chip *chip;
struct gpiod_line *lines[NUM_PINS];
volatile sig_atomic_t terminate = 0;

// Function prototypes
int initialize_gpio(void);
void set_gpio_output(int pin, int value);
void report_gpio_state(void);
void cleanup_gpio(void);
void signal_handler(int sig);

// Signal handler function
void signal_handler(int sig) {
    if (sig == SIGINT) {
        printf("\nCaught SIGINT, exiting gracefully.\n");
        terminate = 1;
    }
}

// Initialize GPIO pins
int initialize_gpio(void) {
    int i;

    // Open GPIO chip
    chip = gpiod_chip_open_by_name("gpiochip0");
    if (!chip) {
        perror("Error opening GPIO chip");
        return -1;
    }

    // Get line handles for each GPIO pin
    for (i = 0; i < NUM_PINS; i++) {
        lines[i] = gpiod_chip_get_line(chip, GPIO_PINS[i]);
        if (!lines[i]) {
            perror("Error getting line handle");
            cleanup_gpio();
            return -1;
        }

        // Request line as output
        if (gpiod_line_request_output(lines[i], "gpio_output", 0) < 0) {
            perror("Error requesting line as output");
            cleanup_gpio();
            return -1;
        }
    }

    return 0;
}

// Set GPIO pin output value
void set_gpio_output(int pin, int value) {
    int i;
    for (i = 0; i < NUM_PINS; i++) {
        if (GPIO_PINS[i] == pin) {
            if (gpiod_line_set_value(lines[i], value) < 0) {
                perror("Error setting GPIO value");
            }
            return;
        }
    }
    fprintf(stderr, "Error: Invalid GPIO pin number: %d\n", pin);
}

// Report GPIO state
void report_gpio_state(void) {
    int i;
    int value;

    printf("GPIO State:\n");
    for (i = 0; i < NUM_PINS; i++) {
        value = gpiod_line_get_value(lines[i]);
        if (value < 0) {
            perror("Error getting GPIO value");
            continue; // Continue to the next pin
        }
        printf("GPIO %d: %d\n", GPIO_PINS[i], value);
    }
}

// Cleanup GPIO resources
void cleanup_gpio(void) {
    int i;

    // Release GPIO lines
    for (i = 0; i < NUM_PINS; i++) {
        if (lines[i]) {
            gpiod_line_release(lines[i]);
        }
    }

    // Close GPIO chip
    if (chip) {
        gpiod_chip_close(chip);
    }
}

int main(void) {
    int i;

    // Install signal handler
    if (signal(SIGINT, signal_handler) == SIG_ERR) {
        perror("Error installing signal handler");
        return 1;
    }

    // Initialize GPIO
    if (initialize_gpio() < 0) {
        return 1;
    }

    // Main loop
    while (!terminate) {
        // Toggle GPIO pins
        for (i = 0; i < NUM_PINS; i++) {
            int current_value = gpiod_line_get_value(lines[i]);
            if (current_value < 0) {
                perror("Error getting current GPIO value");
                continue; // Continue to the next pin
            }
            set_gpio_output(GPIO_PINS[i], !current_value);
        }

        // Report GPIO state
        report_gpio_state();

        // Wait for 50 milliseconds
        usleep(50000); // 50000 microseconds = 50 milliseconds
    }

    // Cleanup GPIO resources
    cleanup_gpio();

    return 0;
}

