#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <fcntl.h>
#include <unistd.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <signal.h>
#include <errno.h>
#include <string.h>

// Define the I2C bus and address
#define I2C_BUS "/dev/i2c-1"
#define OPT3001_ADDR 0x44

// Define the register addresses
#define RESULT_REG 0x00
#define CONFIG_REG 0x01

// Global variable for I2C file descriptor
int i2c_fd = -1;

// Signal handler for Ctrl+C
void signal_handler(int sig) {
    printf("\nCaught signal %d, cleaning up...\n", sig);
    if (i2c_fd != -1) {
        close(i2c_fd);
    }
    exit(0);
}

// Function to read a 16-bit value from the I2C device
int read_i2c_word(int fd, uint8_t reg) {
    uint8_t buf[2];
    buf[0] = reg;

    if (write(fd, buf, 1) != 1) {
        perror("Failed to write register address");
        return -1;
    }

    if (read(fd, buf, 2) != 2) {
        perror("Failed to read data");
        return -1;
    }

    return (buf[0] << 8) | buf[1];
}

// Function to write a 16-bit value to the I2C device
int write_i2c_word(int fd, uint8_t reg, uint16_t value) {
    uint8_t buf[3];
    buf[0] = reg;
    buf[1] = (value >> 8) & 0xFF;
    buf[2] = value & 0xFF;

    if (write(fd, buf, 3) != 3) {
        perror("Failed to write data");
        return -1;
    }

    return 0;
}

// Function to read the result register
int read_result(int fd) {
    return read_i2c_word(fd, RESULT_REG);
}

// Function to read the configuration register
int read_config(int fd) {
    return read_i2c_word(fd, CONFIG_REG);
}

// Function to write the configuration register
int write_config(int fd, uint16_t config) {
    return write_i2c_word(fd, CONFIG_REG, config);
}

// Function to convert the raw result to lux
float convert_to_lux(uint16_t raw_result) {
    int exponent = (raw_result >> 12) & 0x0F;
    int result = raw_result & 0x0FFF;
    return 0.01 * result * (1 << exponent);
}

int main() {
    // Register the signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    // Open the I2C bus
    i2c_fd = open(I2C_BUS, O_RDWR);
    if (i2c_fd < 0) {
        perror("Failed to open I2C bus");
        return 1;
    }

    // Specify the address of the slave device
    if (ioctl(i2c_fd, I2C_SLAVE, OPT3001_ADDR) < 0) {
        perror("Failed to acquire bus access and/or talk to slave");
        close(i2c_fd);
        return 1;
    }

    // Configure the OPT3001 for continuous conversion mode
    uint16_t config = 0xCB01; // Continuous conversion mode, 100ms conversion time
    if (write_config(i2c_fd, config) < 0) {
        fprintf(stderr, "Failed to write configuration register.\n");
        close(i2c_fd);
        return 1;
    }

    // Main loop to read and print the measurement
    while (1) {
        // Read the result register
        int raw_result = read_result(i2c_fd);
        if (raw_result < 0) {
            fprintf(stderr, "Failed to read result register.\n");
            close(i2c_fd);
            return 1;
        }

        // Convert the raw result to lux
        float lux = convert_to_lux((uint16_t)raw_result);

        // Print the lux value
        printf("Lux: %.2f\n", lux);

        // Wait for 1 second
