void signal_handler(int signal) {
    program_running = 0;
    printf("\nCaught signal %d, exiting gracefully...\n", signal);
}

// Function to set the state of a GPIO pin
int set_gpio_state(int gpio, int state) {
    if (gpioWrite(gpio, state) != 0) {
        fprintf(stderr, "Error setting GPIO %d to state %d\n", gpio, state);
        return -1;
    }
    return 0;
}

// Function to report the state of a GPIO pin
void report_gpio_state(int gpio, int state) {
    printf("GPIO %d: %s\n", gpio, state ? "HIGH" : "LOW");
}

int main() {
    // Initialize pigpio library
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO pins as outputs
    gpioSetMode(GPIO_17, PI_OUTPUT);
    gpioSetMode(GPIO_22, PI_OUTPUT);
    gpioSetMode(GPIO_27, PI_OUTPUT);

    // Register signal handler for SIGINT
    signal(SIGINT, signal_handler);

    // Main loop
    while (program_running) {
        // Set GPIO 17 HIGH
        if (set_gpio_state(GPIO_17, 1) == 0) {
            report_gpio_state(GPIO_17, 1);
        }

        // Set GPIO 22 LOW
        if (set_gpio_state(GPIO_22, 0) == 0) {
            report_gpio_state(GPIO_22, 0);
        }

        // Set GPIO 27 HIGH
        if (set_gpio_state(GPIO_27, 1) == 0) {
            report_gpio_state(GPIO_27, 1);
        }

        // Wait for 0.1 seconds
        gpioDelay(100000); // 100000 microseconds = 0.1 seconds
    }

    // Clean up and terminate pigpio library
    gpioTerminate();
    printf("pigpio terminated.\n");

    return 0;
}

#include <stdio.h>
#include <stdlib.h>
#include <gpiod.h>
#include <unistd.h>
#include <signal.h>
#include <time.h>
#include <errno.h>

// Define GPIO pins
#define GPIO_2 2
#define GPIO_3 3

// Define the valid range for the sensor reading
#define MIN_SENSOR_VALUE 0
#define MAX_SENSOR_VALUE 1023

// Global variables for GPIO lines and chip
struct gpiod_line *gpio_line_2 = NULL;
struct gpiod_line *gpio_line_3 = NULL;
struct gpiod_chip *gpio_chip = NULL;

// Signal handler for Ctrl+C
void signal_handler(int sig) {
    printf("\nCaught signal %d, cleaning up...\n", sig);

    // Set GPIO lines to input (safe state)
    if (gpio_line_2) {
        gpiod_line_set_value(gpio_line_2, 0); // Set to input
    }
    if (gpio_line_3) {
        gpiod_line_set_value(gpio_line_3, 0); // Set to input
    }

    // Release GPIO lines
    if (gpio_line_2) {
        gpiod_line_release(gpio_line_2);
    }
    if (gpio_line_3) {
        gpiod_line_release(gpio_line_3);
    }

    // Close GPIO chip
    if (gpio_chip) {
        gpiod_chip_close(gpio_chip);
    }

    exit(0);
}

// Function to read the sensor value from the specified GPIO pin
int read_sensor(struct gpiod_line *line) {
    int value = gpiod_line_get_value(line);
    if (value < 0) {
        fprintf(stderr, "Error reading GPIO line: %s\n", strerror(-value));
        return -1; // Indicate an error
    }
    return value;
}

// Function to set the output state of the specified GPIO pin
int set_output(struct gpiod_line *line, int state) {
    int ret = gpiod_line_set_value(line, state);
    if (ret < 0) {
        fprintf(stderr, "Error setting GPIO line value: %s\n", strerror(-ret));
        return -1; // Indicate an error
    }
    return 0;
}

// Function to validate the sensor reading
int validate_sensor_reading(int reading) {
    if (reading < MIN_SENSOR_VALUE || reading > MAX_SENSOR_VALUE) {
        fprintf(stderr, "Invalid sensor reading: %d\n", reading);
        return -1; // Indicate an error
    }
    return 0;
}

int main() {
    // Install signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    // Open GPIO chip
    gpio_chip = gpiod_chip_open_by_name("gpiochip0");
    if (!gpio_chip) {
        fprintf(stderr, "Error opening GPIO chip: %s\n", strerror(errno));
        return 1;
    }

    // Get GPIO lines
    gpio_line_2 = gpiod_chip_get_line(gpio_chip, GPIO_2);
    gpio_line_3 = gpiod_chip_get_line(gpio_chip, GPIO_3);

    if (!gpio_line_2 || !gpio_line_3) {
        fprintf(stderr, "Error getting GPIO line: %s\n", strerror(errno));
        gpiod_chip_close(gpio_chip);
        return 1;
    }

    // Request GPIO lines for output
    if (gpiod_line_request_output(gpio_line_2, "output_app", 0) < 0) {
        fprintf(stderr, "Error requesting GPIO line 2 for output: %s\n", strerror(errno));
        gpiod_line_release(gpio_line_2);
        gpiod_line_release(gpio_line_3);
        gpiod_chip_close(gpio_chip);
        return 1;
    }
    if (gpiod_line_request_output(gpio_line_3, "output_app", 0) < 0) {
        fprintf(stderr, "Error requesting GPIO line 3 for output: %s\n", strerror(errno));
        gpiod_line_release(gpio_line_2);
        gpiod_line_release(gpio_line_3);
        gpiod_chip_close(gpio_chip);
        return 1;
    }

    // Main loop
    while (1) {
        // Read sensor value from GPIO 2
        int sensor_value = read_sensor(gpio_line_2);
        if (sensor_value < 0) {
            fprintf(stderr, "Error reading sensor value, exiting.\n");
            break;
        }

        // Validate sensor reading
        if (validate_sensor_reading(sensor_value) < 0) {
            fprintf(stderr, "Invalid sensor reading, skipping output.\n");
            continue; // Skip to the next iteration
        }

        // Set GPIO 3 output based on sensor value
        if (sensor_value > 511) {
            if (set_output(gpio_line_3, 1) < 0) {
                fprintf(stderr, "Error setting GPIO 3 output, exiting.\n");
                break;
            }
            printf("GPIO 3 set to HIGH\n");
        } else {
            if (set_output(gpio_line_3, 0) < 0) {
                fprintf(stderr, "Error setting GPIO 3 output, exiting.\n");
                break;
            }
            printf("GPIO 3 set to LOW\n");
        }

        // Wait for 0.1 seconds
        struct timespec sleep_time;
        sleep_time.tv_sec = 0;
        sleep_time.tv_nsec = 100 * 1000 * 1000; // 100 milliseconds
        nanosleep(&sleep_time, NULL);
    }

    // Cleanup (should not reach here if signal handler works correctly)
    gpiod_line_release(gpio_line_2);
    gpiod_line_release(gpio_line_3);
    gpiod_chip_close(gpio_chip);

    return 0;
}

