#include <time.h>

#define GPIO_PIN 2
#define GPIO_CHIP "gpiochip0"

static struct gpiod_chip *chip;
static struct gpiod_line *line;
static volatile sig_atomic_t terminate = 0;

void signal_handler(int sig) {
    terminate = 1;
}

int main() {
    int i, ret;

    // Register signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    // Open GPIO chip
    chip = gpiod_chip_open_by_name(GPIO_CHIP);
    if (!chip) {
        perror("Error opening GPIO chip");
        return 1;
    }

    // Get GPIO line
    line = gpiod_chip_get_line(chip, GPIO_PIN);
    if (!line) {
        perror("Error getting GPIO line");
        gpiod_chip_close(chip);
        return 1;
    }

    // Request GPIO line for output
    ret = gpiod_line_request_output(line, "gpio-output", 0);
    if (ret < 0) {
        perror("Error requesting GPIO line for output");
        gpiod_chip_close(chip);
        return 1;
    }

    // Main loop
    for (i = 0; i < 3 && !terminate; i++) {
        // Set GPIO high
        ret = gpiod_line_set_value(line, 1);
        if (ret < 0) {
            perror("Error setting GPIO high");
            break;
        }
        printf("GPIO %d set to HIGH\n", GPIO_PIN);

        // Wait for 0.1 seconds
        struct timespec ts;
        ts.tv_sec = 0;
        ts.tv_nsec = 100 * 1000 * 1000; // 100 milliseconds
        nanosleep(&ts, NULL);

        // Set GPIO low
        ret = gpiod_line_set_value(line, 0);
        if (ret < 0) {
            perror("Error setting GPIO low");
            break;
        }
        printf("GPIO %d set to LOW\n", GPIO_PIN);

        // Wait for 0.1 seconds
        nanosleep(&ts, NULL);
    }

    // Release GPIO line
    gpiod_line_release(line);

    // Close GPIO chip
    gpiod_chip_close(chip);

    printf("Program terminated gracefully.\n");
    return 0;
}

#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

// Define GPIO pins
#define GPIO_4 4
#define GPIO_12 12
#define GPIO_18 18

// Define PWM frequency
#define PWM_FREQUENCY 1000

// Global variable to indicate program termination
volatile sig_atomic_t program_running = 1;

// Signal handler for SIGINT (Ctrl+C)
void signal_handler(int signal) {
    program_running = 0;
    printf("\nCaught signal %d, exiting gracefully...\n", signal);
}

int main() {
    // Initialize pigpio library
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO pins as outputs
    gpioSetMode(GPIO_4, PI_OUTPUT);
    gpioSetMode(GPIO_12, PI_OUTPUT);
    gpioSetMode(GPIO_18, PI_OUTPUT);

    // Set PWM frequency
    gpioSetPWMfrequency(GPIO_4, PWM_FREQUENCY);
    gpioSetPWMfrequency(GPIO_12, PWM_FREQUENCY);
    gpioSetPWMfrequency(GPIO_18, PWM_FREQUENCY);

    // Set PWM range (0-255)
    gpioSetPWMrange(GPIO_4, 255);
    gpioSetPWMrange(GPIO_12, 255);
    gpioSetPWMrange(GPIO_18, 255);

    // Register signal handler for SIGINT
    signal(SIGINT, signal_handler);

    // Main loop
    while (program_running) {
        // Set PWM duty cycle to 128 (50%)
        gpioPWM(GPIO_4, 128);
        gpioPWM(GPIO_12, 128);
        gpioPWM(GPIO_18, 128);

        // Report the state
        printf("GPIO 4: PWM = 128, GPIO 12: PWM = 128, GPIO 18: PWM = 128\n");

        // Wait for 1 second
        sleep(1);

        // Set PWM duty cycle to 0 (0%)
        gpioPWM(GPIO_4, 0);
        gpioPWM(GPIO_12, 0);
        gpioPWM(GPIO_18, 0);

        // Report the state
        printf("GPIO 4: PWM = 0, GPIO 12: PWM = 0, GPIO 18: PWM = 0\n");

        // Wait for 1 second
        sleep(1);
    }

    // Stop PWM on all GPIO pins
    gpioPWM(GPIO_4, 0);
    gpioPWM(GPIO_12, 0);
    gpioPWM(GPIO_18, 0);

    // Release GPIO pins
    gpioSetMode(GPIO_4, PI_INPUT); // Set to input to release
    gpioSetMode(GPIO_12, PI_INPUT); // Set to input to release
    gpioSetMode(GPIO_18, PI_INPUT); // Set to input to release

    // Terminate pigpio library
    gpioTerminate();

    return 0;
}

