#define PWM_RANGE 1000

// Global variable to indicate program termination
volatile sig_atomic_t program_running = 1;

// Signal handler for Ctrl+C
void signal_handler(int signal) {
    program_running = 0;
    printf("\nCaught signal %d, exiting gracefully...\n", signal);
}

// Function to set the PWM duty cycle for a given GPIO pin
void set_pwm_duty_cycle(int gpio, int duty_cycle) {
    gpioPWM(gpio, duty_cycle);
}

// Function to report the PWM state for a given GPIO pin
void report_pwm_state(int gpio, int duty_cycle) {
    printf("GPIO %d: Duty Cycle = %d\n", gpio, duty_cycle);
}

int main() {
    // Initialize pigpio library
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO pins as outputs
    gpioSetMode(GPIO_17, PI_OUTPUT);
    gpioSetMode(GPIO_18, PI_OUTPUT);
    gpioSetMode(GPIO_27, PI_OUTPUT);

    // Set PWM frequency for all GPIO pins
    gpioSetPWMfrequency(GPIO_17, PWM_FREQUENCY);
    gpioSetPWMfrequency(GPIO_18, PWM_FREQUENCY);
    gpioSetPWMfrequency(GPIO_27, PWM_FREQUENCY);

    // Set PWM range for all GPIO pins
    gpioSetPWMrange(GPIO_17, PWM_RANGE);
    gpioSetPWMrange(GPIO_18, PWM_RANGE);
    gpioSetPWMrange(GPIO_27, PWM_RANGE);

    // Register signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    // Main loop
    while (program_running) {
        // Set PWM duty cycles for GPIO 17, 18, and 27
        set_pwm_duty_cycle(GPIO_17, 250);
        set_pwm_duty_cycle(GPIO_18, 500);
        set_pwm_duty_cycle(GPIO_27, 750);

