// Function to discover DS18B20 devices
int discover_devices() {
    DIR *dir;
    struct dirent *ent;
    int i = 0;

    dir = opendir(W1_DEVICES_DIR);
    if (dir == NULL) {
        perror("Error opening w1 devices directory");
        return -1;
    }

    while ((ent = readdir(dir)) != NULL && i < MAX_DEVICES) {
        if (strncmp(ent->d_name, "28-", 3) == 0) {
            strncpy(devices[i].id, ent->d_name, sizeof(devices[i].id) - 1);
            devices[i].id[sizeof(devices[i].id) - 1] = '\0'; // Ensure null termination
            snprintf(devices[i].path, sizeof(devices[i].path), "%s%s/%s", W1_DEVICES_DIR, devices[i].id, W1_SLAVE_FILE);
            i++;
        }
    }
    closedir(dir);
    num_devices = i;
    return 0;
}

// Function to read temperature from a DS18B20 device
int read_temperature(const char *device_id, float *temperature) {
    int fd;
    char buf[256];
    ssize_t num_read;
    char *temp_str;
    long temp_raw;

    fd = open(devices[0].path, O_RDONLY); // Use the first device's path
    if (fd == -1) {
        perror("Error opening w1 slave file");
        return -1;
    }

    num_read = read(fd, buf, sizeof(buf) - 1);
    if (num_read == -1) {
        perror("Error reading w1 slave file");
        close(fd);
        return -1;
    }
    buf[num_read] = '\0';

    close(fd);

    // Check for CRC error
    if (strstr(buf, "YES") == NULL) {
        fprintf(stderr, "CRC check failed for device %s\n", device_id);
        return -1;
    }

    // Extract temperature from the string
    temp_str = strstr(buf, "t=");
    if (temp_str == NULL) {
        fprintf(stderr, "Temperature data not found in device %s\n", device_id);
        return -1;
    }

    temp_raw = strtol(temp_str + 2, NULL, 10);
    *temperature = (float)temp_raw / 1000.0;

    return 0;
}

