// HTU21D I2C address
#define HTU21D_ADDR 0x40

// HTU21D commands
#define HTU21D_TEMP_MEASURE 0xE3
#define HTU21D_HUMID_MEASURE 0xE5

// Global variable for I2C file descriptor
int i2c_fd = -1;

// Signal handler for Ctrl+C
void signal_handler(int sig) {
    printf("\nExiting program...\n");
    if (i2c_fd != -1) {
        close(i2c_fd);
    }
    exit(0);
}

// Function to read a 16-bit value from the I2C device
int read_i2c_word(int fd, uint8_t command) {
    uint8_t buf[2];
    int result;

    // Write the command to the device
    if (write(fd, &command, 1) != 1) {
        perror("Failed to write to I2C device");
        return -1;
    }

    // Read two bytes from the device
    result = read(fd, buf, 2);
    if (result != 2) {
        perror("Failed to read from I2C device");
        return -1;
    }

    // Combine the bytes into a 16-bit value
    return (buf[0] << 8) | buf[1];
}

// Function to calculate the temperature in Celsius
float calculate_temperature(uint16_t raw_temperature) {
    return -46.85 + 175.72 * (raw_temperature / 65536.0);
}

// Function to calculate the relative humidity
float calculate_humidity(uint16_t raw_humidity) {
    return -6.0 + 125.0 * (raw_humidity / 65536.0);
}

// Function to validate the temperature reading
int validate_temperature(float temperature) {
    return (temperature >= -40.0 && temperature <= 125.0);
}

// Function to validate the humidity reading
int validate_humidity(float humidity) {
    return (humidity >= 0.0 && humidity <= 100.0);
}

int main() {
    // Register the signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    // Open the I2C device
    i2c_fd = open("/dev/i2c-1", O_RDWR);
    if (i2c_fd < 0) {
        perror("Failed to open I2C device");
        return 1;
    }

    // Set the I2C slave address
    if (ioctl(i2c_fd, I2C_SLAVE, HTU21D_ADDR) < 0) {
        perror("Failed to set I2C slave address");
        close(i2c_fd);
        return 1;
    }

    // Main loop
    while (1) {
        // Read the temperature
        int raw_temperature = read_i2c_word(i2c_fd, HTU21D_TEMP_MEASURE);
        if (raw_temperature < 0) {
            fprintf(stderr, "Failed to read temperature. Retrying in 60 seconds.\n");
            sleep(60);
            continue;
        }

        // Read the humidity
        int raw_humidity = read_i2c_word(i2c_fd, HTU21D_HUMID_MEASURE);
        if (raw_humidity < 0) {
            fprintf(stderr, "Failed to read humidity. Retrying in 60 seconds.\n");
            sleep(60);
            continue;
        }

        // Calculate the temperature and humidity
        float temperature = calculate_temperature(raw_temperature);
        float humidity = calculate_humidity(raw_humidity);

        // Validate the readings
        if (!validate_temperature(temperature)) {
            fprintf(stderr, "Invalid temperature reading: %.2f\n", temperature);
            sleep(60);
            continue;
        }

        if (!validate_humidity(humidity)) {
            fprintf(stderr, "Invalid humidity reading: %.2f\n", humidity);
            sleep(60);
            continue;
        }

        // Print the temperature and humidity
        printf("Temperature: %.2f C, Humidity: %.2f %%\n", temperature, humidity);

        // Wait for 60 seconds
        sleep(60);
    }

    // The program should never reach here due to the infinite loop,
    // but include cleanup for completeness.
    close(i2c_fd);
    return 0;
}

