    printf("\nExiting program...\n");
    if (i2c_fd != -1) {
        // Disable ADXL345 (optional, but good practice)
        uint8_t power_ctl = 0x00; // Standby mode
        if (write_i2c_reg(i2c_fd, ADXL345_POWER_CTL, power_ctl) < 0) {
            fprintf(stderr, "Error disabling ADXL345: %s\n", strerror(errno));
        }
        close(i2c_fd);
    }
    exit(0);
}

// Function to write a byte to an I2C register
int write_i2c_reg(int fd, uint8_t reg, uint8_t value) {
    uint8_t buf[2];
    buf[0] = reg;
    buf[1] = value;
    if (write(fd, buf, 2) != 2) {
        fprintf(stderr, "Error writing to I2C device: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

// Function to read a byte from an I2C register
int read_i2c_reg(int fd, uint8_t reg, uint8_t *value) {
    if (write(fd, &reg, 1) != 1) {
        fprintf(stderr, "Error writing register address: %s\n", strerror(errno));
        return -1;
    }
    if (read(fd, value, 1) != 1) {
        fprintf(stderr, "Error reading from I2C device: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

// Function to read acceleration data from ADXL345
int read_acceleration(int fd, int16_t *x, int16_t *y, int16_t *z) {
    uint8_t data[6];

    // Read all six bytes at once
    if (write(fd, (uint8_t[]){ADXL345_DATAX0}, 1) != 1) {
        fprintf(stderr, "Error writing register address for multi-read: %s\n", strerror(errno));
        return -1;
    }

    if (read(fd, data, 6) != 6) {
        fprintf(stderr, "Error reading acceleration data: %s\n", strerror(errno));
        return -1;
    }

    // Combine high and low bytes for each axis
    *x = (int16_t)((data[1] << 8) | data[0]);
    *y = (int16_t)((data[3] << 8) | data[2]);
    *z = (int16_t)((data[5] << 8) | data[4]);

    return 0;
}

