        gpioDelay(1);
        timeout++;
        if (timeout > 100) return -1; // Timeout error
    }

    // Read the 40 bits of data
    for (i = 0; i < 40; i++) {
        timeout = 0;
        while (gpioRead(gpio_pin) == 0) {
            gpioDelay(1);
            timeout++;
            if (timeout > 100) return -1; // Timeout error
        }

        long start = gpioTick();
        timeout = 0;
        while (gpioRead(gpio_pin) == 1) {
            gpioDelay(1);
            timeout++;
            if (timeout > 100) return -1; // Timeout error
        }
        long end = gpioTick();

        if ((end - start) > 40) {
            data[bit_count / 8] |= (1 << (7 - (bit_count % 8)));
        }
        bit_count++;
    }

    // Verify checksum
    if ((data[0] + data[1] + data[2] + data[3]) != data[4]) {
        return -2; // Checksum error
    }

    // Convert data to temperature and humidity
    *humidity = (float)(((data[0] << 8) + data[1])) / 10.0;
    *temperature = (float)(((data[2] << 8) + data[3])) / 10.0;
    if (*temperature > 125) {
        *temperature = *temperature - 256;
    }

    return 0; // Success
}

// Function to process sensor data
void process_sensor_data(DHT22SensorData *sensor_data) {
    float temperature, humidity;
    int result = read_dht22(sensor_data->gpio_pin, &temperature, &humidity);

    if (result == 0) {
        sensor_data->temperature = temperature;
        sensor_data->humidity = humidity;
        sensor_data->valid = 1;
    } else {
        sensor_data->temperature = -999.0; // Indicate error
        sensor_data->humidity = -999.0;    // Indicate error
        sensor_data->valid = 0;
        fprintf(stderr, "Error reading sensor on GPIO %d: %d\n", sensor_data->gpio_pin, result);
    }
}

// Function to report sensor data
void report_sensor_data(DHT22SensorData sensor_data) {
    if (sensor_data.valid) {
        printf("GPIO %d: Temperature = %.1f C, Humidity = %.1f %%\n", sensor_data.gpio_pin, sensor_data.temperature, sensor_data.humidity);
    } else {
        printf("GPIO %d: Sensor data invalid\n", sensor_data.gpio_pin);
    }
}

int main() {
    // Initialize pigpio library
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Register signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    // Define DHT22 sensor data structures
    DHT22SensorData sensor1 = {DHT22_PIN_1, 0.0, 0.0, 0};
    DHT22SensorData sensor2 = {DHT22_PIN_2, 0.0, 0.0, 0};
    DHT22SensorData sensor3 = {DHT22_PIN_3, 0.0, 0.0, 0};
    DHT22SensorData sensor4 = {DHT22_PIN_4, 0.0, 0.0, 0};

    // Main loop
    while (program_running) {
        // Process sensor data
        process_sensor_data(&sensor1);
        process_sensor_data(&sensor2);
        process_sensor_data(&sensor3);
        process_sensor_data(&sensor4);

        // Report sensor data
        report_sensor_data(sensor1);
        report_sensor_data(sensor2);
        report_sensor_data(sensor3);
        report_sensor_data(sensor4);

        // Wait for 2 seconds
        sleep(2);
    }

    // Release GPIO resources
    gpioTerminate();

    return 0;
}

