// Global variables for GPIO lines and chip
struct gpiod_line *gpio_line_17 = NULL;
struct gpiod_line *gpio_line_27 = NULL;
struct gpiod_chip *gpio_chip = NULL;

// Signal handler for Ctrl+C
void signal_handler(int sig) {
    printf("\nCaught signal %d, cleaning up...\n", sig);

    // Release GPIO lines
    if (gpio_line_17) {
        gpiod_line_release(gpio_line_17);
    }
    if (gpio_line_27) {
        gpiod_line_release(gpio_line_27);
    }

    // Close GPIO chip
    if (gpio_chip) {
        gpiod_chip_close(gpio_chip);
    }

    exit(0);
}

int main() {
    // Register signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    // Open GPIO chip
    gpio_chip = gpiod_chip_open_by_name("gpiochip0");
    if (!gpio_chip) {
        fprintf(stderr, "Error opening GPIO chip: %s\n", strerror(errno));
        return 1;
    }

    // Get GPIO lines for GPIO 17 and GPIO 27
    gpio_line_17 = gpiod_chip_get_line(gpio_chip, GPIO_17);
    if (!gpio_line_17) {
        fprintf(stderr, "Error getting GPIO line %d: %s\n", GPIO_17, strerror(errno));
        gpiod_chip_close(gpio_chip);
        return 1;
    }

    gpio_line_27 = gpiod_chip_get_line(gpio_chip, GPIO_27);
    if (!gpio_line_27) {
        fprintf(stderr, "Error getting GPIO line %d: %s\n", GPIO_27, strerror(errno));
        gpiod_line_release(gpio_line_17);
        gpiod_chip_close(gpio_chip);
        return 1;
    }

    // Request GPIO lines for output
    if (gpiod_line_request_output(gpio_line_17, "gpio_output", 0) < 0) {
        fprintf(stderr, "Error requesting GPIO line %d for output: %s\n", GPIO_17, strerror(errno));
        gpiod_line_release(gpio_line_17);
        gpiod_line_release(gpio_line_27);
        gpiod_chip_close(gpio_chip);
        return 1;
    }

    if (gpiod_line_request_output(gpio_line_27, "gpio_output", 0) < 0) {
        fprintf(stderr, "Error requesting GPIO line %d for output: %s\n", GPIO_27, strerror(errno));
        gpiod_line_release(gpio_line_17);
        gpiod_line_release(gpio_line_27);
        gpiod_chip_close(gpio_chip);
        return 1;
    }

    // Main loop
    while (1) {
        // Set GPIO 17 HIGH
        if (gpiod_line_set_value(gpio_line_17, 1) < 0) {
            fprintf(stderr, "Error setting GPIO line %d HIGH: %s\n", GPIO_17, strerror(errno));
            break; // Exit loop on error
        }
        printf("GPIO %d set HIGH\n", GPIO_17);

        // Set GPIO 27 LOW
        if (gpiod_line_set_value(gpio_line_27, 0) < 0) {
            fprintf(stderr, "Error setting GPIO line %d LOW: %s\n", GPIO_27, strerror(errno));
            break; // Exit loop on error
        }
        printf("GPIO %d set LOW\n", GPIO_27);

        sleep(1);

        // Set GPIO 17 LOW
        if (gpiod_line_set_value(gpio_line_17, 0) < 0) {
            fprintf(stderr, "Error setting GPIO line %d LOW: %s\n", GPIO_17, strerror(errno));
            break; // Exit loop on error
        }
        printf("GPIO %d set LOW\n", GPIO_17);

        // Set GPIO 27 HIGH
        if (gpiod_line_set_value(gpio_line_27, 1) < 0) {
            fprintf(stderr, "Error setting GPIO line %d HIGH: %s\n", GPIO_27, strerror(errno));
            break; // Exit loop on error
        }
        printf("GPIO %d set HIGH\n", GPIO_27);

        sleep(1);
    }

    // Cleanup (should not reach here if signal handler works correctly)
    gpiod_line_release(gpio_line_17);
    gpiod_line_release(gpio_line_27);
    gpiod_chip_close(gpio_chip);

    return 1;
}

