#define GPIO_PIN 18
#define PWM_FREQUENCY 1000
#define PWM_RANGE 1000

volatile sig_atomic_t program_running = 1;

void signal_handler(int signal) {
    program_running = 0;
    printf("\nCaught signal %d, exiting gracefully...\n", signal);
}

int main() {
    int duty_cycle;

    // Register signal handlers for graceful shutdown
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize pigpio library
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO 18 as output
    gpioSetMode(GPIO_PIN, PI_OUTPUT);

    // Set PWM frequency
    gpioSetPWMfrequency(GPIO_PIN, PWM_FREQUENCY);

    // Set PWM range
    gpioSetPWMrange(GPIO_PIN, PWM_RANGE);

    printf("PWM output on GPIO %d started. Press Ctrl+C to exit.\n", GPIO_PIN);

    while (program_running) {
        // Cycle through duty cycles from 0 to 1000
        for (duty_cycle = 0; duty_cycle <= PWM_RANGE; duty_cycle++) {
            gpioPWM(GPIO_PIN, duty_cycle);
            printf("Duty Cycle: %d\n", duty_cycle);
            usleep(20000); // 20ms delay
        }

        // Cycle through duty cycles from 1000 to 0
        for (duty_cycle = PWM_RANGE; duty_cycle >= 0; duty_cycle--) {
            gpioPWM(GPIO_PIN, duty_cycle);
            printf("Duty Cycle: %d\n", duty_cycle);
            usleep(20000); // 20ms delay
        }
    }

    // Stop PWM output
    gpioPWM(GPIO_PIN, 0);

    // Release GPIO resources
    gpioTerminate();

    printf("PWM output stopped. GPIO %d released.\n", GPIO_PIN);

    return 0;
}

