#include <errno.h>
#include <string.h>

// TCS34725 I2C address
#define TCS34725_ADDRESS 0x29

// TCS34725 Registers
#define TCS34725_ENABLE 0x80
#define TCS34725_ATIME 0x81
#define TCS34725_CONTROL 0x8F
#define TCS34725_CDATA 0x94
#define TCS34725_RDATA 0x96
#define TCS34725_GDATA 0x98
#define TCS34725_BDATA 0x9A

// Global variables
int i2c_fd;
volatile sig_atomic_t program_running = 1;

// Function prototypes
int i2c_read_register(int fd, uint8_t reg);
int i2c_write_register(int fd, uint8_t reg, uint8_t value);
int tcs34725_init(int fd);
int tcs34725_read_data(int fd, uint16_t *clear, uint16_t *red, uint16_t *green, uint16_t *blue);
void signal_handler(int signal);

// I2C read register function
int i2c_read_register(int fd, uint8_t reg) {
    if (write(fd, &reg, 1) != 1) {
        perror("Failed to write register address");
        return -1;
    }
    uint8_t value;
    if (read(fd, &value, 1) != 1) {
        perror("Failed to read register value");
        return -1;
    }
    return value;
}

// I2C write register function
int i2c_write_register(int fd, uint8_t reg, uint8_t value) {
    uint8_t buf[2];
    buf[0] = reg;
    buf[1] = value;
    if (write(fd, buf, 2) != 2) {
        perror("Failed to write register value");
        return -1;
    }
    return 0;
}

// TCS34725 initialization function
int tcs34725_init(int fd) {
    // Enable power and ALS (Ambient Light Sensing)
    if (i2c_write_register(fd, TCS34725_ENABLE, 0x03) != 0) {
        fprintf(stderr, "Failed to enable TCS34725\n");
        return -1;
    }

    // Set integration time (ATIME) - Adjust as needed
    if (i2c_write_register(fd, TCS34725_ATIME, 0xD5) != 0) { // 101ms integration time
        fprintf(stderr, "Failed to set integration time\n");
        return -1;
    }

    // Set gain (AGAIN) - Adjust as needed
    if (i2c_write_register(fd, TCS34725_CONTROL, 0x01) != 0) { // 4x gain
        fprintf(stderr, "Failed to set gain\n");
        return -1;
    }

    return 0;
}

// TCS34725 read data function
int tcs34725_read_data(int fd, uint16_t *clear, uint16_t *red, uint16_t *green, uint16_t *blue) {
    uint8_t data[8];
    uint8_t reg = TCS34725_CDATA;

    if (write(fd, &reg, 1) != 1) {
        perror("Failed to write register address for data read");
        return -1;
    }

    if (read(fd, data, 8) != 8) {
        perror("Failed to read data");
        return -1;
    }

    *clear = (data[1] << 8) | data[0];
    *red   = (data[3] << 8) | data[2];
    *green = (data[5] << 8) | data[4];
    *blue  = (data[7] << 8) | data[6];

    return 0;
}

// Signal handler for Ctrl+C
void signal_handler(int signal) {
    program_running = 0;
    printf("\nExiting program...\n");
}

int main() {
    // Register signal handler
    signal(SIGINT, signal_handler);

    // Open I2C device
    i2c_fd = open("/dev/i2c-1", O_RDWR);
    if (i2c_fd < 0) {
        perror("Failed to open I2C device");
        return 1;
    }

    // Specify slave address
    if (ioctl(i2c_fd, I2C_SLAVE, TCS34725_ADDRESS) < 0) {
        perror("Failed to acquire bus access and/or talk to slave");
        close(i2c_fd);
        return 1;
    }

    // Initialize TCS34725
    if (tcs34725_init(i2c_fd) != 0) {
        fprintf(stderr, "TCS34725 initialization failed\n");
        close(i2c_fd);
        return 1;
    }

    printf("TCS34725 initialized successfully\n");

    // Main loop
    uint16_t clear, red, green, blue;
    while (program_running) {
        if (tcs34725_read_data(i2c_fd, &clear, &red, &green, &blue) == 0) {
            printf("Clear: %5u, Red: %5u, Green: %5u, Blue: %5u\n", clear, red, green, blue);
        } else {
            fprintf(stderr, "Failed to read TCS34725 data\n");
        }
        usleep(200000); // 0.2 seconds
    }

    // Close I2C device
    close(i2c_fd);

    return 0;
}

#include <stdio.h>
#include <stdlib.h>
#include <gpiod.h>
#include <unistd.h>
#include <signal.h>
#include <errno.h>

// Define GPIO pins
#define GPIO_18 18
#define GPIO_21 21
#define GPIO_22 22

// Global variables for GPIO lines and chip
struct gpiod_line *gpio_line_18 = NULL;
struct gpiod_line *gpio_line_21 = NULL;
struct gpiod_line *gpio_line_22 = NULL;
struct gpiod_chip *gpio_chip = NULL;

// Signal handler for Ctrl+C
void signal_handler(int sig) {
    printf("\nCaught signal %d, cleaning up...\n", sig);

    // Release GPIO lines
    if (gpio_line_18) {
        gpiod_line_release(gpio_line_18);
    }
    if (gpio_line_21) {
        gpiod_line_release(gpio_line_21);
    }
    if (gpio_line_22) {
        gpiod_line_release(gpio_line_22);
    }

    // Close GPIO chip
    if (gpio_chip) {
        gpiod_chip_close(gpio_chip);
    }

    exit(0);
}

int main() {
    // Register signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    // Open GPIO chip
    gpio_chip = gpiod_chip_open_by_name("gpiochip0");
    if (!gpio_chip) {
        perror("Error opening GPIO chip");
        return 1;
    }

    // Get GPIO lines
    gpio_line_18 = gpiod_chip_get_line(gpio_chip, GPIO_18);
    gpio_line_21 = gpiod_chip_get_line(gpio_chip, GPIO_21);
    gpio_line_22 = gpiod_chip_get_line(gpio_chip, GPIO_22);

    if (!gpio_line_18 || !gpio_line_21 || !gpio_line_22) {
        perror("Error getting GPIO line");
        if (gpio_line_18) gpiod_line_release(gpio_line_18);
        if (gpio_line_21) gpiod_line_release(gpio_line_21);
        if (gpio_line_22) gpiod_line_release(gpio_line_22);
        gpiod_chip_close(gpio_chip);
        return 1;
    }

    // Request GPIO lines for output
    if (gpiod_line_request_output(gpio_line_18, "gpio_output", 0) < 0) {
        perror("Error requesting GPIO 18 for output");
        gpiod_line_release(gpio_line_18);
        gpiod_line_release(gpio_line_21);
        gpiod_line_release(gpio_line_22);
        gpiod_chip_close(gpio_chip);
        return 1;
    }
    if (gpiod_line_request_output(gpio_line_21, "gpio_output", 0) < 0) {
        perror("Error requesting GPIO 21 for output");
        gpiod_line_release(gpio_line_18);
        gpiod_line_release(gpio_line_21);
        gpiod_line_release(gpio_line_22);
        gpiod_chip_close(gpio_chip);
        return 1;
    }
    if (gpiod_line_request_output(gpio_line_22, "gpio_output", 0) < 0) {
        perror("Error requesting GPIO 22 for output");
        gpiod_line_release(gpio_line_18);
        gpiod_line_release(gpio_line_21);
        gpiod_line_release(gpio_line_22);
        gpiod_chip_close(gpio_chip);
        return 1;
    }

    // Set GPIO 18 to HIGH
    if (gpiod_line_set_value(gpio_line_18, 1) < 0) {
        perror("Error setting GPIO 18 HIGH");
        gpiod_line_release(gpio_line_18);
        gpiod_line_release(gpio_line_21);
        gpiod_line_release(gpio_line_22);
        gpiod_chip_close(gpio_chip);
        return 1;
    }
    printf("GPIO 18 set to HIGH\n");

    // Set GPIO 21 to LOW
    if (gpiod_line_set_value(gpio_line_21, 0) < 0) {
        perror("Error setting GPIO 21 LOW");
        gpiod_line_release(gpio_line_18);
        gpiod_line_release(gpio_line_21);
        gpiod_line_release(gpio_line_22);
        gpiod_chip_close(gpio_chip);
        return 1;
    }
    printf("GPIO 21 set to LOW\n");

    // Set GPIO 22 to HIGH
    if (gpiod_line_set_value(gpio_line_22, 1) < 0) {
        perror("Error setting GPIO 22 HIGH");
        gpiod_line_release(gpio_line_18);
        gpiod_line_release(gpio_line_21);
        gpiod_line_release(gpio_line_22);
        gpiod_chip_close(gpio_chip);
        return 1;
    }
    printf("GPIO 22 set to HIGH\n");

    // Wait for 5 seconds
    sleep(5);

    // Release GPIO lines
    gpiod_line_release(gpio_line_18);
    gpiod_line_release(gpio_line_21);
    gpiod_line_release(gpio_line_22);

    // Close GPIO chip
    gpiod_chip_close(gpio_chip);

    printf("GPIO lines released. Exiting.\n");

    return 0;
}

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <fcntl.h>
#include <unistd.h>
#include <sys/ioctl.h>
#include <sys/mman.h>
#include <linux/videodev2.h>
#include <errno.h>
#include <signal.h>
#include <time.h>

#define DEVICE_NAME "/dev/video0"
#define IMAGE_WIDTH 640
#define IMAGE_HEIGHT 480
#define IMAGE_FORMAT V4L2_PIX_FMT_YUYV
#define NUM_BUFFERS 4

// Structure to hold buffer information
typedef struct {
    void   *start;
    size_t  length;
} buffer;

static buffer *buffers = NULL;
static int fd = -1;
static int running = 1;

// Signal handler for Ctrl+C
void signal_handler(int sig)
{
    running = 0;
    printf("\nCaught signal %d, exiting...\n", sig);
}

// Function to initialize the camera
int init_camera(const char *device_name)
{
    struct v4l2_capability cap;
    struct v4l2_format fmt;
    struct v4l2_requestbuffers req;
    int i;

    fd = open(device_name, O_RDWR | O_NONBLOCK, 0);
    if (fd < 0) {
        perror("Error opening device");
        return -1;
    }

    if (ioctl(fd, VIDIOC_QUERYCAP, &cap) < 0) {
        perror("Error querying capabilities");
        close(fd);
        return -1;
    }

    if (!(cap.capabilities & V4L2_CAP_VIDEO_CAPTURE)) {
        fprintf(stderr, "%s is not a video capture device\n", device_name);
        close(fd);
        return -1;
    }

    if (!(cap.capabilities & V4L2_CAP_STREAMING)) {
        fprintf(stderr, "%s does not support streaming i/o\n", device_name);
        close(fd);
        return -1;
    }

    memset(&fmt, 0, sizeof(fmt));
    fmt.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    fmt.fmt.pix.width = IMAGE_WIDTH;
    fmt.fmt.pix.height = IMAGE_HEIGHT;
    fmt.fmt.pix.pixelformat = IMAGE_FORMAT;
    fmt.fmt.pix.field = V4L2_FIELD_INTERLACED;

    if (ioctl(fd, VIDIOC_S_FMT, &fmt) < 0) {
        perror("Error setting format");
        close(fd);
        return -1;
    }

    memset(&req, 0, sizeof(req));
    req.count = NUM_BUFFERS;
    req.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    req.memory = V4L2_MEMORY_MMAP;

    if (ioctl(fd, VIDIOC_REQBUFS, &req) < 0) {
        perror("Error requesting buffers");
        close(fd);
        return -1;
    }

    buffers = calloc(req.count, sizeof(*buffers));
    if (!buffers) {
        perror("Out of memory");
        close(fd);
        return -1;
    }

    for (i = 0; i < req.count; ++i) {
        struct v4l2_buffer buf;

        memset(&buf, 0, sizeof(buf));
        buf.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
        buf.memory = V4L2_MEMORY_MMAP;
        buf.index = i;

        if (ioctl(fd, VIDIOC_QUERYBUF, &buf) < 0) {
            perror("Error querying buffer");
            close(fd);
            free(buffers);
            return -1;
        }

        buffers[i].length = buf.length;
        buffers[i].start = mmap(NULL, buf.length, PROT_READ | PROT_WRITE, MAP_SHARED, fd, buf.m.offset);

        if (buffers[i].start == MAP_FAILED) {
            perror("Error mapping buffer");
            close(fd);
            free(buffers);
            return -1;
        }
    }

    return 0;
}

// Function to capture an image
int capture_image(const char *filename)
{
    struct v4l2_buffer buf;
    int i;

    for (i = 0; i < NUM_BUFFERS; ++i) {
        memset(&buf, 0, sizeof(buf));
        buf.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
        buf.memory = V4L2_MEMORY_MMAP;
        buf.index = i;

        if (ioctl(fd, VIDIOC_QBUF, &buf) < 0) {
            perror("Error queuing buffer");
            return -1;
        }
    }

    enum v4l2_buf_type type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    if (ioctl(fd, VIDIOC_STREAMON, &type) < 0) {
        perror("Error starting stream");
        return -1;
    }

    fd_set fds;
    struct timeval tv;
    int r;

    FD_ZERO(&fds);
    FD_SET(fd, &fds);

    tv.tv_sec = 2; // Timeout of 2 seconds
    tv.tv_usec = 0;

    r = select(fd + 1, &fds, NULL, NULL, &tv);

    if (r == -1) {
        perror("Error during select");
        ioctl(fd, VIDIOC_STREAMOFF, &type);
        return -1;
    }

    if (r == 0) {
        fprintf(stderr, "Select timeout\n");
        ioctl(fd, VIDIOC_STREAMOFF, &type);
        return -1;
    }

    memset(&buf, 0, sizeof(buf));
    buf.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    buf.memory = V4L2_MEMORY_MMAP;

    if (ioctl(fd, VIDIOC_DQBUF, &buf) < 0) {
        perror("Error dequeuing buffer");
        ioctl(fd, VIDIOC_STREAMOFF, &type);
        return -1;
    }

    FILE *fp = fopen(filename, "wb");
    if (!fp) {
        perror("Error opening file for writing");
        ioctl(fd, VIDIOC_STREAMOFF, &type);
        return -1;
    }

    fwrite(buffers[buf.index].start, buf.bytesused, 1, fp);
    fclose(fp);

    if (ioctl(fd, VIDIOC_QBUF, &buf) < 0) {
        perror("Error queuing buffer");
        ioctl(fd, VIDIOC_STREAMOFF, &type);
        return -1;
    }

    if (ioctl(fd, VIDIOC_STREAMOFF, &type) < 0) {
        perror("Error stopping stream");
        return -1;
    }

    return 0;
}

// Function to release resources
void release_resources()
{
    int i;

    if (fd != -1) {
        enum v4l2_buf_type type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
        ioctl(fd, VIDIOC_STREAMOFF, &type);

        for (i = 0; i < NUM_BUFFERS; ++i) {
            if (buffers[i].start != MAP_FAILED) {
                munmap(buffers[i].start, buffers[i].length);
            }
        }

        free(buffers);
        close(fd);
    }
}

int main()
{
    signal(SIGINT, signal_handler);

    if (init_camera(DEVICE_NAME) < 0) {
        fprintf(stderr, "Camera initialization failed. Check if %s is present and accessible.\n", DEVICE_NAME);
        return 1;
    }

    printf("Camera initialized successfully.\n");

    if (capture_image("image.yuyv") < 0) {
        fprintf(stderr, "Image capture failed.\n");
        release_resources();
        return 1;
    }

    printf("Image captured successfully. Saved to image.yuyv\n");

    release_resources();

    return 0;
}

#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

// Define GPIO pins
#define GPIO_22 22
#define GPIO_27 27

// Global variable to track program state for signal handling
volatile sig_atomic_t program_running = 1;

// Signal handler function
void signal_handler(int signal) {
    program_running = 0;
    printf("\nCaught signal %d, exiting gracefully...\n", signal);
}

int main() {
    // Register signal handlers for SIGINT and SIGTERM
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize pigpio library
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Configure GPIO pins as outputs
    gpioSetMode(GPIO_22, PI_OUTPUT);
    gpioSetMode(GPIO_27, PI_OUTPUT);

    // Main loop
    while (program_running) {
        // Set GPIO 22 HIGH
        gpioWrite(GPIO_22, 1);
        printf("GPIO 22 HIGH\n");

        // Wait for 10 milliseconds
        gpioDelay(10000); // 10000 microseconds = 10 milliseconds

        // Set GPIO 22 LOW
        gpioWrite(GPIO_22, 0);
        printf("GPIO 22 LOW\n");

        // Wait for 10 milliseconds
        gpioDelay(10000); // 10000 microseconds = 10 milliseconds

        // Set GPIO 27 HIGH
        gpioWrite(GPIO_27, 1);
        printf("GPIO 27 HIGH\n");

        // Wait for 10 milliseconds
        gpioDelay(10000); // 10000 microseconds = 10 milliseconds

        // Set GPIO 27 LOW
        gpioWrite(GPIO_27, 0);
        printf("GPIO 27 LOW\n");

        // Wait for 10 milliseconds
        gpioDelay(10000); // 10000 microseconds = 10 milliseconds
    }

    // Release GPIO resources before exiting
    gpioTerminate();
    printf("pigpio terminated\n");

    return 0;
}

