// Global variable for the I2C file descriptor
int i2c_fd;

// Signal handler for Ctrl+C
void signal_handler(int sig) {
    printf("\nExiting program...\n");
    // Clear the display
    ssd1306_clear_display();
    // Close the I2C device
    close(i2c_fd);
    exit(0);
}

// Function to initialize the SSD1306 display
int ssd1306_init() {
    // Initialization sequence (refer to SSD1306 datasheet)
    uint8_t init_commands[] = {
        0xAE,       // Display off
        0xD5, 0x80, // Clock divide ratio (0x80 = 100Hz)
        0xA8, 0x3F, // Multiplex ratio (63 = 64 rows)
        0xD3, 0x00, // Display offset
        0x40,       // Start line
        0x8D, 0x14, // Charge pump setting
        0x20, 0x00, // Memory addressing mode (0x00 = horizontal)
        0xA1,       // Segment remap
        0xC8,       // COM output scan direction
        0xDA, 0x12, // COM pins hardware configuration
        0x81, 0xCF, // Contrast control
        0xD9, 0xF1, // Pre-charge period
        0xDB, 0x40, // VCOM deselect level
        0xA4,       // Entire display ON/OFF (0xA4 = normal, 0xA5 = all ON)
        0xA6,       // Normal/Inverse display (0xA6 = normal, 0xA7 = inverse)
        0xAF        // Display on
    };

    for (size_t i = 0; i < sizeof(init_commands); i++) {
        uint8_t data[2] = {0x00, init_commands[i]};
        if (write(i2c_fd, data, 2) != 2) {
            perror("Error writing to I2C device");
            return -1;
        }
    }

    return 0;
}

// Function to clear the SSD1306 display
void ssd1306_clear_display() {
    uint8_t buffer[1025] = {0x40}; // Start command + 1024 bytes of 0x00
    memset(buffer + 1, 0x00, 1024);
    if (write(i2c_fd, buffer, 1025) != 1025) {
        perror("Error writing to I2C device");
    }
}

