#include <pigpio.h>

// Define GPIO pins for the LED strip
#define DATA_PIN 18
#define CLOCK_PIN 23

// Define the number of LEDs in the strip
#define NUM_LEDS 10

// Structure to represent a colour
typedef struct {
    int red;
    int green;
    int blue;
} Colour;

// Global variable to indicate program termination
volatile sig_atomic_t terminate = 0;

// Signal handler for SIGINT (Ctrl+C)
void sigint_handler(int signal) {
    terminate = 1;
    printf("\nCaught SIGINT, exiting gracefully...\n");
}

// Function to set the colour of a single LED
void set_led_colour(int led_number, Colour colour) {
    // Convert RGB values to 24-bit data stream
    unsigned int data = (colour.red << 16) | (colour.green << 8) | colour.blue;

    // Send the data to the LED strip
    for (int i = 23; i >= 0; i--) {
        gpioWrite(CLOCK_PIN, 0); // Clock low
        gpioWrite(DATA_PIN, (data >> i) & 1); // Send bit
        gpioWrite(CLOCK_PIN, 1); // Clock high
    }
}

// Function to set the colour of all LEDs in the strip
void set_all_leds(Colour colour) {
    for (int i = 0; i < NUM_LEDS; i++) {
        set_led_colour(i, colour);
    }
}

int main() {
    // Initialize pigpio library
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO pins as outputs
    gpioSetMode(DATA_PIN, PI_OUTPUT);
    gpioSetMode(CLOCK_PIN, PI_OUTPUT);

    // Register signal handler for SIGINT
    signal(SIGINT, sigint_handler);

    // Main loop
    while (!terminate) {
        // Define a colour
        Colour colour = {255, 0, 0}; // Red

        // Set the colour of all LEDs
        set_all_leds(colour);

        // Delay for 10 milliseconds
        gpioDelay(10000); // 10000 microseconds = 10 milliseconds
    }

    // Clean up and exit
    gpioTerminate();
    return 0;
}

