            // Release previously acquired lines
            for (int j = 0; j < NUM_GPIOS; j++) {
                gpiod_line_release(gpio_lines[j]);
            }
            gpiod_chip_close(gpio_chip);
            return 1;
        }
    }

    // Report GPIO states
    printf("GPIO states:\n");
    for (int i = 0; i < NUM_GPIOS; i++) {
        int value = gpiod_line_get_value(gpio_lines[i]);
        if (value < 0) {
            fprintf(stderr, "Error getting GPIO %d value: %s\n", i + 1, strerror(errno));
            // Release previously acquired lines
            for (int j = 0; j < NUM_GPIOS; j++) {
                gpiod_line_release(gpio_lines[j]);
            }
            gpiod_chip_close(gpio_chip);
            return 1;
        }
        printf("GPIO %d: %d\n", i + 1, value);
    }

    // Release GPIO lines
    for (int i = 0; i < NUM_GPIOS; i++) {
        if (gpiod_line_release(gpio_lines[i]) < 0) {
            fprintf(stderr, "Error releasing GPIO %d: %s\n", i + 1, strerror(errno));
        }
    }

    // Close GPIO chip
    if (gpiod_chip_close(gpio_chip) < 0) {
        fprintf(stderr, "Error closing GPIO chip: %s\n", strerror(errno));
    }

    return 0;
}

