#include <errno.h>
#include <string.h>

// MPU6050 I2C address
#define MPU6050_ADDR 0x68

// MPU6050 registers
#define PWR_MGMT_1   0x6B
#define ACCEL_XOUT_H 0x3B
#define ACCEL_YOUT_H 0x3D
#define ACCEL_ZOUT_H 0x3F

// Global variables
int i2c_fd;
volatile sig_atomic_t program_running = 1;

// Signal handler for Ctrl+C
void signal_handler(int sig) {
    program_running = 0;
    printf("\nExiting program...\n");
}

// Function to initialize the MPU6050
int init_mpu6050() {
    // Wake up the MPU6050 (clear sleep mode bit)
    if (i2c_smbus_write_byte_data(i2c_fd, PWR_MGMT_1, 0) < 0) {
        perror("Error writing to PWR_MGMT_1");
        return -1;
    }
    return 0;
}

// Function to read accelerometer data
int read_accelerometer(int16_t *x, int16_t *y, int16_t *z) {
    uint8_t buffer[6];

    // Read accelerometer data (X, Y, Z)
    if (read(i2c_fd, buffer, 6) != 6) {
        perror("Error reading accelerometer data");
        return -1;
    }

    // Combine high and low bytes for each axis
    *x = (int16_t)((buffer[0] << 8) | buffer[1]);
    *y = (int16_t)((buffer[2] << 8) | buffer[3]);
    *z = (int16_t)((buffer[4] << 8) | buffer[5]);

    return 0;
}

int main() {
    // Register signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    // Open I2C device
    i2c_fd = open("/dev/i2c-1", O_RDWR);
    if (i2c_fd < 0) {
        perror("Error opening I2C device");
        return 1;
    }

    // Specify the address of the slave device
    if (ioctl(i2c_fd, I2C_SLAVE, MPU6050_ADDR) < 0) {
        perror("Error setting I2C slave address");
        close(i2c_fd);
        return 1;
    }

    // Initialize MPU6050
    if (init_mpu6050() < 0) {
        close(i2c_fd);
        return 1;
    }

    printf("MPU6050 initialized successfully.\n");

    // Main loop
    while (program_running) {
        int16_t x, y, z;

        // Read accelerometer data
        if (read_accelerometer(&x, &y, &z) == 0) {
            // Print accelerometer data
            printf("X: %6d, Y: %6d, Z: %6d\n", x, y, z);
        } else {
            fprintf(stderr, "Failed to read accelerometer data. Retrying...\n");
        }

        // Delay for 10 milliseconds
        usleep(10000); // 10000 microseconds = 10 milliseconds
    }

    // Close I2C device
    close(i2c_fd);

    return 0;
}

#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define GPIO_PIN 23

volatile sig_atomic_t program_running = 1;

void signal_handler(int signal) {
    program_running = 0;
    printf("\nCaught signal %d, exiting gracefully...\n", signal);
}

int main() {
    int gpio_status;

    // Register signal handlers for SIGINT and SIGTERM
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize the pigpio library
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO 23 as an output
    gpioSetMode(GPIO_PIN, PI_OUTPUT);

    printf("GPIO %d set as output.  Toggling every 0.05 seconds...\n", GPIO_PIN);

    // Main loop to toggle the GPIO pin
    while (program_running) {
        // Set GPIO high
        gpioWrite(GPIO_PIN, 1);
        gpio_status = gpioRead(GPIO_PIN);
        if (gpio_status != 1) {
            fprintf(stderr, "Error: GPIO %d read back as %d after setting high\n", GPIO_PIN, gpio_status);
        }
        printf("GPIO %d set HIGH\n", GPIO_PIN);

        // Wait for 50 milliseconds
        gpioDelay(50000); // 50000 microseconds = 50 milliseconds

        // Set GPIO low
        gpioWrite(GPIO_PIN, 0);
        gpio_status = gpioRead(GPIO_PIN);
        if (gpio_status != 0) {
            fprintf(stderr, "Error: GPIO %d read back as %d after setting low\n", GPIO_PIN, gpio_status);
        }
        printf("GPIO %d set LOW\n", GPIO_PIN);

        // Wait for 50 milliseconds
        gpioDelay(50000); // 50000 microseconds = 50 milliseconds
    }

    // Clean up and terminate the pigpio library
    gpioTerminate();
    printf("pigpio terminated.\n");

    return 0;
}

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <signal.h>
#include <time.h>

// Define the I2C address of the HD44780 LCD
#define LCD_ADDR 0x27

// Define the I2C bus
#define I2C_BUS "/dev/i2c-1"

// Define LCD commands
#define LCD_CLEARDISPLAY 0x01
#define LCD_RETURNHOME 0x02
#define LCD_ENTRYMODESET 0x04
#define LCD_DISPLAYCONTROL 0x08
#define LCD_CURSORSHIFT 0x10
#define LCD_FUNCTIONSET 0x20

// Define LCD flags
#define LCD_ENTRYRIGHT 0x00
#define LCD_ENTRYLEFT 0x02
#define LCD_ENTRYSHIFTINCREMENT 0x01
#define LCD_ENTRYSHIFTDECREMENT 0x00

#define LCD_DISPLAYON 0x04
#define LCD_DISPLAYOFF 0x00
#define LCD_CURSORON 0x02
#define LCD_CURSOROFF 0x00
#define LCD_BLINKON 0x01
#define LCD_BLINKOFF 0x00

#define LCD_8BITMODE 0x10
#define LCD_4BITMODE 0x00
#define LCD_2LINE 0x08
#define LCD_1LINE 0x00
#define LCD_5x10DOTS 0x04
#define LCD_5x8DOTS 0x00

// Define LCD control bits
#define LCD_RS 0x01
#define LCD_EN 0x04
#define LCD_D4 0x10
#define LCD_D5 0x20
#define LCD_D6 0x40
#define LCD_D7 0x80

// Global variables
int i2c_fd;
volatile sig_atomic_t program_running = 1;

// Function prototypes
int lcd_init();
void lcd_send_command(unsigned char command);
void lcd_send_data(unsigned char data);
void lcd_print(const char *string);
void lcd_clear();
void lcd_set_cursor(int row, int col);
void signal_handler(int signal);

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    program_running = 0;
    printf("\nCaught signal %d, exiting gracefully.\n", signal);
    lcd_clear();
    close(i2c_fd);
    exit(0);
}

// Initialize the LCD
int lcd_init() {
    // Initialize the I2C bus
    if ((i2c_fd = open(I2C_BUS, O_RDWR)) < 0) {
        perror("Error opening I2C bus");
        return -1;
    }

    if (ioctl(i2c_fd, I2C_SLAVE, LCD_ADDR) < 0) {
        perror("Error setting I2C slave address");
        close(i2c_fd);
        return -1;
    }

    // Initialize the LCD in 4-bit mode
    usleep(50000); // Wait for more than 4.1ms after VCC rises to 2.7V
    lcd_send_command(0x33); // Initialize
    usleep(5000);  // Wait for more than 4.1ms
    lcd_send_command(0x32); // Initialize
    usleep(100);   // Wait for more than 100us
    lcd_send_command(0x28); // 4-bit mode, 2 lines, 5x8 font
    usleep(100);   // Wait for more than 100us
    lcd_send_command(0x0C); // Display on, cursor off, blink off
    usleep(100);   // Wait for more than 100us
    lcd_send_command(0x06); // Increment cursor, no shift
    usleep(100);   // Wait for more than 100us
    lcd_send_command(0x01); // Clear display
    usleep(2000);  // Wait for more than 2ms

    return 0;
}

// Send a command to the LCD
void lcd_send_command(unsigned char command) {
    unsigned char data_u, data_l;
    unsigned char data_t[4];
    unsigned char data;

    data_u = (command & 0xF0);
    data_l = ((command << 4) & 0xF0);

    data_t[0] = data_u | LCD_EN;  // En high
    data_t[1] = data_u & ~LCD_EN; // En low
    data_t[2] = data_l | LCD_EN;  // En high
    data_t[3] = data_l & ~LCD_EN; // En low

    for (int i = 0; i < 4; i++) {
        data = data_t[i];
        if (write(i2c_fd, &data, 1) != 1) {
            perror("Error writing to I2C device");
        }
        usleep(1); // Enable pulse width >= 300ns
    }
}

// Send data to the LCD
void lcd_send_data(unsigned char data) {
    unsigned char data_u, data_l;
    unsigned char data_t[4];
    unsigned char cmd;

    data_u = (data & 0xF0) | LCD_RS;
    data_l = ((data << 4) & 0xF0) | LCD_RS;

    data_t[0] = data_u | LCD_EN;  // En high
    data_t[1] = data_u & ~LCD_EN; // En low
    data_t[2] = data_l | LCD_EN;  // En high
    data_t[3] = data_l & ~LCD_EN; // En low

    for (int i = 0; i < 4; i++) {
        cmd = data_t[i];
        if (write(i2c_fd, &cmd, 1) != 1) {
            perror("Error writing to I2C device");
        }
        usleep(1); // Enable pulse width >= 300ns
    }
}

// Print a string to the LCD
void lcd_print(const char *string) {
    while (*string) {
        lcd_send_data(*string++);
    }
}

// Clear the LCD display
void lcd_clear() {
    lcd_send_command(LCD_CLEARDISPLAY);
    usleep(2000); // Wait for more than 2ms
}

// Set the cursor position
void lcd_set_cursor(int row, int col) {
    int address;
    if (row == 0) {
        address = 0x00 + col;
    } else {
        address = 0x40 + col;
    }
    lcd_send_command(0x80 + address);
}

int main() {
    // Register signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    // Initialize the LCD
    if (lcd_init() < 0) {
        fprintf(stderr, "LCD initialization failed.\n");
        return 1;
    }

    // Main loop
    while (program_running) {
        // Get current timestamp
        time_t rawtime;
        struct tm *timeinfo;
        char timestamp[20];

        time(&rawtime);
        timeinfo = localtime(&rawtime);

        strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

        // Print timestamp to LCD
        lcd_clear();
        lcd_set_cursor(0, 0);
        lcd_print(timestamp);

        // Wait for 10 seconds
        sleep(10);
    }

    // Close the I2C bus
    close(i2c_fd);

    return 0;
}

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <fcntl.h>
#include <unistd.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <signal.h>
#include <errno.h>
#include <string.h>

// MPU6050 I2C address
#define MPU6050_ADDR 0x68

// MPU6050 registers
#define PWR_MGMT_1   0x6B
#define ACCEL_XOUT_H 0x3B
#define ACCEL_YOUT_H 0x3D
#define ACCEL_ZOUT_H 0x3F

// Global variables
int i2c_fd;
volatile sig_atomic_t program_running = 1;

// Function prototypes
int init_i2c(int address);
int read_register(int reg);
int write_register(int reg, int value);
int16_t read_raw_data(int reg);
void signal_handler(int sig);

// Signal handler for graceful shutdown
void signal_handler(int sig) {
    program_running = 0;
    printf("\nCaught signal %d, exiting gracefully.\n", sig);
}

// Initialize I2C communication
int init_i2c(int address) {
    int fd = open("/dev/i2c-1", O_RDWR);
    if (fd < 0) {
        perror("Error opening I2C device");
        return -1;
    }

    if (ioctl(fd, I2C_SLAVE, address) < 0) {
        perror("Error setting I2C slave address");
        close(fd);
        return -1;
    }

    return fd;
}

// Read a single byte from a register
int read_register(int reg) {
    int value = i2c_smbus_read_byte_data(i2c_fd, reg);
    if (value < 0) {
        perror("Error reading register");
        return -1;
    }
    return value;
}

// Write a single byte to a register
int write_register(int reg, int value) {
    int result = i2c_smbus_write_byte_data(i2c_fd, reg, value);
    if (result < 0) {
        perror("Error writing register");
        return -1;
    }
    return 0;
}

// Read raw accelerometer data from two registers
int16_t read_raw_data(int reg) {
    int16_t high = read_register(reg);
    int16_t low = read_register(reg + 1);

    if (high < 0 || low < 0) {
        return 0; // Return 0 on error
    }

    return (high << 8) | low;
}

int main() {
    // Register signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    // Initialize I2C
    i2c_fd = init_i2c(MPU6050_ADDR);
    if (i2c_fd < 0) {
        fprintf(stderr, "MPU6050 not found at address 0x%02X\n", MPU6050_ADDR);
        return 1;
    }

    // Wake up the MPU6050 (clear sleep mode bit)
    if (write_register(PWR_MGMT_1, 0) < 0) {
        fprintf(stderr, "Failed to wake up MPU6050\n");
        close(i2c_fd);
        return 1;
    }

    printf("MPU6050 initialized successfully.\n");

    // Main loop
    for (int i = 0; i < 100 && program_running; i++) {
        // Read accelerometer data
        int16_t accel_x = read_raw_data(ACCEL_XOUT_H);
        int16_t accel_y = read_raw_data(ACCEL_YOUT_H);
        int16_t accel_z = read_raw_data(ACCEL_ZOUT_H);

        // Print the data
        printf("Accelerometer X: %d, Y: %d, Z: %d\n", accel_x, accel_y, accel_z);

        // Delay for 10 milliseconds
        usleep(10000); // 10000 microseconds = 10 milliseconds
    }

    // Close I2C device
    close(i2c_fd);

    printf("Program finished.\n");

    return 0;
}

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

// Define GPIO pins
#define GPIO_14 14
#define GPIO_15 15

// Define I2C address
#define I2C_ADDR 0x48

// Define I2C bus
#define I2C_BUS 1

// Define valid sensor readings
#define MIN_TEMP 10.0
#define MAX_TEMP 30.0

// Global variables
int i2c_handle;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int read_temperature(float *temperature);
int control_gpio(int gpio, int state);
void report_state(int gpio, int state);
void signal_handler(int signal);

// Signal handler function
void signal_handler(int signal) {
    terminate = 1;
    printf("\nCaught signal %d, exiting gracefully...\n", signal);
}

// Function to read temperature from the sensor
int read_temperature(float *temperature) {
    char buf[2];
    int result;

    result = i2cReadDevice(i2c_handle, buf, 2);
    if (result != 2) {
        fprintf(stderr, "Error reading temperature: %d\n", result);
        return -1;
    }

    // Convert raw data to temperature (assuming LM75B format)
    int raw_temp = (buf[0] << 4) | (buf[1] >> 4);
    if (raw_temp & 0x800) {
        raw_temp |= 0xF000; // Sign extend if negative
    }

    *temperature = (float)raw_temp * 0.0625;

    // Validate sensor reading
    if (*temperature < MIN_TEMP || *temperature > MAX_TEMP) {
        fprintf(stderr, "Invalid temperature reading: %.2f\n", *temperature);
        return -1;
    }

    return 0;
}

// Function to control GPIO output
int control_gpio(int gpio, int state) {
    if (gpioWrite(gpio, state) != 0) {
        fprintf(stderr, "Error writing to GPIO %d\n", gpio);
        return -1;
    }
    return 0;
}

// Function to report GPIO state
void report_state(int gpio, int state) {
    printf("GPIO %d: %s\n", gpio, state ? "HIGH" : "LOW");
}

int main() {
    float temperature;
    int gpio_state = 0; // 0 = LOW, 1 = HIGH
    time_t last_report_time = 0;

    // Initialize pigpio library
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Open I2C device
    i2c_handle = i2cOpen(I2C_BUS, I2C_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C device: %d\n", i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Set GPIO modes
    gpioSetMode(GPIO_14, PI_OUTPUT);
    gpioSetMode(GPIO_15, PI_OUTPUT);

    // Register signal handler
    signal(SIGINT, signal_handler);

    printf("Temperature monitoring and GPIO control started. Press Ctrl+C to exit.\n");

    // Main loop
    while (!terminate) {
        // Read temperature
        if (read_temperature(&temperature) == 0) {
            // Control GPIO based on temperature
            if (temperature < 20.0) {
                if (gpio_state != 0) {
                    if (control_gpio(GPIO_14, 0) == 0 && control_gpio(GPIO_15, 0) == 0) {
                        gpio_state = 0;
                        report_state(GPIO_14, 0);
                        report_state(GPIO_15, 0);
                    }
                }
            } else if (temperature > 25.0) {
                if (gpio_state != 1) {
                    if (control_gpio(GPIO_14, 1) == 0 && control_gpio(GPIO_15, 1) == 0) {
                        gpio_state = 1;
                        report_state(GPIO_14, 1);
                        report_state(GPIO_15, 1);
                    }
                }
            }

            // Report state every 5 seconds
            time_t current_time = time(NULL);
            if (current_time - last_report_time >= 5) {
                report_state(GPIO_14, gpio_state);
                report_state(GPIO_15, gpio_state);
                last_report_time = current_time;
            }
        } else {
            fprintf(stderr, "Failed to read temperature. Retrying in 1 second.\n");
        }

        gpioDelay(1000); // Wait 1 second
    }

    // Cleanup
    i2cClose(i2c_handle);
    gpioTerminate();

    printf("Program terminated.\n");
    return 0;
}

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <signal.h>
#include <unistd.h>
#include <time.h>
#include <pigpio.h>
#include <mosquitto.h>

// Configuration
#define MQTT_BROKER "localhost" // Change this to your MQTT broker address
#define MQTT_PORT 1883
#define MQTT_TOPIC "sensor/data"
#define SPI_CHANNEL 0
#define SPI_SPEED 1000000 // 1 MHz
#define ADC_CHANNEL 0
#define ADC_MIN 0
#define ADC_MAX 1023
#define TEMP_MIN 0.0
#define TEMP_MAX 50.0
#define READ_INTERVAL_US 10000 // 0.01 seconds

// Global variables
int spi_handle;
struct mosquitto *mosq = NULL;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int read_adc(int channel);
float adc_to_temperature(int adc_value);
int publish_temperature(float temperature);
void signal_handler(int sig);
int initialize();
void cleanup();

// Function to read ADC value from MCP3008
int read_adc(int channel) {
    if (channel < 0 || channel > 7) {
        fprintf(stderr, "Error: Invalid ADC channel %d\n", channel);
        return -1;
    }

    unsigned char spi_tx_buf[3];
    unsigned char spi_rx_buf[3];

    // Construct SPI message
    spi_tx_buf[0] = 0x01; // Start bit
    spi_tx_buf[1] = (0x08 | channel) << 4; // Single-ended mode, channel select
    spi_tx_buf[2] = 0x00; // Don't care

    // Transfer SPI data
    int result = spiXfer(spi_handle, spi_tx_buf, spi_rx_buf, 3);
    if (result != 0) {
        fprintf(stderr, "Error: SPI transfer failed (%d)\n", result);
        return -1;
    }

    // Extract ADC value
    int adc_value = ((spi_rx_buf[1] & 0x03) << 8) + spi_rx_buf[2];
    return adc_value;
}

// Function to convert ADC value to temperature (Celsius)
float adc_to_temperature(int adc_value) {
    if (adc_value < ADC_MIN || adc_value > ADC_MAX) {
        fprintf(stderr, "Error: ADC value out of range (%d)\n", adc_value);
        return -1000.0; // Indicate an error
    }

    float temperature = TEMP_MIN + (float)(adc_value - ADC_MIN) * (TEMP_MAX - TEMP_MIN) / (ADC_MAX - ADC_MIN);
    return temperature;
}

// Function to publish temperature reading to MQTT broker
int publish_temperature(float temperature) {
    char payload[50];
    snprintf(payload, sizeof(payload), "%.2f", temperature);

    int ret = mosquitto_publish(mosq, NULL, MQTT_TOPIC, strlen(payload), payload, 0, false);
    if (ret != MOSQ_ERR_SUCCESS) {
        fprintf(stderr, "Error: MQTT publish failed (%s)\n", mosquitto_strerror(ret));
        return -1;
    }

    return 0;
}

// Signal handler for graceful shutdown
void signal_handler(int sig) {
    fprintf(stderr, "Signal received, terminating...\n");
    terminate = 1;
}

// Initialization function
int initialize() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return -1;
    }

    // Open SPI channel
    spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, 0); // Mode 0
    if (spi_handle < 0) {
        fprintf(stderr, "Error: SPI open failed (%d)\n", spi_handle);
        gpioTerminate();
        return -1;
    }

    // Initialize libmosquitto
    mosquitto_lib_init();
    mosq = mosquitto_new(NULL, true, NULL);
    if (!mosq) {
        fprintf(stderr, "Error: mosquitto_new failed\n");
        spiClose(spi_handle);
        gpioTerminate();
        mosquitto_lib_cleanup();
        return -1;
    }

    // Connect to MQTT broker
    int ret = mosquitto_connect(mosq, MQTT_BROKER, MQTT_PORT, 60);
    if (ret != MOSQ_ERR_SUCCESS) {
        fprintf(stderr, "Error: MQTT connect failed (%s)\n", mosquitto_strerror(ret));
        mosquitto_destroy(mosq);
        spiClose(spi_handle);
        gpioTerminate();
        mosquitto_lib_cleanup();
        return -1;
    }

    mosquitto_loop_start(mosq);

    return 0;
}

// Cleanup function
void cleanup() {
    fprintf(stderr, "Cleaning up...\n");

    // Disconnect from MQTT broker
    if (mosq) {
        mosquitto_disconnect(mosq);
        mosquitto_loop_stop(mosq, false);
        mosquitto_destroy(mosq);
    }

    // Close SPI channel
    if (spi_handle >= 0) {
        spiClose(spi_handle);
    }

    // Terminate pigpio
    gpioTerminate();

    // Cleanup libmosquitto
    mosquitto_lib_cleanup();

    fprintf(stderr, "Cleanup complete.\n");
}

int main() {
    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize
    if (initialize() != 0) {
        return 1;
    }

    fprintf(stderr, "Temperature sensor publishing started. Press Ctrl+C to exit.\n");

    // Main loop
    while (!terminate) {
        // Read ADC value
        int adc_value = read_adc(ADC_CHANNEL);
        if (adc_value < 0) {
            fprintf(stderr, "Error reading ADC, retrying...\n");
            gpioDelay(100000); // Wait 0.1 seconds before retrying
            continue;
        }

        // Convert ADC value to temperature
        float temperature = adc_to_temperature(adc_value);
        if (temperature < -999.0) {
            fprintf(stderr, "Error converting ADC to temperature, retrying...\n");
            gpioDelay(100000); // Wait 0.1 seconds before retrying
            continue;
        }

        // Publish temperature reading
        if (publish_temperature(temperature) != 0) {
            fprintf(stderr, "Error publishing temperature, retrying...\n");
        }

        // Wait for the specified interval
        gpioDelay(READ_INTERVAL_US);
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

