#include <stdio.h>
#include <stdlib.h>
#include <gpiod.h>
#include <signal.h>
#include <unistd.h>

// Define GPIO pins
#define GPIO_18 18
#define GPIO_24 24

// Global variables for GPIO lines and chip
struct gpiod_line *line18 = NULL;
struct gpiod_line *line24 = NULL;
struct gpiod_chip *chip = NULL;

// Signal handler for Ctrl+C
void signal_handler(int sig) {
    printf("\nCaught signal %d, cleaning up...\n", sig);

    // Release GPIO lines
    if (line18) {
        gpiod_line_release(line18);
    }
    if (line24) {
        gpiod_line_release(line24);
    }

    // Close GPIO chip
    if (chip) {
        gpiod_chip_close(chip);
    }

    exit(0);
}

int main() {
    // Register signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    // Open GPIO chip
    chip = gpiod_chip_open_by_name("gpiochip0");
    if (!chip) {
        perror("Error opening GPIO chip");
        return 1;
    }

    // Get GPIO lines for GPIO 18 and GPIO 24
    line18 = gpiod_chip_get_line(chip, GPIO_18);
    if (!line18) {
        perror("Error getting GPIO 18 line");
        gpiod_chip_close(chip);
        return 1;
    }

    line24 = gpiod_chip_get_line(chip, GPIO_24);
    if (!line24) {
        perror("Error getting GPIO 24 line");
        gpiod_line_release(line18);
        gpiod_chip_close(chip);
        return 1;
    }

    // Request GPIO lines for output
    if (gpiod_line_request_output(line18, "gpio18_output", 0) < 0) {
        perror("Error requesting GPIO 18 for output");
        gpiod_line_release(line18);
        gpiod_line_release(line24);
        gpiod_chip_close(chip);
        return 1;
    }

    if (gpiod_line_request_output(line24, "gpio24_output", 1) < 0) {
        perror("Error requesting GPIO 24 for output");
        gpiod_line_release(line18);
        gpiod_line_release(line24);
        gpiod_chip_close(chip);
        return 1;
    }

    // Set GPIO 18 to HIGH and GPIO 24 to LOW
    if (gpiod_line_set_value(line18, 1) < 0) {
        perror("Error setting GPIO 18 HIGH");
        gpiod_line_release(line18);
        gpiod_line_release(line24);
        gpiod_chip_close(chip);
        return 1;
    }

    if (gpiod_line_set_value(line24, 0) < 0) {
        perror("Error setting GPIO 24 LOW");
        gpiod_line_release(line18);
        gpiod_line_release(line24);
        gpiod_chip_close(chip);
        return 1;
    }

    // Report the state applied to standard output
    printf("GPIO 18 set to HIGH, GPIO 24 set to LOW\n");

    // Release GPIO lines
    gpiod_line_release(line18);
    gpiod_line_release(line24);

    // Close GPIO chip
    gpiod_chip_close(chip);

    return 0;
}

