// Configuration
#define MQTT_BROKER "localhost" // Change this to your MQTT broker address
#define MQTT_PORT 1883
#define MQTT_TOPIC "sensor/data"
#define DHT22_GPIO 4
#define MAX_RETRIES 3

// Global variables
static volatile int running = 1;
static struct mosquitto *mosq = NULL;

// Function prototypes
int read_dht22(int gpio, float *temperature, float *humidity);
int publish_data(struct mosquitto *mosq, const char *topic, float temperature, float humidity);
void signal_handler(int signum);

// Signal handler for graceful shutdown
void signal_handler(int signum) {
    if (signum == SIGINT) {
        printf("Received SIGINT, shutting down...\n");
        running = 0;
    }
}

// Function to read DHT22 sensor data
int read_dht22(int gpio, float *temperature, float *humidity) {
    int result = 0;
    int retries = 0;
    int data[5] = {0, 0, 0, 0, 0};
    int bit_count = 0;
    int byte_index = 0;

    gpioSetMode(gpio, PI_OUTPUT);
    gpioWrite(gpio, 0);
    gpioDelay(1);
    gpioWrite(gpio, 1);
    gpioDelay(30);
    gpioSetMode(gpio, PI_INPUT);

    // Read data
    for (int i = 0; i < 85; i++) {
        int count = 0;
        while (gpioRead(gpio) == (i % 2 == 0 ? 0 : 1)) {
            count++;
            gpioDelay(1);
            if (count > 200) {
                fprintf(stderr, "DHT22 timeout error\n");
                return -1; // Timeout error
            }
        }

        if (i > 3) {
            data[byte_index] <<= 1;
            if (count > 26) {
                data[byte_index] |= 1;
            }
            bit_count++;
            if (bit_count == 8) {
                bit_count = 0;
                byte_index++;
            }
        }
    }

    // Validate checksum
    if (data[4] != ((data[0] + data[1] + data[2] + data[3]) & 0xFF)) {
        fprintf(stderr, "DHT22 checksum error\n");
        return -2; // Checksum error
    }

    *humidity = (float)((data[0] << 8) + data[1]) / 10.0;
    *temperature = (float)(((data[2] & 0x7F) << 8) + data[3]) / 10.0;
    if (data[2] & 0x80) {
        *temperature *= -1.0;
    }

    return 0; // Success
}

// Function to publish data to MQTT broker
int publish_data(struct mosquitto *mosq, const char *topic, float temperature, float humidity) {
    char payload[50];
    snprintf(payload, sizeof(payload), "{\"temperature\": %.1f, \"humidity\": %.1f}", temperature, humidity);

    int ret = mosquitto_publish(mosq, NULL, topic, strlen(payload), payload, 0, false);
    if (ret != MOSQ_ERR_SUCCESS) {
        fprintf(stderr, "Error publishing message: %s\n", mosquitto_strerror(ret));
        return -1;
    }

    printf("Published: %s\n", payload);
    return 0;
}

int main() {
    float temperature, humidity;
    int result;

    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Initialize libmosquitto
    mosquitto_lib_init();
    mosq = mosquitto_new(NULL, true, NULL);
    if (!mosq) {
        fprintf(stderr, "Error: Out of memory.\n");
        gpioTerminate();
        return 1;
    }

    // Connect to MQTT broker
    int ret = mosquitto_connect(mosq, MQTT_BROKER, MQTT_PORT, 60);
    if (ret != MOSQ_ERR_SUCCESS) {
        fprintf(stderr, "Error connecting to MQTT broker: %s\n", mosquitto_strerror(ret));
        mosquitto_destroy(mosq);
        mosquitto_lib_cleanup();
        gpioTerminate();
        return 1;
    }

    // Set signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    // Main loop
    while (running) {
        result = read_dht22(DHT22_GPIO, &temperature, &humidity);
        if (result == 0) {
            if (publish_data(mosq, MQTT_TOPIC, temperature, humidity) != 0) {
                fprintf(stderr, "Failed to publish data.\n");
            }
        } else {
            fprintf(stderr, "Failed to read DHT22 sensor data. Retrying...\n");
        }

        sleep(5);
    }

    // Cleanup
    mosquitto_disconnect(mosq);
    mosquitto_destroy(mosq);
    mosquitto_lib_cleanup();
    gpioTerminate();

    printf("Program finished.\n");
    return 0;
}

