    gpioTerminate();

    printf("Program terminated.\n");
    return 0;
}

#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

// Define GPIO pins
#define TRIGGER_PIN 23
#define ECHO_PIN 24

// Define constants
#define SPEED_OF_SOUND 34300.0 // Speed of sound in cm/s
#define TIMEOUT_US 50000       // Timeout in microseconds (50ms)

// Global variables
volatile sig_atomic_t program_running = 1;

// Signal handler for Ctrl+C
void signal_handler(int signal) {
    program_running = 0;
    printf("\nExiting program...\n");
}

// Function to trigger the HC-SR04 sensor
void trigger_sensor() {
    gpioWrite(TRIGGER_PIN, 1);
    gpioDelay(10); // 10us trigger pulse
    gpioWrite(TRIGGER_PIN, 0);
}

// Function to measure the echo pulse width
long measure_pulse_width() {
    long start_tick, end_tick, pulse_width;

    // Wait for the echo pin to go high
    int count = 0;
    while (gpioRead(ECHO_PIN) == 0 && count < TIMEOUT_US) {
        count++;
        gpioDelay(1); // Small delay to prevent busy-waiting
    }

    if (count >= TIMEOUT_US) {
        fprintf(stderr, "Error: Timeout waiting for echo start.\n");
        return -1; // Indicate timeout error
    }

    start_tick = gpioTick();

    // Wait for the echo pin to go low
    count = 0;
    while (gpioRead(ECHO_PIN) == 1 && count < TIMEOUT_US) {
        count++;
        gpioDelay(1);
    }

    if (count >= TIMEOUT_US) {
        fprintf(stderr, "Error: Timeout waiting for echo end.\n");
        return -1; // Indicate timeout error
    }

    end_tick = gpioTick();

    pulse_width = end_tick - start_tick;
    return pulse_width;
}

// Function to calculate the distance in centimeters
float calculate_distance(long pulse_width) {
    if (pulse_width < 0) {
        return -1.0; // Indicate error
    }
    return (float)pulse_width * SPEED_OF_SOUND / 2000000.0; // Divide by 2 for one-way distance
}

int main() {
    // Initialize pigpio library
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO modes
    gpioSetMode(TRIGGER_PIN, PI_OUTPUT);
    gpioSetMode(ECHO_PIN, PI_INPUT);

    // Register signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    printf("HC-SR04 sensor program running. Press Ctrl+C to exit.\n");

    // Main loop
    while (program_running) {
        trigger_sensor();
        long pulse_width = measure_pulse_width();
        float distance = calculate_distance(pulse_width);

        if (distance >= 0) {
            printf("Distance: %.2f cm\n", distance);
        } else {
            fprintf(stderr, "Error: Distance measurement failed.\n");
        }

        gpioDelay(200); // Wait 200ms
    }

    // Clean up and exit
    gpioTerminate();
    return 0;
}

