    }

    int rc = mosquitto_connect(mosq, broker, port, 60);
    if (rc != MOSQ_ERR_SUCCESS) {
        fprintf(stderr, "Error connecting to MQTT broker: %s\n", mosquitto_strerror(rc));
        mosquitto_destroy(mosq);
        mosquitto_lib_cleanup();
        return -1;
    }

    rc = mosquitto_loop_start(mosq);
    if (rc != MOSQ_ERR_SUCCESS) {
        fprintf(stderr, "Error starting MQTT loop: %s\n", mosquitto_strerror(rc));
        mosquitto_disconnect(mosq);
        mosquitto_destroy(mosq);
        mosquitto_lib_cleanup();
        return -1;
    }

    return 0;
}

// Read temperature from the sensor
int read_temperature(int i2c_handle, float *temperature) {
    char buf[2];
    int bytes_read = i2cReadDevice(i2c_handle, buf, 2);

    if (bytes_read != 2) {
        fprintf(stderr, "Error reading temperature data: %d\n", bytes_read);
        return -1;
    }

    // Convert raw data to temperature (Celsius)
    int raw_temp = (buf[0] << 4) | (buf[1] >> 4);
    *temperature = (float)raw_temp * 0.0625;

    return 0;
}

// Publish temperature to MQTT broker
int publish_temperature(struct mosquitto *mosq, const char *topic, float temperature) {
    char payload[20];
    snprintf(payload, sizeof(payload), "%.2f", temperature);

    int rc = mosquitto_publish(mosq, NULL, topic, strlen(payload), payload, 0, false);
    if (rc != MOSQ_ERR_SUCCESS) {
        fprintf(stderr, "Error publishing temperature: %s\n", mosquitto_strerror(rc));
        return -1;
    }

    return 0;
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Setup I2C
    if (setup_i2c(1, I2C_ADDR) != 0) {
        gpioTerminate();
        return 1;
    }

    // Setup MQTT
    if (setup_mqtt(MQTT_BROKER, MQTT_PORT) != 0) {
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Set up signal handling
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    float temperature;
    int retries = 3;
    int delay_ms = 100;

    printf("Starting temperature monitoring...\n");

    while (!terminate) {
        if (read_temperature(i2c_handle, &temperature) == 0) {
            // Validate temperature
            if (temperature >= TEMP_MIN && temperature <= TEMP_MAX) {
                if (publish_temperature(mosq, MQTT_TOPIC, temperature) != 0) {
                    fprintf(stderr, "Failed to publish temperature, retrying...\n");
                } else {
                    printf("Published temperature: %.2f\n", temperature);
                }
            } else {
                fprintf(stderr, "Invalid temperature reading: %.2f\n", temperature);
            }
        } else {
            fprintf(stderr, "Failed to read temperature, retrying...\n");
        }

        gpioDelay(READ_INTERVAL * 1000); // Delay for 5 seconds
    }

    // Cleanup
    printf("Cleaning up...\n");
    mosquitto_loop_stop(mosq, false);
    mosquitto_disconnect(mosq);
    mosquitto_destroy(mosq);
    mosquitto_lib_cleanup();
    i2cClose(i2c_handle);
    gpioTerminate();

    printf("Exiting.\n");
    return 0;
}

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <signal.h>
#include <unistd.h>
#include <time.h>
#include <sys/time.h>
#include <pigpio.h>
#include <mosquitto.h>

// Configuration
#define MQTT_BROKER_ADDRESS "localhost" // Replace with your MQTT broker address
#define MQTT_BROKER_PORT 1883
#define MQTT_TOPIC "sensor/ads1115"
#define MQTT_CLIENT_ID "rpi_ads1115"
#define ADS1115_I2C_ADDR 0x48
#define ADS1115_REG_CONFIG 0x01
#define ADS1115_REG_CONVERT 0x00
#define ADS1115_CONFIG_OS_SINGLE 0x8000  // Start single conversion
#define ADS1115_CONFIG_MUX_SINGLE_0 0x4000 // AIN0 single-ended
#define ADS1115_CONFIG_PGA_4_096V 0x0000  // +/-4.096V range
#define ADS1115_CONFIG_MODE_SINGLE 0x0100 // Single-shot mode
#define ADS1115_CONFIG_DR_128SPS 0x0060   // 128 SPS
#define ADS1115_CONFIG_COMP_MODE_TRAD 0x0000 // Traditional comparator
#define ADS1115_CONFIG_COMP_POL_LOW 0x0000  // Active low comparator
#define ADS1115_CONFIG_COMP_LAT_NON 0x0000  // Non-latching comparator
#define ADS1115_CONFIG_COMP_QUE_DISABLE 0x0003 // Disable comparator

// Global variables
int i2c_handle;
struct mosquitto *mosq = NULL;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int init_i2c();
int read_ads1115(int16_t *value);
int publish_mqtt(int16_t value);
void signal_handler(int sig);
void cleanup();

// Signal handler for graceful shutdown
void signal_handler(int sig) {
    terminate = 1;
    printf("Signal received, terminating...\n");
}

// Initialize I2C communication
int init_i2c() {
    i2c_handle = i2cOpen(1, ADS1115_I2C_ADDR, 0); // Bus 1, address 0x48, no flags
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C: %d\n", i2c_handle);
        return -1;
    }
    return 0;
}

// Read data from ADS1115
int read_ads1115(int16_t *value) {
    uint8_t config[3];
    uint8_t data[2];

    // Configure ADS1115 for single-ended AIN0, +/-4.096V, 128 SPS
    config[0] = ADS1115_REG_CONFIG;
    config[1] = (ADS1115_CONFIG_OS_SINGLE | ADS1115_CONFIG_MUX_SINGLE_0 | ADS1115_CONFIG_PGA_4_096V | ADS1115_CONFIG_MODE_SINGLE | ADS1115_CONFIG_DR_128SPS | ADS1115_CONFIG_COMP_MODE_TRAD | ADS1115_CONFIG_COMP_POL_LOW | ADS1115_CONFIG_COMP_LAT_NON | ADS1115_CONFIG_COMP_QUE_DISABLE) >> 8;
    config[2] = (ADS1115_CONFIG_OS_SINGLE | ADS1115_CONFIG_MUX_SINGLE_0 | ADS1115_CONFIG_PGA_4_096V | ADS1115_CONFIG_MODE_SINGLE | ADS1115_CONFIG_DR_128SPS | ADS1115_CONFIG_COMP_MODE_TRAD | ADS1115_CONFIG_COMP_POL_LOW | ADS1115_CONFIG_COMP_LAT_NON | ADS1115_CONFIG_COMP_QUE_DISABLE) & 0xFF;

    if (i2cWriteDevice(i2c_handle, (char *)config, 3) != 0) {
        fprintf(stderr, "Error writing to ADS1115 config register\n");
        return -1;
    }

    // Wait for conversion to complete (at least 8ms for 128 SPS)
    gpioDelay(10000); // 10ms

    // Read conversion result
    config[0] = ADS1115_REG_CONVERT;
    if (i2cWriteDevice(i2c_handle, (char *)config, 1) != 0) {
        fprintf(stderr, "Error writing to ADS1115 conversion register\n");
        return -1;
    }

    if (i2cReadDevice(i2c_handle, (char *)data, 2) != 2) {
        fprintf(stderr, "Error reading from ADS1115 conversion register\n");
        return -1;
    }

    *value = (int16_t)((data[0] << 8) | data[1]);
    return 0;
}

// Publish data to MQTT broker
int publish_mqtt(int16_t value) {
    char payload[50];
    struct timeval tv;
    struct tm *tm_info;

    gettimeofday(&tv, NULL);
    tm_info = localtime(&tv.tv_sec);

    strftime(payload, sizeof(payload), "%Y-%m-%d %H:%M:%S", tm_info);
    snprintf(payload + strlen(payload), sizeof(payload) - strlen(payload), ".%06ld", tv.tv_usec);
    snprintf(payload + strlen(payload), sizeof(payload) - strlen(payload), ",%d", value);

    int ret = mosquitto_publish(mosq, NULL, MQTT_TOPIC, strlen(payload), payload, 0, false);
    if (ret != MOSQ_ERR_SUCCESS) {
        fprintf(stderr, "Error publishing to MQTT: %s\n", mosquitto_strerror(ret));
        return -1;
    }
    return 0;
}

// Cleanup resources
void cleanup() {
    printf("Cleaning up...\n");
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
    }
    if (mosq) {
        mosquitto_disconnect(mosq);
        mosquitto_destroy(mosq);
        mosquitto_lib_cleanup();
    }
    gpioTerminate();
}

int main() {
    int16_t sensor_value;
    int i;

    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Initialize I2C
    if (init_i2c() != 0) {
        gpioTerminate();
        return 1;
    }

    // Initialize MQTT
    mosquitto_lib_init();
    mosq = mosquitto_new(MQTT_CLIENT_ID, true, NULL);
    if (!mosq) {
        fprintf(stderr, "Error: Out of memory.\n");
        cleanup();
        return 1;
    }

    int ret = mosquitto_connect(mosq, MQTT_BROKER_ADDRESS, MQTT_BROKER_PORT, 60);
    if (ret != MOSQ_ERR_SUCCESS) {
        fprintf(stderr, "Error connecting to MQTT broker: %s\n", mosquitto_strerror(ret));
        cleanup();
        return 1;
    }

    mosquitto_loop_start(mosq);

    // Set up signal handler
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Main loop
    for (i = 0; i < 10 && !terminate; i++) {
        if (read_ads1115(&sensor_value) == 0) {
            if (publish_mqtt(sensor_value) != 0) {
                fprintf(stderr, "Error publishing sensor data\n");
            } else {
                printf("Published sensor value: %d\n", sensor_value);
            }
        } else {
            fprintf(stderr, "Error reading sensor data\n");
        }
        gpioDelay(1000000); // 1 second delay
    }

    // Cleanup and exit
    mosquitto_loop_stop(mosq, false);
    cleanup();
    return 0;
}

#include <stdio.h>
