// Define GPIO pins
#define GPIO_17 17
#define GPIO_18 18

// Define chip name
#define CHIP_NAME "gpiochip0"

// Global variables for GPIO lines and chip
struct gpiod_line *gpio_line_17 = NULL;
struct gpiod_line *gpio_line_18 = NULL;
struct gpiod_chip *gpio_chip = NULL;

// Signal handler for Ctrl+C
void signal_handler(int sig) {
    printf("\nCaught signal %d, cleaning up...\n", sig);

    // Release GPIO lines
    if (gpio_line_17) {
        gpiod_line_release(gpio_line_17);
    }
    if (gpio_line_18) {
        gpiod_line_release(gpio_line_18);
    }

    // Close GPIO chip
    if (gpio_chip) {
        gpiod_chip_close(gpio_chip);
    }

    exit(0);
}

int main() {
    // Register signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    // Open GPIO chip
    gpio_chip = gpiod_chip_open_by_name(CHIP_NAME);
    if (!gpio_chip) {
        fprintf(stderr, "Error opening GPIO chip '%s': %s\n", CHIP_NAME, strerror(errno));
        return 1;
    }

    // Get GPIO lines for GPIO 17 and GPIO 18
    gpio_line_17 = gpiod_chip_get_line(gpio_chip, GPIO_17);
    if (!gpio_line_17) {
        fprintf(stderr, "Error getting GPIO line %d: %s\n", GPIO_17, strerror(errno));
        gpiod_chip_close(gpio_chip);
        return 1;
    }

    gpio_line_18 = gpiod_chip_get_line(gpio_chip, GPIO_18);
    if (!gpio_line_18) {
        fprintf(stderr, "Error getting GPIO line %d: %s\n", GPIO_18, strerror(errno));
        gpiod_line_release(gpio_line_17);
        gpiod_chip_close(gpio_chip);
        return 1;
    }

    // Request GPIO lines for output
    if (gpiod_line_request_output(gpio_line_17, "gpio_output", 0) < 0) {
        fprintf(stderr, "Error requesting GPIO line %d for output: %s\n", GPIO_17, strerror(errno));
        gpiod_line_release(gpio_line_17);
        gpiod_line_release(gpio_line_18);
        gpiod_chip_close(gpio_chip);
        return 1;
    }

    if (gpiod_line_request_output(gpio_line_18, "gpio_output", 0) < 0) {
        fprintf(stderr, "Error requesting GPIO line %d for output: %s\n", GPIO_18, strerror(errno));
        gpiod_line_release(gpio_line_17);
        gpiod_line_release(gpio_line_18);
        gpiod_chip_close(gpio_chip);
        return 1;
    }

    // Main loop
    while (1) {
        // Set GPIO 17 HIGH
        if (gpiod_line_set_value(gpio_line_17, 1) < 0) {
            fprintf(stderr, "Error setting GPIO line %d HIGH: %s\n", GPIO_17, strerror(errno));
            break; // Exit loop on error
        }
        printf("GPIO %d HIGH\n", GPIO_17);

        // Set GPIO 18 LOW
        if (gpiod_line_set_value(gpio_line_18, 0) < 0) {
            fprintf(stderr, "Error setting GPIO line %d LOW: %s\n", GPIO_18, strerror(errno));
            break; // Exit loop on error
        }
        printf("GPIO %d LOW\n", GPIO_18);

        // Wait for 50 milliseconds
        struct timespec sleep_time;
        sleep_time.tv_sec = 0;
        sleep_time.tv_nsec = 50 * 1000 * 1000; // 50 milliseconds
        nanosleep(&sleep_time, NULL);

        // Set GPIO 17 LOW
        if (gpiod_line_set_value(gpio_line_17, 0) < 0) {
            fprintf(stderr, "Error setting GPIO line %d LOW: %s\n", GPIO_17, strerror(errno));
            break; // Exit loop on error
        }
        printf("GPIO %d LOW\n", GPIO_17);

        // Set GPIO 18 HIGH
        if (gpiod_line_set_value(gpio_line_18, 1) < 0) {
            fprintf(stderr, "Error setting GPIO line %d HIGH: %s\n", GPIO_18, strerror(errno));
            break; // Exit loop on error
        }
        printf("GPIO %d HIGH\n", GPIO_18);

        // Wait for 50 milliseconds
        nanosleep(&sleep_time, NULL);
    }

    // Cleanup (should not reach here if signal handler works correctly)
    gpiod_line_release(gpio_line_17);
    gpiod_line_release(gpio_line_18);
    gpiod_chip_close(gpio_chip);

    return 1;
}

