    program_running = 0;
    printf("\nCaught signal %d, exiting gracefully...\n", signal);
}

int main() {
    int gpio_status;

    // Register signal handlers for SIGINT and SIGTERM
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize the pigpio library
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO 17 as an output
    gpioSetMode(GPIO_PIN, PI_OUTPUT);

    printf("GPIO %d set as output.  Toggling every 5 seconds. Press Ctrl+C to exit.\n", GPIO_PIN);

    // Main loop to toggle the GPIO state
    while (program_running) {
        // Set GPIO high
        gpioWrite(GPIO_PIN, 1);
        gpio_status = gpioRead(GPIO_PIN);
        printf("GPIO %d set to HIGH (read: %d)\n", GPIO_PIN, gpio_status);

        // Wait for 5 seconds
        sleep(5);

        // Set GPIO low
        gpioWrite(GPIO_PIN, 0);
        gpio_status = gpioRead(GPIO_PIN);
        printf("GPIO %d set to LOW (read: %d)\n", GPIO_PIN, gpio_status);

        // Wait for 5 seconds
        sleep(5);
    }

    // Clean up and terminate the pigpio library
    gpioTerminate();
    printf("pigpio terminated.\n");

    return 0;
}

