#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <fcntl.h>
#include <termios.h>
#include <unistd.h>
#include <signal.h>
#include <errno.h>

#define UART_PORT "/dev/ttyS0" // Or /dev/ttyAMA0
#define BAUD_RATE B115200
#define MAX_BUFFER 256

volatile sig_atomic_t program_running = 1;
int uart_fd = -1;

void signal_handler(int signal) {
    program_running = 0;
    printf("\nCaught signal %d, exiting gracefully.\n", signal);
}

int setup_uart(const char *port, speed_t baud_rate) {
    int fd = open(port, O_RDWR | O_NOCTTY | O_SYNC);
    if (fd == -1) {
        perror("Error opening UART port");
        return -1;
    }

    struct termios tty;
    if (tcgetattr(fd, &tty) != 0) {
        perror("Error getting termios attributes");
        close(fd);
        return -1;
    }

    tty.c_cflag = baud_rate | CS8 | CLOCAL | CREAD;  // 8N1, no parity
    tty.c_iflag = IGNPAR;                           // Ignore parity errors
    tty.c_oflag = 0;
    tty.c_lflag = 0; // Non-canonical mode

    tty.c_cc[VMIN] = 0;  // Read doesn't block
    tty.c_cc[VTIME] = 5; // 0.5 seconds read timeout

    if (tcsetattr(fd, TCSANOW, &tty) != 0) {
        perror("Error setting termios attributes");
        close(fd);
        return -1;
    }

    return fd;
}

int read_data(int fd, char *buffer, size_t max_len) {
    ssize_t bytes_read = read(fd, buffer, max_len - 1);
    if (bytes_read == -1) {
        perror("Error reading from UART");
        return -1;
    } else if (bytes_read == 0) {
        // Timeout or no data
        return 0;
    } else {
        buffer[bytes_read] = '\0'; // Null-terminate the string
        return bytes_read;
    }
}

int main() {
    signal(SIGINT, signal_handler);

    uart_fd = setup_uart(UART_PORT, BAUD_RATE);
    if (uart_fd == -1) {
        return EXIT_FAILURE;
    }

    char buffer[MAX_BUFFER];

    printf("Reading data from %s at %d baud...\n", UART_PORT, BAUD_RATE);

    while (program_running) {
        int bytes_read = read_data(uart_fd, buffer, sizeof(buffer));
        if (bytes_read > 0) {
            printf("Received: %s", buffer);
        } else if (bytes_read < 0) {
            // Error already printed in read_data
            break;
        }
        usleep(100000); // 100ms delay
    }

    if (uart_fd != -1) {
        close(uart_fd);
    }

    printf("Program finished.\n");
    return EXIT_SUCCESS;
}

