void signal_handler(int sig) {
    program_running = 0;
    printf("\nExiting program...\n");
}

// Function to read a single byte from an I2C register
int read_i2c_reg(int fd, uint8_t reg) {
    if (write(fd, &reg, 1) != 1) {
        perror("Failed to write register address");
        return -1;
    }
    uint8_t value;
    if (read(fd, &value, 1) != 1) {
        perror("Failed to read register value");
        return -1;
    }
    return value;
}

// Function to write a single byte to an I2C register
int write_i2c_reg(int fd, uint8_t reg, uint8_t value) {
    uint8_t buf[2];
    buf[0] = reg;
    buf[1] = value;
    if (write(fd, buf, 2) != 2) {
        perror("Failed to write register value");
        return -1;
    }
    return 0;
}

// Function to read accelerometer data
int read_accelerometer_data(int fd, int16_t *x, int16_t *y, int16_t *z) {
    uint8_t buffer[6];
    uint8_t reg = ACCEL_XOUT_H;

    if (write(fd, &reg, 1) != 1) {
        perror("Failed to write register address");
        return -1;
    }

    if (read(fd, buffer, 6) != 6) {
        perror("Failed to read accelerometer data");
        return -1;
    }

    *x = (int16_t)((buffer[0] << 8) | buffer[1]);
    *y = (int16_t)((buffer[2] << 8) | buffer[3]);
    *z = (int16_t)((buffer[4] << 8) | buffer[5]);

    return 0;
}

int main() {
    // Register signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    // Open I2C device
    i2c_fd = open("/dev/i2c-1", O_RDWR);
    if (i2c_fd < 0) {
        perror("Failed to open I2C device");
        return 1;
    }

    // Specify slave address
    if (ioctl(i2c_fd, I2C_SLAVE, MPU6050_ADDR) < 0) {
        perror("Failed to acquire bus access and/or talk to slave");
        close(i2c_fd);
        return 1;
    }

    // Wake up the MPU6050
    if (write_i2c_reg(i2c_fd, PWR_MGMT_1, 0) < 0) {
        fprintf(stderr, "Failed to wake up MPU6050\n");
        close(i2c_fd);
        return 1;
    }

    printf("MPU6050 initialized. Reading accelerometer data...\n");

    // Main loop
    while (program_running) {
        int16_t x, y, z;

        if (read_accelerometer_data(i2c_fd, &x, &y, &z) == 0) {
            printf("X: %6d, Y: %6d, Z: %6d\n", x, y, z);
        } else {
            fprintf(stderr, "Failed to read accelerometer data. Retrying...\n");
        }

        usleep(100000); // 0.1 seconds
    }

    // Close I2C device
    close(i2c_fd);

    return 0;
}

#include <stdio.h>
