// BMP280 I2C address
#define BMP280_I2C_ADDR 0x76

// BMP280 register addresses
#define BMP280_REG_TEMP_MSB 0xFA
#define BMP280_REG_TEMP_LSB 0xFB
#define BMP280_REG_TEMP_XLSB 0xFC
#define BMP280_REG_PRESS_MSB 0xF7
#define BMP280_REG_PRESS_LSB 0xF8
#define BMP280_REG_PRESS_XLSB 0xF9
#define BMP280_REG_CONFIG 0xF5
#define BMP280_REG_CTRL_MEAS 0xF4
#define BMP280_REG_RESET 0xE0

// Calibration data registers
#define BMP280_REG_CALIB_00 0x88

// Global variables
int i2c_fd;
volatile sig_atomic_t program_running = 1;

// Calibration data structure
struct bmp280_calib_data {
    uint16_t dig_T1;
    int16_t dig_T2;
    int16_t dig_T3;
    uint16_t dig_P1;
    int16_t dig_P2;
    int16_t dig_P3;
    int16_t dig_P4;
    int16_t dig_P5;
    int16_t dig_P6;
    int16_t dig_P7;
    int16_t dig_P8;
    int16_t dig_P9;
};

struct bmp280_calib_data calib;

// Function prototypes
int init_i2c(int address);
int read_calibration_data(int fd, struct bmp280_calib_data *calib);
int read_raw_data(int fd, int32_t *temperature, int32_t *pressure);
double compensate_temperature(int32_t raw_temp, struct bmp280_calib_data calib);
double compensate_pressure(int32_t raw_pressure, int32_t t_fine, struct bmp280_calib_data calib);
void signal_handler(int signal);

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    program_running = 0;
    printf("\nCaught signal %d, exiting gracefully.\n", signal);
}

// Initialize I2C communication
int init_i2c(int address) {
    int fd = open("/dev/i2c-1", O_RDWR);
    if (fd < 0) {
        perror("Error opening I2C device");
        return -1;
    }

    if (ioctl(fd, I2C_SLAVE, address) < 0) {
        perror("Error setting I2C slave address");
        close(fd);
        return -1;
    }

    return fd;
}

// Read calibration data from BMP280
int read_calibration_data(int fd, struct bmp280_calib_data *calib) {
    uint8_t data[26];
    if (read(fd, data, 26) != 26) {
        perror("Error reading calibration data");
        return -1;
    }

    calib->dig_T1 = (uint16_t)data[0] | ((uint16_t)data[1] << 8);
    calib->dig_T2 = (int16_t)data[2] | ((int16_t)data[3] << 8);
    calib->dig_T3 = (int16_t)data[4] | ((int16_t)data[5] << 8);
    calib->dig_P1 = (uint16_t)data[6] | ((uint16_t)data[7] << 8);
    calib->dig_P2 = (int16_t)data[8] | ((int16_t)data[9] << 8);
    calib->dig_P3 = (int16_t)data[10] | ((int16_t)data[11] << 8);
    calib->dig_P4 = (int16_t)data[12] | ((int16_t)data[13] << 8);
    calib->dig_P5 = (int16_t)data[14] | ((int16_t)data[15] << 8);
    calib->dig_P6 = (int16_t)data[16] | ((int16_t)data[17] << 8);
    calib->dig_P7 = (int16_t)data[18] | ((int16_t)data[19] << 8);
    calib->dig_P8 = (int16_t)data[20] | ((int16_t)data[21] << 8);
    calib->dig_P9 = (int16_t)data[22] | ((int16_t)data[23] << 8);

    return 0;
}

// Read raw temperature and pressure data from BMP280
int read_raw_data(int fd, int32_t *temperature, int32_t *pressure) {
    uint8_t data[6];
    if (read(fd, data, 6) != 6) {
        perror("Error reading raw data");
        return -1;
    }

    *pressure = ((int32_t)data[0] << 12) | ((int32_t)data[1] << 4) | ((int32_t)data[2] >> 4);
    *temperature = ((int32_t)data[3] << 12) | ((int32_t)data[4] << 4) | ((int32_t)data[5] >> 4);

    return 0;
}

// Compensate temperature using calibration data
double compensate_temperature(int32_t raw_temp, struct bmp280_calib_data calib) {
    double var1, var2, T;
    var1 = (((double)raw_temp) / 16384.0 - ((double)calib.dig_T1) / 1024.0) * ((double)calib.dig_T2);
    var2 = ((((double)raw_temp) / 131072.0 - ((double)calib.dig_T1) / 8192.0) * (((double)raw_temp) / 131072.0 - ((double)calib.dig_T1) / 8192.0)) * ((double)calib.dig_T3);
    double t_fine = (var1 + var2);
    T = (t_fine / 5120.0);
    return T;
}

// Compensate pressure using calibration data
double compensate_pressure(int32_t raw_pressure, int32_t t_fine, struct bmp280_calib_data calib) {
    double var1, var2, p;
    var1 = ((double)t_fine / 2.0) - 64000.0;
    var2 = var1 * var1 * ((double)calib.dig_P6) / 32768.0;
    var2 = var2 + var1 * ((double)calib.dig_P5) * 2.0;
    var2 = (var2 / 4.0) + (((double)calib.dig_P4) * 65536.0);
    var1 = (((double)calib.dig_P3) * var1 * var1 / 524288.0 + ((double)calib.dig_P2) * var1) / 524288.0;
    var1 = (1.0 + var1 / 32768.0) * ((double)calib.dig_P1);
    if (var1 == 0)
    {
        return 0;
    }
    p = 1048576.0 - (double)raw_pressure;
    p = (p - (var2 / 4096.0)) * 6250.0 / var1;
    var1 = ((double)calib.dig_P9) * p * p / 2147483648.0;
    var2 = p * ((double)calib.dig_P8) / 32768.0;
    p = p + (var1 + var2 + ((double)calib.dig_P7)) / 16.0;
    return p;
}

int main() {
    // Register signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    // Initialize I2C
    i2c_fd = init_i2c(BMP280_I2C_ADDR);
    if (i2c_fd < 0) {
        fprintf(stderr, "Failed to initialize I2C. Exiting.\n");
        return 1;
    }

    // Read calibration data
    if (read_calibration_data(i2c_fd, &calib) < 0) {
        fprintf(stderr, "Failed to read calibration data. Exiting.\n");
        close(i2c_fd);
        return 1;
    }

    // Set BMP280 to forced mode
    uint8_t ctrl_meas = 0b00100111; // Oversampling x1, Normal mode
    if (write(i2c_fd, &ctrl_meas, 1) != 1) {
        perror("Error writing to control register");
        close(i2c_fd);
        return 1;
    }

    // Main loop
    while (program_running) {
        int32_t raw_temperature, raw_pressure;

        // Read raw data
        if (read_raw_data(i2c_fd, &raw_temperature, &raw_pressure) < 0) {
            fprintf(stderr, "Failed to read raw data. Retrying in 5 seconds.\n");
            sleep(5);
            continue;
        }

        // Compensate temperature and pressure
        double temperature = compensate_temperature(raw_temperature, calib);
        double pressure = compensate_pressure(raw_pressure, 0, calib); // t_fine is not used here, but needs to be passed

        // Print temperature and pressure
        printf("Temperature: %.2f °C, Pressure: %.2f Pa\n", temperature, pressure);

        // Wait 5 seconds
        sleep(5);
    }

    // Close I2C device
    close(i2c_fd);

    return 0;
}

#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <pigpio.h>

#define GPIO_PIN 4
#define PWM_FREQUENCY 1000
#define PWM_RANGE 1000

volatile sig_atomic_t program_running = 1;

void signal_handler(int signal) {
    program_running = 0;
    printf("\nCaught signal %d, exiting gracefully...\n", signal);
}

int main() {
    int duty_cycle;

    // Register signal handlers for graceful shutdown
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize pigpio library
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO 4 as output
    gpioSetMode(GPIO_PIN, PI_OUTPUT);

    // Set PWM frequency
    gpioSetPWMfrequency(GPIO_PIN, PWM_FREQUENCY);

    // Set PWM range
    gpioSetPWMrange(GPIO_PIN, PWM_RANGE);

    // Main loop
    while (program_running) {
        // Cycle through duty cycles
        for (duty_cycle = 0; duty_cycle <= PWM_RANGE; duty_cycle += 10) {
            gpioPWM(GPIO_PIN, duty_cycle);
            printf("Duty Cycle: %d\n", duty_cycle);
            gpioDelay(100000); // 100ms delay
        }

        for (duty_cycle = PWM_RANGE; duty_cycle >= 0; duty_cycle -= 10) {
            gpioPWM(GPIO_PIN, duty_cycle);
            printf("Duty Cycle: %d\n", duty_cycle);
            gpioDelay(100000); // 100ms delay
        }
    }

    // Stop PWM output
    gpioPWM(GPIO_PIN, 0);

    // Release GPIO resources
    gpioTerminate();

    printf("Program terminated.\n");
    return 0;
}

#include <stdio.h>
#include <stdlib.h>
#include <gpiod.h>
#include <unistd.h>
#include <signal.h>
#include <errno.h>

// Define GPIO pins
#define GPIO_5 5
#define GPIO_6 6
#define GPIO_13 13

// Global variables for GPIO lines and chip
struct gpiod_line *gpio_line_5 = NULL;
struct gpiod_line *gpio_line_6 = NULL;
struct gpiod_line *gpio_line_13 = NULL;
struct gpiod_chip *gpio_chip = NULL;

// Signal handler for Ctrl+C
void signal_handler(int sig) {
    printf("\nCaught signal %d, cleaning up...\n", sig);

    // Set GPIO lines to input (safe state)
    if (gpio_line_5) {
        if (gpiod_line_set_value(gpio_line_5, 0) < 0) {
            perror("Error setting GPIO 5 to input");
        }
    }
    if (gpio_line_6) {
        if (gpiod_line_set_value(gpio_line_6, 0) < 0) {
            perror("Error setting GPIO 6 to input");
        }
    }
    if (gpio_line_13) {
        if (gpiod_line_set_value(gpio_line_13, 0) < 0) {
            perror("Error setting GPIO 13 to input");
        }
    }

    // Release GPIO lines
    if (gpio_line_5) {
        gpiod_line_release(gpio_line_5);
    }
    if (gpio_line_6) {
        gpiod_line_release(gpio_line_6);
    }
    if (gpio_line_13) {
        gpiod_line_release(gpio_line_13);
    }

    // Close GPIO chip
    if (gpio_chip) {
        gpiod_chip_close(gpio_chip);
    }

    exit(0);
}

int main() {
    // Register signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    // Open GPIO chip
    gpio_chip = gpiod_chip_open_by_name("gpiochip0");
    if (!gpio_chip) {
        perror("Error opening GPIO chip");
        return 1;
    }

    // Get GPIO lines
    gpio_line_5 = gpiod_chip_get_line(gpio_chip, GPIO_5);
    gpio_line_6 = gpiod_chip_get_line(gpio_chip, GPIO_6);
    gpio_line_13 = gpiod_chip_get_line(gpio_chip, GPIO_13);

    if (!gpio_line_5 || !gpio_line_6 || !gpio_line_13) {
        perror("Error getting GPIO line");
        gpiod_chip_close(gpio_chip);
        return 1;
    }

    // Request GPIO lines for output
    if (gpiod_line_request_output(gpio_line_5, "gpio_output", 1) < 0) {
        perror("Error requesting GPIO 5 for output");
        gpiod_line_release(gpio_line_5);
        gpiod_line_release(gpio_line_6);
        gpiod_line_release(gpio_line_13);
        gpiod_chip_close(gpio_chip);
        return 1;
    }
    if (gpiod_line_request_output(gpio_line_6, "gpio_output", 0) < 0) {
        perror("Error requesting GPIO 6 for output");
        gpiod_line_release(gpio_line_5);
        gpiod_line_release(gpio_line_6);
        gpiod_line_release(gpio_line_13);
        gpiod_chip_close(gpio_chip);
        return 1;
    }
    if (gpiod_line_request_output(gpio_line_13, "gpio_output", 1) < 0) {
        perror("Error requesting GPIO 13 for output");
        gpiod_line_release(gpio_line_5);
        gpiod_line_release(gpio_line_6);
        gpiod_line_release(gpio_line_13);
        gpiod_chip_close(gpio_chip);
        return 1;
    }

    // Set GPIO line values and print to standard output
    int value_5 = gpiod_line_get_value(gpio_line_5);
    int value_6 = gpiod_line_get_value(gpio_line_6);
    int value_13 = gpiod_line_get_value(gpio_line_13);

    printf("GPIO 5: %d\n", value_5);
    printf("GPIO 6: %d\n", value_6);
    printf("GPIO 13: %d\n", value_13);

    // Release GPIO lines
    gpiod_line_release(gpio_line_5);
    gpiod_line_release(gpio_line_6);
    gpiod_line_release(gpio_line_13);

    // Close GPIO chip
    gpiod_chip_close(gpio_chip);

    return 0;
}

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <signal.h>
#include <unistd.h>
#include <time.h>
#include <pigpio.h>
#include <mosquitto.h>

// Configuration
#define MQTT_BROKER "localhost" // Change this to your MQTT broker address
#define MQTT_PORT 1883
#define MQTT_TOPIC "sensor/data"
#define DHT22_GPIO 4
#define SLEEP_INTERVAL 5 // seconds

// Global variables
static volatile int running = 1;
static struct mosquitto *mosq = NULL;

// Function prototypes
void signal_handler(int signum);
int read_dht22(int gpio, float *temperature, float *humidity);
int publish_data(float temperature, float humidity);

// Signal handler for graceful shutdown
void signal_handler(int signum) {
    if (signum == SIGINT) {
        printf("Received SIGINT, shutting down...\n");
        running = 0;
    }
}

// Function to read DHT22 sensor data
int read_dht22(int gpio, float *temperature, float *humidity) {
    int data[5] = {0, 0, 0, 0, 0};
    int laststate = PI_HIGH;
    int j = 0;

    gpioSetMode(gpio, PI_OUTPUT);
    gpioWrite(gpio, PI_LOW);
    gpioDelay(18); // > 18ms
    gpioWrite(gpio, PI_HIGH);
    gpioDelay(40); // 20-40us
    gpioSetMode(gpio, PI_INPUT);

    // Read data
    for (int i = 0; i < 85; i++) {
        int counter = 0;
        while (gpioRead(gpio) == laststate) {
            counter++;
            gpioDelay(1); // Delay 1us
            if (counter == 255) {
                return -1; // Timeout
            }
        }
        laststate = gpioRead(gpio);

        if (counter > 3) {
            data[j / 8] <<= 1;
            if (counter > 16) // Changed from 16 to 26 to accommodate longer pulses
                data[j / 8] |= 1;
            j++;
        }
    }

    // Check checksum
    if (j >= 40 && (data[4] == ((data[0] + data[1] + data[2] + data[3]) & 0xFF))) {
        *humidity = (float)(((data[0] << 8) + data[1])) / 10.0;
        *temperature = (float)(((data[2] << 8) + data[3])) / 10.0;
        if (*temperature > 125) {
            *temperature = *temperature - 256;
        }
        return 0; // Success
    } else {
        return -1; // Checksum error
    }
}

// Function to publish data to MQTT broker
int publish_data(float temperature, float humidity) {
    char payload[100];
    snprintf(payload, sizeof(payload), "{\"temperature\": %.2f, \"humidity\": %.2f}", temperature, humidity);

    int ret = mosquitto_publish(mosq, NULL, MQTT_TOPIC, strlen(payload), payload, 0, false);
    if (ret != MOSQ_ERR_SUCCESS) {
        fprintf(stderr, "Error publishing message: %s\n", mosquitto_strerror(ret));
        return -1;
    }
    return 0;
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Initialize libmosquitto
    mosquitto_lib_init();
    mosq = mosquitto_new(NULL, true, NULL);
    if (!mosq) {
        fprintf(stderr, "Error: Out of memory.\n");
        gpioTerminate();
        return 1;
    }

    // Connect to MQTT broker
    int ret = mosquitto_connect(mosq, MQTT_BROKER, MQTT_PORT, 60);
    if (ret != MOSQ_ERR_SUCCESS) {
        fprintf(stderr, "Error connecting to MQTT broker: %s\n", mosquitto_strerror(ret));
        mosquitto_destroy(mosq);
        mosquitto_lib_cleanup();
        gpioTerminate();
        return 1;
    }

    // Set signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    float temperature, humidity;

    // Main loop
    while (running) {
        // Read sensor data
        if (read_dht22(DHT22_GPIO, &temperature, &humidity) == 0) {
            printf("Temperature: %.2f °C, Humidity: %.2f %%\n", temperature, humidity);

            // Publish data
            if (publish_data(temperature, humidity) != 0) {
                fprintf(stderr, "Failed to publish data.\n");
            }
        } else {
            fprintf(stderr, "Failed to read DHT22 sensor data.\n");
        }

        // Sleep for the specified interval
        sleep(SLEEP_INTERVAL);
    }

    // Disconnect from MQTT broker
    mosquitto_disconnect(mosq);
    mosquitto_destroy(mosq);
    mosquitto_lib_cleanup();

    // Terminate pigpio
    gpioTerminate();

    printf("Program terminated.\n");
    return 0;
}

#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <pigpio.h>

// Define GPIO pins
#define GPIO_2 2
#define GPIO_3 3
#define GPIO_18 18
#define GPIO_23 23
#define GPIO_24 24

// Define PWM frequency
#define PWM_FREQUENCY 1000

// Global variable to indicate program termination
volatile sig_atomic_t program_running = 1;

// Signal handler for Ctrl+C
void signal_handler(int signal) {
    program_running = 0;
    printf("\nCaught signal %d, exiting gracefully...\n", signal);
}

// Function to set PWM duty cycle for a given GPIO pin
void set_pwm_duty_cycle(int gpio, int duty_cycle) {
    gpioPWM(gpio, duty_cycle);
}

// Function to report the state of a GPIO pin
void report_gpio_state(int gpio) {
    int level = gpioRead(gpio);
    printf("GPIO %d: %d\n", gpio, level);
}

int main() {
    // Initialize pigpio library
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO pins as outputs
    gpioSetMode(GPIO_2, PI_OUTPUT);
    gpioSetMode(GPIO_3, PI_OUTPUT);
    gpioSetMode(GPIO_18, PI_OUTPUT);
    gpioSetMode(GPIO_23, PI_OUTPUT);
    gpioSetMode(GPIO_24, PI_OUTPUT);

    // Set PWM frequency for all GPIO pins
    gpioSetPWMfrequency(GPIO_2, PWM_FREQUENCY);
    gpioSetPWMfrequency(GPIO_3, PWM_FREQUENCY);
    gpioSetPWMfrequency(GPIO_18, PWM_FREQUENCY);
    gpioSetPWMfrequency(GPIO_23, PWM_FREQUENCY);
    gpioSetPWMfrequency(GPIO_24, PWM_FREQUENCY);

    // Set PWM range (0-255)
    gpioSetPWMrange(GPIO_2, 255);
    gpioSetPWMrange(GPIO_3, 255);
    gpioSetPWMrange(GPIO_18, 255);
    gpioSetPWMrange(GPIO_23, 255);
    gpioSetPWMrange(GPIO_24, 255);

    // Register signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    // Main loop
    while (program_running) {
        // Set PWM duty cycles for each GPIO pin
        set_pwm_duty_cycle(GPIO_2, 128);
        set_pwm_duty_cycle(GPIO_3, 128);
        set_pwm_duty_cycle(GPIO_18, 128);
        set_pwm_duty_cycle(GPIO_23, 128);
        set_pwm_duty_cycle(GPIO_24, 128);

        // Report GPIO states
        report_gpio_state(GPIO_2);
        report_gpio_state(GPIO_3);
        report_gpio_state(GPIO_18);
        report_gpio_state(GPIO_23);
        report_gpio_state(GPIO_24);

        // Delay for 1 second
        gpioDelay(1000); // Delay in milliseconds
    }

    // Stop PWM signals
    gpioPWM(GPIO_2, 0);
    gpioPWM(GPIO_3, 0);
    gpioPWM(GPIO_18, 0);
    gpioPWM(GPIO_23, 0);
    gpioPWM(GPIO_24, 0);

    // Terminate pigpio library
    gpioTerminate();

    return 0;
}

