// Function to capture an image
int capture_image(const char *filename)
{
    struct v4l2_buffer buf;
    int i;

    for (i = 0; i < NUM_BUFFERS; ++i) {
        memset(&buf, 0, sizeof(buf));
        buf.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
        buf.memory = V4L2_MEMORY_MMAP;
        buf.index = i;

        if (ioctl(fd, VIDIOC_QBUF, &buf) < 0) {
            perror("Error queuing buffer");
            return -1;
        }
    }

    enum v4l2_buf_type type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    if (ioctl(fd, VIDIOC_STREAMON, &type) < 0) {
        perror("Error starting stream");
        return -1;
    }

    fd_set fds;
    struct timeval tv;
    int r;

    FD_ZERO(&fds);
    FD_SET(fd, &fds);

    tv.tv_sec = 2; // Timeout of 2 seconds
    tv.tv_usec = 0;

    r = select(fd + 1, &fds, NULL, NULL, &tv);

    if (r == -1) {
        perror("Error during select");
        ioctl(fd, VIDIOC_STREAMOFF, &type);
        return -1;
    }

    if (r == 0) {
        fprintf(stderr, "Select timeout\n");
        ioctl(fd, VIDIOC_STREAMOFF, &type);
        return -1;
    }

    memset(&buf, 0, sizeof(buf));
    buf.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    buf.memory = V4L2_MEMORY_MMAP;

    if (ioctl(fd, VIDIOC_DQBUF, &buf) < 0) {
        perror("Error dequeuing buffer");
        ioctl(fd, VIDIOC_STREAMOFF, &type);
        return -1;
    }

    FILE *fp = fopen(filename, "wb");
    if (!fp) {
        perror("Error opening file for writing");
        ioctl(fd, VIDIOC_STREAMOFF, &type);
        return -1;
    }

    fwrite(buffers[buf.index].start, buf.bytesused, 1, fp);
    fclose(fp);

    if (ioctl(fd, VIDIOC_QBUF, &buf) < 0) {
        perror("Error queuing buffer");
        ioctl(fd, VIDIOC_STREAMOFF, &type);
        return -1;
    }

    if (ioctl(fd, VIDIOC_STREAMOFF, &type) < 0) {
        perror("Error stopping stream");
        return -1;
    }

    return 0;
}

// Function to release resources
void release_resources()
{
    int i;

    if (fd != -1) {
        enum v4l2_buf_type type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
        ioctl(fd, VIDIOC_STREAMOFF, &type);

        for (i = 0; i < NUM_BUFFERS; ++i) {
            if (buffers[i].start != MAP_FAILED) {
                munmap(buffers[i].start, buffers[i].length);
            }
        }

        free(buffers);
        close(fd);
    }
}

int main()
{
    signal(SIGINT, signal_handler);

    if (init_camera(DEVICE_NAME) < 0) {
        fprintf(stderr, "Camera initialization failed. Check if %s is present and accessible.\n", DEVICE_NAME);
        return 1;
    }

    printf("Camera initialized successfully.\n");

    if (capture_image("image.yuv") < 0) {
        fprintf(stderr, "Image capture failed.\n");
        release_resources();
        return 1;
    }

    printf("Image captured successfully. Saved to image.yuv\n");

    release_resources();

    return 0;
}

#include <stdio.h>
#include <stdlib.h>
#include <gpiod.h>
#include <unistd.h>
#include <signal.h>
#include <errno.h>

// Define GPIO pins
#define GPIO_2 2
#define GPIO_3 3

// Global variables for GPIO lines and chip
struct gpiod_line *gpio_line_2 = NULL;
struct gpiod_line *gpio_line_3 = NULL;
struct gpiod_chip *gpio_chip = NULL;

// Signal handler for Ctrl+C
void signal_handler(int sig) {
    printf("\nCaught signal %d, cleaning up...\n", sig);

    // Release GPIO lines
    if (gpio_line_2) {
        gpiod_line_release(gpio_line_2);
    }
    if (gpio_line_3) {
        gpiod_line_release(gpio_line_3);
    }

    // Close GPIO chip
    if (gpio_chip) {
        gpiod_chip_close(gpio_chip);
    }

    exit(0);
}

int main() {
    // Register signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    // Open GPIO chip
    gpio_chip = gpiod_chip_open_by_name("gpiochip0");
    if (!gpio_chip) {
        fprintf(stderr, "Error opening GPIO chip: %s\n", strerror(errno));
        return 1;
    }

    // Get GPIO lines
    gpio_line_2 = gpiod_chip_get_line(gpio_chip, GPIO_2);
    if (!gpio_line_2) {
        fprintf(stderr, "Error getting GPIO %d line: %s\n", GPIO_2, strerror(errno));
        gpiod_chip_close(gpio_chip);
        return 1;
    }

    gpio_line_3 = gpiod_chip_get_line(gpio_chip, GPIO_3);
    if (!gpio_line_3) {
        fprintf(stderr, "Error getting GPIO %d line: %s\n", GPIO_3, strerror(errno));
        gpiod_line_release(gpio_line_2);
        gpiod_chip_close(gpio_chip);
        return 1;
    }

    // Request GPIO lines for output
    if (gpiod_line_request_output(gpio_line_2, "gpio_output", 0) < 0) {
        fprintf(stderr, "Error requesting GPIO %d for output: %s\n", GPIO_2, strerror(errno));
        gpiod_line_release(gpio_line_2);
        gpiod_line_release(gpio_line_3);
        gpiod_chip_close(gpio_chip);
        return 1;
    }

    if (gpiod_line_request_output(gpio_line_3, "gpio_output", 0) < 0) {
        fprintf(stderr, "Error requesting GPIO %d for output: %s\n", GPIO_3, strerror(errno));
        gpiod_line_release(gpio_line_2);
        gpiod_line_release(gpio_line_3);
        gpiod_chip_close(gpio_chip);
        return 1;
    }

    // Main loop
    while (1) {
        // Set GPIO 2 HIGH
        if (gpiod_line_set_value(gpio_line_2, 1) < 0) {
            fprintf(stderr, "Error setting GPIO %d HIGH: %s\n", GPIO_2, strerror(errno));
            break;
        }
        printf("GPIO %d set HIGH\n", GPIO_2);

        // Set GPIO 3 LOW
        if (gpiod_line_set_value(gpio_line_3, 0) < 0) {
            fprintf(stderr, "Error setting GPIO %d LOW: %s\n", GPIO_3, strerror(errno));
            break;
        }
        printf("GPIO %d set LOW\n", GPIO_3);

        // Wait for 0.5 seconds
        sleep(0.5);

        // Set GPIO 2 LOW
        if (gpiod_line_set_value(gpio_line_2, 0) < 0) {
            fprintf(stderr, "Error setting GPIO %d LOW: %s\n", GPIO_2, strerror(errno));
            break;
        }
        printf("GPIO %d set LOW\n", GPIO_2);

        // Set GPIO 3 HIGH
        if (gpiod_line_set_value(gpio_line_3, 1) < 0) {
            fprintf(stderr, "Error setting GPIO %d HIGH: %s\n", GPIO_3, strerror(errno));
            break;
        }
        printf("GPIO %d set HIGH\n", GPIO_3);

        // Wait for 0.5 seconds
        sleep(0.5);
    }

    // Cleanup (should not reach here if signal handler works correctly)
    gpiod_line_release(gpio_line_2);
    gpiod_line_release(gpio_line_3);
    gpiod_chip_close(gpio_chip);

    return 1;
}

#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

// Define GPIO pins
#define GPIO_17 17
#define GPIO_27 27

// Global variable to track program state for signal handling
volatile sig_atomic_t program_running = 1;

// Signal handler function
void signal_handler(int signal) {
    program_running = 0;
    printf("\nCaught signal %d, exiting gracefully...\n", signal);
}

// Function to set the state of a GPIO pin
int set_gpio_state(int gpio, int state) {
    if (gpioWrite(gpio, state) != 0) {
        fprintf(stderr, "Error writing to GPIO %d\n", gpio);
        return -1;
    }
    return 0;
}

// Function to get the state of a GPIO pin
int get_gpio_state(int gpio) {
    int state = gpioRead(gpio);
    if (state < 0) {
        fprintf(stderr, "Error reading GPIO %d\n", gpio);
        return -1;
    }
    return state;
}

int main() {
    // Register signal handlers for SIGINT and SIGTERM
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize the pigpio library
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Configure GPIO pins as outputs
    gpioSetMode(GPIO_17, PI_OUTPUT);
    gpioSetMode(GPIO_27, PI_OUTPUT);

    printf("GPIO control program started. Press Ctrl+C to exit.\n");

    // Main loop
    while (program_running) {
        // Set GPIO 17 HIGH
        if (set_gpio_state(GPIO_17, 1) != 0) {
            program_running = 0; // Exit loop on error
            break;
        }
        printf("GPIO 17: HIGH\n");

        // Wait for 1 second
        sleep(1);

        // Set GPIO 17 LOW
        if (set_gpio_state(GPIO_17, 0) != 0) {
            program_running = 0; // Exit loop on error
            break;
        }
        printf("GPIO 17: LOW\n");

        // Wait for 1 second
        sleep(1);

        // Set GPIO 27 HIGH
        if (set_gpio_state(GPIO_27, 1) != 0) {
            program_running = 0; // Exit loop on error
            break;
        }
        printf("GPIO 27: HIGH\n");

        // Wait for 1 second
        sleep(1);

        // Set GPIO 27 LOW
        if (set_gpio_state(GPIO_27, 0) != 0) {
            program_running = 0; // Exit loop on error
            break;
        }
        printf("GPIO 27: LOW\n");

        // Wait for 1 second
        sleep(1);
    }

    // Clean up and terminate the pigpio library
    gpioTerminate();
    printf("GPIO control program terminated.\n");

    return 0;
}

