        gpiod_line_release(line19);
        gpiod_chip_close(chip);
        return 1;
    }

    // Main loop
    while (1) {
        // Set GPIO 18 HIGH
        if (gpiod_line_set_value(line18, 1) < 0) {
            perror("Error setting GPIO 18 HIGH");
        }
        printf("GPIO 18 HIGH\n");

        // Set GPIO 19 LOW
        if (gpiod_line_set_value(line19, 0) < 0) {
            perror("Error setting GPIO 19 LOW");
