#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <fcntl.h>
#include <termios.h>
#include <unistd.h>
#include <signal.h>
#include <errno.h>

// Define the serial port device
#define SERIAL_PORT "/dev/ttyS0"

// Define the baud rate
#define BAUD_RATE B9600

// Define the data frame size
#define DATA_FRAME_SIZE 4

// Global variable for the serial port file descriptor
int serial_port_fd = -1;

// Signal handler for Ctrl+C
void signal_handler(int signal) {
    printf("\nCaught signal %d, cleaning up...\n", signal);

    // Close the serial port if it's open
    if (serial_port_fd != -1) {
        close(serial_port_fd);
        printf("Serial port closed.\n");
    }

    exit(0);
}

// Function to initialize the serial port
int init_serial_port(const char *port, speed_t baud_rate) {
    int fd = open(port, O_RDWR | O_NOCTTY | O_SYNC);
    if (fd == -1) {
        perror("Error opening serial port");
        return -1;
    }

    struct termios tty;
    if (tcgetattr(fd, &tty) != 0) {
        perror("Error getting termios attributes");
        close(fd);
        return -1;
    }

    tty.c_cflag = baud_rate | CS8 | CLOCAL | CREAD;  // 9600 baud, 8 data bits, no parity, 1 stop bit
    tty.c_iflag = IGNPAR;                           // Ignore parity errors
    tty.c_oflag = 0;
    tty.c_lflag = 0;                               // Non-canonical mode

    tty.c_cc[VMIN] = 0;  // Read doesn't block
    tty.c_cc[VTIME] = 5; // 0.5 seconds read timeout

    if (tcsetattr(fd, TCSANOW, &tty) != 0) {
        perror("Error setting termios attributes");
        close(fd);
        return -1;
    }

    return fd;
}

// Function to read data from the serial port
int read_serial_data(int fd, unsigned char *buffer, int max_len) {
    ssize_t bytes_read = read(fd, buffer, max_len);
    if (bytes_read == -1) {
        perror("Error reading from serial port");
        return -1;
    }
    return (int)bytes_read;
}

// Function to process the received data
int process_data(const unsigned char *data, int len) {
    if (len != DATA_FRAME_SIZE) {
        fprintf(stderr, "Error: Invalid data frame size (%d bytes, expected %d)\n", len, DATA_FRAME_SIZE);
        return -1;
    }

    // Extract the sensor values from the data frame
    int sensor1_value = (data[0] << 8) | data[1];
    int sensor2_value = (data[2] << 8) | data[3];

    // Validate sensor values
    if (sensor1_value < 0 || sensor1_value > 1023) {
        fprintf(stderr, "Error: Invalid sensor 1 value: %d\n", sensor1_value);
        return -1;
    }
    if (sensor2_value < 0 || sensor2_value > 1023) {
        fprintf(stderr, "Error: Invalid sensor 2 value: %d\n", sensor2_value);
        return -1;
    }

    // Print the sensor values
    printf("Sensor 1: %d, Sensor 2: %d\n", sensor1_value, sensor2_value);

    return 0;
}

int main() {
    // Install signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    // Initialize the serial port
    serial_port_fd = init_serial_port(SERIAL_PORT, BAUD_RATE);
    if (serial_port_fd == -1) {
        fprintf(stderr, "Failed to initialize serial port. Exiting.\n");
        return 1;
    }
    printf("Serial port initialized successfully.\n");

    unsigned char buffer[DATA_FRAME_SIZE];
    int bytes_read;

    // Main loop to read and process data
    while (1) {
        // Read data from the serial port
        bytes_read = read_serial_data(serial_port_fd, buffer, DATA_FRAME_SIZE);
        if (bytes_read > 0) {
            // Process the received data
            if (process_data(buffer, bytes_read) != 0) {
                fprintf(stderr, "Error processing data.\n");
            }
        } else if (bytes_read < 0) {
            fprintf(stderr, "Error reading from serial port. Retrying.\n");
            // Attempt to re-initialize the serial port
            close(serial_port_fd);
            serial_port_fd = init_serial_port(SERIAL_PORT, BAUD_RATE);
            if (serial_port_fd == -1) {
                fprintf(stderr, "Failed to re-initialize serial port. Exiting.\n");
                break; // Exit the loop if re-initialization fails
            }
            printf("Serial port re-initialized successfully.\n");
        }

        // Small delay to avoid busy-waiting
        usleep(10000); // 10 milliseconds
    }

    // Close the serial port before exiting
    close(serial_port_fd);
    printf("Serial port closed.\n");

    return 0;
}

