#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define DHT22_GPIO 4
#define MAX_TIMINGS 85

volatile sig_atomic_t terminate = 0;

void signal_handler(int sig) {
    terminate = 1;
    printf("\nCaught signal %d, terminating gracefully...\n", sig);
}

int read_dht22(int gpio, float *temperature, float *humidity) {
    int data[5] = {0, 0, 0, 0, 0};
    int laststate = PI_HIGH;
    int j = 0;

    gpioSetMode(gpio, PI_OUTPUT);
    gpioWrite(gpio, PI_LOW);
    gpioDelay(18); //18ms
    gpioWrite(gpio, PI_HIGH);
    gpioDelay(40); //40us
    gpioSetMode(gpio, PI_INPUT);

    unsigned int timings[MAX_TIMINGS];
    int timing_index = 0;

    // Read data
    for (int i = 0; i < MAX_TIMINGS; i++) {
        int counter = 0;
        while (gpioRead(gpio) == laststate) {
            counter++;
            gpioDelay(1); //1us delay
            if (counter == 255) {
                fprintf(stderr, "Timeout waiting for state change\n");
                return -1;
            }
        }
        laststate = gpioRead(gpio);

        timings[timing_index++] = counter;

        if (timing_index >= MAX_TIMINGS) {
            fprintf(stderr, "Too many timings\n");
            return -1;
        }
    }

    // Decode data
    for (int i = 3; i < MAX_TIMINGS - 3; i += 2) {
        int index = (i - 3) / 16;
        int bit = (i - 3) % 16;
        data[index] <<= 1;
        if (timings[i] > timings[i + 1]) {
            data[index] |= 1;
        }
    }

    // Check checksum
    if (data[4] != ((data[0] + data[1] + data[2] + data[3]) & 0xFF)) {
        fprintf(stderr, "Checksum failure\n");
        return -1;
    }

    // Convert data to temperature and humidity
    *humidity = (float)data[0] * 256 + (float)data[1];
    *humidity /= 10;

    *temperature = (float)(data[2] & 0x7F) * 256 + (float)data[3];
    *temperature /= 10;
    if (data[2] & 0x80) {
        *temperature *= -1;
    }

    return 0;
}

int main() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    signal(SIGINT, signal_handler);

    float temperature, humidity;

    if (read_dht22(DHT22_GPIO, &temperature, &humidity) == 0) {
        printf("Temperature: %.1f °C, Humidity: %.1f %%\n", temperature, humidity);
    } else {
        fprintf(stderr, "Failed to read DHT22 data\n");
    }

    gpioTerminate();
    return 0;
}

#include <stdio.h>
