#include <string.h>

// Define GPIO pins
#define GPIO_17 17
#define GPIO_23 23
#define GPIO_24 24
#define GPIO_25 25

// Define the number of GPIO pins
#define NUM_GPIOS 4

// Define the GPIO pins array
const int gpio_pins[NUM_GPIOS] = {GPIO_17, GPIO_23, GPIO_24, GPIO_25};

// Global variable to store the GPIO chip
struct gpiod_chip *gpio_chip = NULL;

// Global variable to store the GPIO lines
struct gpiod_line *gpio_lines[NUM_GPIOS];

// Signal handler for Ctrl+C
void signal_handler(int sig) {
    printf("\nCaught signal %d, cleaning up...\n", sig);

    // Release GPIO lines
    for (int i = 0; i < NUM_GPIOS; i++) {
        if (gpio_lines[i] != NULL) {
            if (gpiod_line_release(gpio_lines[i]) < 0) {
                fprintf(stderr, "Error releasing GPIO %d: %s\n", gpio_pins[i], strerror(errno));
            }
        }
    }

    // Close GPIO chip
    if (gpio_chip != NULL) {
        if (gpiod_chip_close(gpio_chip) < 0) {
            fprintf(stderr, "Error closing GPIO chip: %s\n", strerror(errno));
        }
    }

    exit(0);
}

// Function to set the state of a GPIO pin
int set_gpio_state(struct gpiod_line *line, int state) {
    int ret = gpiod_line_set_value(line, state);
    if (ret < 0) {
        fprintf(stderr, "Error setting GPIO value: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

// Function to get the state of a GPIO pin
int get_gpio_state(struct gpiod_line *line) {
    int ret = gpiod_line_get_value(line);
    if (ret < 0) {
        fprintf(stderr, "Error getting GPIO value: %s\n", strerror(errno));
        return -1;
    }
    return ret;
}

int main() {
    // Install signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    // Open GPIO chip
    gpio_chip = gpiod_chip_open_by_name("gpiochip0");
    if (!gpio_chip) {
        fprintf(stderr, "Error opening GPIO chip: %s\n", strerror(errno));
        return 1;
    }

    // Get GPIO lines
    for (int i = 0; i < NUM_GPIOS; i++) {
        gpio_lines[i] = gpiod_chip_get_line(gpio_chip, gpio_pins[i]);
        if (!gpio_lines[i]) {
            fprintf(stderr, "Error getting GPIO %d: %s\n", gpio_pins[i], strerror(errno));
            // Release previously acquired lines
            for (int j = 0; j < i; j++) {
                gpiod_line_release(gpio_lines[j]);
            }
            gpiod_chip_close(gpio_chip);
            return 1;
        }

        // Request GPIO line for output
        if (gpiod_line_request_output(gpio_lines[i], "gpio_output", 0) < 0) {
            fprintf(stderr, "Error requesting GPIO %d for output: %s\n", gpio_pins[i], strerror(errno));
            // Release previously acquired lines
            for (int j = 0; j <= i; j++) {
                gpiod_line_release(gpio_lines[j]);
            }
            gpiod_chip_close(gpio_chip);
            return 1;
        }
    }

    // Main loop
    while (1) {
        // Set GPIO pins HIGH
        for (int i = 0; i < NUM_GPIOS; i++) {
            if (set_gpio_state(gpio_lines[i], 1) < 0) {
                // Handle error, but continue to the next pin
