    enum v4l2_buf_type type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    if (ioctl(fd, VIDIOC_STREAMON, &type) < 0) {
        perror("Error starting stream");
        close(fd);
        free(buffers);
        return 1;
    }

    // Capture a frame
    struct v4l2_buffer buf;
    memset(&buf, 0, sizeof(buf));
    buf.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    buf.memory = V4L2_MEMORY_MMAP;

    if (ioctl(fd, VIDIOC_DQBUF, &buf) < 0) {
        perror("Error dequeuing buffer");
        close(fd);
        free(buffers);
        return 1;
    }

    // Save the frame to a file
    fp = fopen(IMAGE_FILENAME, "wb");
    if (!fp) {
        perror("Error opening file for writing");
        close(fd);
        free(buffers);
        return 1;
    }

    fwrite(buffers[buf.index].start, buf.bytesused, 1, fp);
    fclose(fp);

    // Requeue the buffer
    if (ioctl(fd, VIDIOC_QBUF, &buf) < 0) {
        perror("Error requeuing buffer");
        close(fd);
        free(buffers);
        return 1;
    }

    // Stop streaming
    if (ioctl(fd, VIDIOC_STREAMOFF, &type) < 0) {
        perror("Error stopping stream");
        close(fd);
        free(buffers);
        return 1;
    }

    // Unmap the buffers
    for (i = 0; i < n_buffers; ++i) {
        if (munmap(buffers[i].start, buffers[i].length) < 0) {
            perror("Error unmapping buffer");
            close(fd);
            free(buffers);
            return 1;
        }
    }

    // Free the buffers
    free(buffers);

    // Close the device
    close(fd);

    printf("Image captured and saved to %s\n", IMAGE_FILENAME);

    return 0;
}

