#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <fcntl.h>
#include <unistd.h>
#include <sys/ioctl.h>
#include <sys/mman.h>
#include <linux/videodev2.h>
#include <signal.h>
#include <errno.h>
#include <time.h>

#define DEVICE_NAME "/dev/video0"
#define IMAGE_WIDTH 640
#define IMAGE_HEIGHT 480
#define IMAGE_FORMAT V4L2_PIX_FMT_YUYV
#define NUM_BUFFERS 4

// Structure to hold buffer information
typedef struct {
    void   *start;
    size_t  length;
} buffer;

static buffer *buffers = NULL;
static int fd = -1;
static int running = 1;

// Signal handler for Ctrl+C
void signal_handler(int sig) {
    running = 0;
    printf("\nCaught signal %d, exiting...\n", sig);
}

// Function to initialize the camera
int init_camera(const char *device_name) {
    fd = open(device_name, O_RDWR | O_NONBLOCK, 0);
    if (fd < 0) {
        perror("Error opening device");
        return -1;
    }

    struct v4l2_capability cap;
    if (ioctl(fd, VIDIOC_QUERYCAP, &cap) < 0) {
        perror("Error querying capabilities");
        close(fd);
        return -1;
    }

    if (!(cap.capabilities & V4L2_CAP_VIDEO_CAPTURE)) {
        fprintf(stderr, "%s is not a video capture device\n", device_name);
        close(fd);
        return -1;
    }

    if (!(cap.capabilities & V4L2_CAP_STREAMING)) {
        fprintf(stderr, "%s does not support streaming i/o\n", device_name);
        close(fd);
        return -1;
    }

    struct v4l2_format fmt;
    memset(&fmt, 0, sizeof(fmt));
    fmt.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    fmt.fmt.pix.width = IMAGE_WIDTH;
    fmt.fmt.pix.height = IMAGE_HEIGHT;
    fmt.fmt.pix.pixelformat = IMAGE_FORMAT;
    fmt.fmt.pix.field = V4L2_FIELD_INTERLACED;

    if (ioctl(fd, VIDIOC_S_FMT, &fmt) < 0) {
        perror("Error setting format");
        close(fd);
        return -1;
    }

    if (fmt.fmt.pix.width != IMAGE_WIDTH || fmt.fmt.pix.height != IMAGE_HEIGHT || fmt.fmt.pix.pixelformat != IMAGE_FORMAT) {
        fprintf(stderr, "Camera does not support requested format\n");
        close(fd);
        return -1;
    }

    struct v4l2_requestbuffers req;
    memset(&req, 0, sizeof(req));
    req.count = NUM_BUFFERS;
    req.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    req.memory = V4L2_MEMORY_MMAP;

    if (ioctl(fd, VIDIOC_REQBUFS, &req) < 0) {
        perror("Error requesting buffers");
        close(fd);
        return -1;
    }

    if (req.count < 2) {
        fprintf(stderr, "Insufficient buffer memory on %s\n", device_name);
        close(fd);
        return -1;
    }

    buffers = calloc(req.count, sizeof(*buffers));
    if (!buffers) {
        perror("Out of memory");
        close(fd);
        return -1;
    }

    for (int i = 0; i < req.count; ++i) {
        struct v4l2_buffer buf;
        memset(&buf, 0, sizeof(buf));
        buf.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
        buf.memory = V4L2_MEMORY_MMAP;
        buf.index = i;

        if (ioctl(fd, VIDIOC_QUERYBUF, &buf) < 0) {
            perror("Error querying buffer");
            close(fd);
            free(buffers);
            return -1;
        }

        buffers[i].length = buf.length;
        buffers[i].start = mmap(NULL, buf.length, PROT_READ | PROT_WRITE, MAP_SHARED, fd, buf.m.offset);

        if (buffers[i].start == MAP_FAILED) {
            perror("Error mapping buffer");
            close(fd);
            free(buffers);
            return -1;
        }
    }

    for (int i = 0; i < req.count; ++i) {
        struct v4l2_buffer buf;
        memset(&buf, 0, sizeof(buf));
        buf.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
        buf.memory = V4L2_MEMORY_MMAP;
        buf.index = i;

        if (ioctl(fd, VIDIOC_QBUF, &buf) < 0) {
            perror("Error queuing buffer");
            close(fd);
            free(buffers);
            return -1;
        }
    }

    enum v4l2_buf_type type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    if (ioctl(fd, VIDIOC_STREAMON, &type) < 0) {
        perror("Error starting stream");
        close(fd);
        free(buffers);
        return -1;
    }

    return 0;
}

// Function to capture an image
int capture_image(const char *filename) {
    struct v4l2_buffer buf;
    memset(&buf, 0, sizeof(buf));
    buf.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    buf.memory = V4L2_MEMORY_MMAP;

    if (ioctl(fd, VIDIOC_DQBUF, &buf) < 0) {
        perror("Error dequeuing buffer");
        return -1;
    }

    FILE *fp = fopen(filename, "wb");
    if (!fp) {
        perror("Error opening file for writing");
        if (ioctl(fd, VIDIOC_QBUF, &buf) < 0) {
            perror("Error re-queuing buffer");
        }
        return -1;
    }

    fwrite(buffers[buf.index].start, buf.bytesused, 1, fp);
    fclose(fp);

    if (ioctl(fd, VIDIOC_QBUF, &buf) < 0) {
        perror("Error re-queuing buffer");
        return -1;
    }

    return 0;
}

// Function to release resources
void release_resources() {
    if (fd != -1) {
        enum v4l2_buf_type type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
        ioctl(fd, VIDIOC_STREAMOFF, &type);

        for (int i = 0; i < NUM_BUFFERS; ++i) {
            if (buffers[i].start != MAP_FAILED) {
                munmap(buffers[i].start, buffers[i].length);
            }
        }
        free(buffers);
        close(fd);
    }
}

int main() {
    // Install signal handler
    signal(SIGINT, signal_handler);

    // Initialize camera
    if (init_camera(DEVICE_NAME) < 0) {
        fprintf(stderr, "Camera initialization failed. Exiting.\n");
        return 1;
    }

    printf("Camera initialized successfully. Capturing images every 0.1 seconds.\n");

    // Capture and save images
    while (running) {
        char filename[50];
        time_t rawtime;
        struct tm *timeinfo;

        time(&rawtime);
        timeinfo = localtime(&rawtime);

        strftime(filename, sizeof(filename), "image_%Y%m%d_%H%M%S.yuv", timeinfo);

        if (capture_image(filename) < 0) {
            fprintf(stderr, "Error capturing image. Continuing.\n");
        } else {
            printf("Image saved to %s\n", filename);
        }

        usleep(100000); // 0.1 seconds
    }

    // Release resources
    release_resources();

    printf("Resources released. Exiting.\n");
    return 0;
}

