#define PCF8574_RS 0x01
#define PCF8574_EN 0x04
#define PCF8574_D4 0x10
#define PCF8574_D5 0x20
#define PCF8574_D6 0x40
#define PCF8574_D7 0x80

// Global variable for the I2C file descriptor
int i2c_fd = -1;

// Signal handler for Ctrl+C
void signal_handler(int sig) {
    printf("\nCaught signal %d, cleaning up...\n", sig);
    if (i2c_fd != -1) {
        close(i2c_fd);
    }
    exit(0);
}

// Function to write a command to the PCF8574
int pcf8574_write_command(int fd, unsigned char command) {
    unsigned char data = 0x00; // Initialize data to 0

    // Set RS pin low for command
    data &= ~PCF8574_RS;

    // Set data pins
    if (command & 0x01) data |= PCF8574_D4;
    if (command & 0x02) data |= PCF8574_D5;
    if (command & 0x04) data |= PCF8574_D6;
    if (command & 0x08) data |= PCF8574_D7;

    // Write the data to the PCF8574
    if (write(fd, &data, 1) != 1) {
        perror("Error writing to I2C device");
        return -1;
    }

    // Enable the PCF8574
    data |= PCF8574_EN;
    if (write(fd, &data, 1) != 1) {
        perror("Error writing to I2C device");
        return -1;
    }
    usleep(1); // Short delay

    // Disable the PCF8574
    data &= ~PCF8574_EN;
    if (write(fd, &data, 1) != 1) {
        perror("Error writing to I2C device");
        return -1;
    }
    usleep(100); // Short delay

    return 0;
}

// Function to write data to the PCF8574
int pcf8574_write_data(int fd, unsigned char data) {
    unsigned char command = 0x00; // Initialize command to 0

    // Set RS pin high for data
    command |= PCF8574_RS;

    // Set data pins
    if (data & 0x01) command |= PCF8574_D4;
    if (data & 0x02) command |= PCF8574_D5;
    if (data & 0x04) command |= PCF8574_D6;
    if (data & 0x08) command |= PCF8574_D7;

    // Write the data to the PCF8574
    if (write(fd, &command, 1) != 1) {
        perror("Error writing to I2C device");
        return -1;
    }

    // Enable the PCF8574
    command |= PCF8574_EN;
    if (write(fd, &command, 1) != 1) {
        perror("Error writing to I2C device");
        return -1;
    }
    usleep(1); // Short delay

    // Disable the PCF8574
    command &= ~PCF8574_EN;
    if (write(fd, &command, 1) != 1) {
        perror("Error writing to I2C device");
        return -1;
    }
    usleep(100); // Short delay

    return 0;
}

// Function to initialize the PCF8574
int pcf8574_init(int fd) {
    // Initialize the PCF8574 (no specific initialization needed for this example)
    return 0;
}

// Function to display a string on the PCF8574
int pcf8574_display_string(int fd, const char *string) {
    int i;

    // Clear the display (optional)
    pcf8574_write_command(fd, 0x01); // Clear display command
    usleep(2000); // Wait for clear display to complete

    // Set cursor to beginning of first line
    pcf8574_write_command(fd, 0x80); // Set cursor to beginning of first line

    for (i = 0; string[i] != '\0'; i++) {
        pcf8574_write_data(fd, string[i]);
    }

    return 0;
}

int main() {
    // Register the signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    // Open the I2C bus
    i2c_fd = open(I2C_BUS, O_RDWR);
    if (i2c_fd < 0) {
        perror("Error opening I2C bus");
        return 1;
    }

    // Set the I2C slave address
    if (ioctl(i2c_fd, I2C_SLAVE, PCF8574_ADDR) < 0) {
        perror("Error setting I2C slave address");
        close(i2c_fd);
        return 1;
    }

    // Initialize the PCF8574
    if (pcf8574_init(i2c_fd) != 0) {
        fprintf(stderr, "Error initializing PCF8574\n");
        close(i2c_fd);
        return 1;
    }

    // Display a string on the PCF8574
    if (pcf8574_display_string(i2c_fd, "Hello, World!") != 0) {
        fprintf(stderr, "Error displaying string\n");
        close(i2c_fd);
        return 1;
    }

    // Wait for 5 seconds
    sleep(5);

    // Close the I2C bus
    close(i2c_fd);

    return 0;
}

