#define PWM_RANGE 1000

// Global variable to indicate program termination
volatile sig_atomic_t program_running = 1;

// Signal handler for Ctrl+C
void signal_handler(int signal) {
    program_running = 0;
    printf("\nCaught signal %d, exiting gracefully...\n", signal);
}

// Function to set the PWM duty cycle for a given GPIO pin
void set_pwm_duty_cycle(int gpio_pin, int duty_cycle) {
    gpioPWM(gpio_pin, duty_cycle);
}

// Function to report the PWM state for a given GPIO pin
void report_pwm_state(int gpio_pin, int duty_cycle) {
    printf("GPIO %d: Duty Cycle = %d\n", gpio_pin, duty_cycle);
}

int main() {
    // Initialize pigpio library
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO pins as outputs
    gpioSetMode(GPIO_18, PI_OUTPUT);
    gpioSetMode(GPIO_23, PI_OUTPUT);
    gpioSetMode(GPIO_24, PI_OUTPUT);

    // Set PWM frequency for all GPIO pins
    gpioSetPWMfrequency(GPIO_18, PWM_FREQUENCY);
    gpioSetPWMfrequency(GPIO_23, PWM_FREQUENCY);
    gpioSetPWMfrequency(GPIO_24, PWM_FREQUENCY);

    // Set PWM range for all GPIO pins
    gpioSetPWMrange(GPIO_18, PWM_RANGE);
    gpioSetPWMrange(GPIO_23, PWM_RANGE);
    gpioSetPWMrange(GPIO_24, PWM_RANGE);

    // Register signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    // Main loop
    while (program_running) {
        // Set PWM duty cycles for GPIO 18, 23, and 24
        set_pwm_duty_cycle(GPIO_18, 500);
        set_pwm_duty_cycle(GPIO_23, 750);
        set_pwm_duty_cycle(GPIO_24, 250);

        // Report PWM states
        report_pwm_state(GPIO_18, 500);
        report_pwm_state(GPIO_23, 750);
        report_pwm_state(GPIO_24, 250);

        // Wait for 0.1 seconds
        gpioDelay(100000); // 100000 microseconds = 0.1 seconds
    }

    // Stop PWM signals
    gpioPWM(GPIO_18, 0);
    gpioPWM(GPIO_23, 0);
    gpioPWM(GPIO_24, 0);

    // Terminate pigpio library
    gpioTerminate();

    return 0;
}

