        return -1;
    }

    if (gpiod_line_request_input(echo_line, "hc-sr04") < 0) {
        perror("Error requesting echo line as input");
        gpiod_chip_close(chip);
        gpiod_line_release(trigger_line);
        gpiod_line_release(echo_line);
        return -1;
    }

    return 0;
}

// Send a 10us trigger pulse
void trigger_pulse(void) {
    struct timespec start, end;
    clock_gettime(CLOCK_MONOTONIC, &start);

    if (gpiod_line_set_value(trigger_line, 1) < 0) {
        perror("Error setting trigger high");
        terminate = 1; // Set terminate flag to exit
        return;
    }

    usleep(10); // 10us

    if (gpiod_line_set_value(trigger_line, 0) < 0) {
        perror("Error setting trigger low");
        terminate = 1; // Set terminate flag to exit
        return;
    }

    clock_gettime(CLOCK_MONOTONIC, &end);
    long long elapsed_ns = (end.tv_sec - start.tv_sec) * 1000000000LL + (end.tv_nsec - start.tv_nsec);
    if (elapsed_ns > TIMEOUT_US * 1000) {
        fprintf(stderr, "Timeout waiting for trigger to settle.\n");
        terminate = 1; // Set terminate flag to exit
    }
}

// Measure the echo pulse width
long long get_pulse_width(void) {
    struct timespec start, end;
    long long pulse_width = 0;

    // Wait for echo to go high
    clock_gettime(CLOCK_MONOTONIC, &start);
    while (gpiod_line_get_value(echo_line) == 0) {
        clock_gettime(CLOCK_MONOTONIC, &end);
        pulse_width = (end.tv_sec - start.tv_sec) * 1000000000LL + (end.tv_nsec - start.tv_nsec);
        if (pulse_width > TIMEOUT_US * 1000) {
            fprintf(stderr, "Timeout waiting for echo high.\n");
            return -1; // Indicate timeout
        }
    }

    // Measure pulse width
    clock_gettime(CLOCK_MONOTONIC, &start);
    while (gpiod_line_get_value(echo_line) == 1) {
        clock_gettime(CLOCK_MONOTONIC, &end);
        pulse_width = (end.tv_sec - start.tv_sec) * 1000000000LL + (end.tv_nsec - start.tv_nsec);
        if (pulse_width > TIMEOUT_US * 1000) {
            fprintf(stderr, "Timeout waiting for echo low.\n");
            return -1; // Indicate timeout
        }
    }

    return pulse_width;
}

// Calculate distance in centimeters
double calculate_distance(long long pulse_width) {
    if (pulse_width < 0) {
        return -1.0; // Indicate error
    }
    return (double)pulse_width * SPEED_OF_SOUND / 2000000.0; // Divide by 2 for one-way distance
}

// Report distance to standard output
void report_distance(double distance) {
    if (distance < 0) {
        fprintf(stderr, "Error: Invalid distance reading.\n");
    } else {
        printf("Distance: %.2f cm\n", distance);
    }
}

// Cleanup GPIO resources
void cleanup_gpio(void) {
    if (trigger_line) {
        gpiod_line_release(trigger_line);
    }
    if (echo_line) {
        gpiod_line_release(echo_line);
    }
    if (chip) {
        gpiod_chip_close(chip);
    }
}

int main(void) {
    // Install signal handler
    signal(SIGINT, signal_handler);

    // Initialize GPIO
    if (init_gpio() < 0) {
        fprintf(stderr, "GPIO initialization failed. Exiting.\n");
        return 1;
    }

    // Main loop
    while (!terminate) {
        trigger_pulse();
        long long pulse_width = get_pulse_width();
        double distance = calculate_distance(pulse_width);
        report_distance(distance);
        usleep(500000); // 0.5 second delay
    }

    // Cleanup GPIO
    cleanup_gpio();

    return 0;
}

