#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <fcntl.h>
#include <unistd.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <signal.h>
#include <errno.h>
#include <string.h>

// MPU6050 I2C address
#define MPU6050_ADDR 0x68

// MPU6050 registers
#define PWR_MGMT_1   0x6B
#define ACCEL_XOUT_H 0x3B
#define ACCEL_YOUT_H 0x3D
#define ACCEL_ZOUT_H 0x3F

// Global variables
int i2c_fd;
volatile sig_atomic_t program_running = 1;

// Signal handler for Ctrl+C
void signal_handler(int sig) {
    program_running = 0;
    printf("\nExiting program...\n");
}

// Function to read a single byte from an I2C register
int read_i2c_reg(int fd, uint8_t reg) {
    if (write(fd, &reg, 1) != 1) {
        perror("Failed to write register address");
        return -1;
    }
    uint8_t value;
    if (read(fd, &value, 1) != 1) {
        perror("Failed to read register value");
        return -1;
    }
    return value;
}

// Function to write a single byte to an I2C register
int write_i2c_reg(int fd, uint8_t reg, uint8_t value) {
    uint8_t buf[2];
    buf[0] = reg;
    buf[1] = value;
    if (write(fd, buf, 2) != 2) {
        perror("Failed to write register value");
        return -1;
    }
    return 0;
}

// Function to read accelerometer data
int read_accelerometer_data(int fd, int16_t *x, int16_t *y, int16_t *z) {
    uint8_t buffer[6];
    uint8_t reg = ACCEL_XOUT_H;

    if (write(fd, &reg, 1) != 1) {
        perror("Failed to write register address");
        return -1;
    }

    if (read(fd, buffer, 6) != 6) {
        perror("Failed to read accelerometer data");
        return -1;
    }

    *x = (int16_t)((buffer[0] << 8) | buffer[1]);
    *y = (int16_t)((buffer[2] << 8) | buffer[3]);
    *z = (int16_t)((buffer[4] << 8) | buffer[5]);

    return 0;
}

int main() {
    // Register signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    // Open I2C device
    i2c_fd = open("/dev/i2c-1", O_RDWR);
    if (i2c_fd < 0) {
        perror("Failed to open I2C device");
        return 1;
    }

    // Specify slave address
    if (ioctl(i2c_fd, I2C_SLAVE, MPU6050_ADDR) < 0) {
        perror("Failed to acquire bus access and/or talk to slave");
        close(i2c_fd);
        return 1;
    }

    // Wake up the MPU6050
    if (write_i2c_reg(i2c_fd, PWR_MGMT_1, 0) < 0) {
        fprintf(stderr, "Failed to wake up MPU6050\n");
        close(i2c_fd);
        return 1;
    }

    printf("MPU6050 initialized. Reading accelerometer data...\n");

    // Main loop
    while (program_running) {
        int16_t x, y, z;

        if (read_accelerometer_data(i2c_fd, &x, &y, &z) == 0) {
            printf("X: %6d, Y: %6d, Z: %6d\n", x, y, z);
        } else {
            fprintf(stderr, "Failed to read accelerometer data. Retrying...\n");
        }

        usleep(100000); // 0.1 seconds
    }

    // Close I2C device
    close(i2c_fd);

    return 0;
}

#include <stdio.h>
#include <stdlib.h>
#include <gpiod.h>
#include <unistd.h>
#include <signal.h>
#include <time.h>

// Define GPIO pins
#define GPIO_2 2
#define GPIO_3 3
#define GPIO_17 17

// Define the number of cycles
#define NUM_CYCLES 3

// Define the delay between cycles (in seconds)
#define CYCLE_DELAY 5

// Define the valid reading range
#define MIN_READING 0
#define MAX_READING 1023

// Global variables for GPIO lines and chip
struct gpiod_line *gpio_line_2 = NULL;
struct gpiod_line *gpio_line_3 = NULL;
struct gpiod_line *gpio_line_17 = NULL;
struct gpiod_chip *gpio_chip = NULL;

// Function prototypes
int read_sensor(int gpio_pin);
int validate_reading(int reading);
int set_gpio_output(int gpio_pin, int value);
void report_state(int gpio_pin, int value);
void cleanup(int signum);

// Signal handler for Ctrl+C
void cleanup(int signum) {
    printf("\nCleaning up and exiting...\n");

    // Set GPIO lines to input (safe state)
    if (gpio_line_2) {
        gpiod_line_set_value(gpio_line_2, 0); // Set to 0 to avoid floating
        gpiod_line_release(gpio_line_2);
    }
    if (gpio_line_3) {
        gpiod_line_set_value(gpio_line_3, 0);
        gpiod_line_release(gpio_line_3);
    }
    if (gpio_line_17) {
        gpiod_line_set_value(gpio_line_17, 0);
        gpiod_line_release(gpio_line_17);
    }

    // Close the GPIO chip
    if (gpio_chip) {
        gpiod_chip_close(gpio_chip);
    }

    exit(0);
}

// Function to read the sensor value from a GPIO pin
int read_sensor(int gpio_pin) {
    int reading = rand() % 1024; // Simulate reading from the sensor
    return reading;
}

// Function to validate the sensor reading
int validate_reading(int reading) {
    if (reading >= MIN_READING && reading <= MAX_READING) {
        return 1; // Valid reading
    } else {
        return 0; // Invalid reading
    }
}

// Function to set the GPIO output value
int set_gpio_output(int gpio_pin, int value) {
    struct gpiod_line *gpio_line = NULL;

    if (gpio_pin == GPIO_2) {
        gpio_line = gpio_line_2;
    } else if (gpio_pin == GPIO_3) {
        gpio_line = gpio_line_3;
    } else if (gpio_pin == GPIO_17) {
        gpio_line = gpio_line_17;
    } else {
        fprintf(stderr, "Error: Invalid GPIO pin: %d\n", gpio_pin);
        return -1; // Indicate an error
    }

    if (gpiod_line_set_value(gpio_line, value) < 0) {
        perror("Error setting GPIO value");
        return -1; // Indicate an error
    }

    return 0; // Indicate success
}

// Function to report the state of the GPIO output
void report_state(int gpio_pin, int value) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[80];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    printf("[%s] GPIO %d: %d\n", timestamp, gpio_pin, value);
}

int main() {
    // Install signal handler for Ctrl+C
    signal(SIGINT, cleanup);

    // Open the GPIO chip
    gpio_chip = gpiod_chip_open_by_name("gpiochip0");
    if (!gpio_chip) {
        perror("Error opening GPIO chip");
        return 1;
    }

    // Get GPIO lines
    gpio_line_2 = gpiod_chip_get_line(gpio_chip, GPIO_2);
    gpio_line_3 = gpiod_chip_get_line(gpio_chip, GPIO_3);
    gpio_line_17 = gpiod_chip_get_line(gpio_chip, GPIO_17);

    if (!gpio_line_2 || !gpio_line_3 || !gpio_line_17) {
        perror("Error getting GPIO line");
        cleanup(0); // Call cleanup before exiting
        return 1;
    }

    // Request GPIO lines for output
    if (gpiod_line_request_output(gpio_line_2, "gpio_output", 0) < 0 ||
        gpiod_line_request_output(gpio_line_3, "gpio_output", 0) < 0 ||
        gpiod_line_request_output(gpio_line_17, "gpio_output", 0) < 0) {
        perror("Error requesting GPIO line for output");
        cleanup(0); // Call cleanup before exiting
        return 1;
    }

    // Main loop
    for (int i = 0; i < NUM_CYCLES; i++) {
        // Read sensor values
        int reading_2 = read_sensor(GPIO_2);
        int reading_3 = read_sensor(GPIO_3);
        int reading_17 = read_sensor(GPIO_17);

        // Validate sensor readings
        int valid_2 = validate_reading(reading_2);
        int valid_3 = validate_reading(reading_3);
        int valid_17 = validate_reading(reading_17);

        // Set GPIO outputs based on sensor readings
        if (valid_2) {
            if (set_gpio_output(GPIO_2, (reading_2 > 512) ? 1 : 0) == 0) {
                report_state(GPIO_2, (reading_2 > 512) ? 1 : 0);
            }
        } else {
            fprintf(stderr, "Invalid reading from GPIO %d\n", GPIO_2);
        }

        if (valid_3) {
            if (set_gpio_output(GPIO_3, (reading_3 > 512) ? 1 : 0) == 0) {
                report_state(GPIO_3, (reading_3 > 512) ? 1 : 0);
            }
        } else {
            fprintf(stderr, "Invalid reading from GPIO %d\n", GPIO_3);
        }

        if (valid_17) {
            if (set_gpio_output(GPIO_17, (reading_17 > 512) ? 1 : 0) == 0) {
                report_state(GPIO_17, (reading_17 > 512) ? 1 : 0);
            }
        } else {
            fprintf(stderr, "Invalid reading from GPIO %d\n", GPIO_17);
        }

        // Wait for the specified delay
        sleep(CYCLE_DELAY);
    }

    // Cleanup and exit
    cleanup(0);

    return 0;
}

