#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <fcntl.h>
#include <unistd.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <signal.h>
#include <time.h>
#include <errno.h>
#include <string.h>

// SHT31 I2C address
#define SHT31_ADDR 0x44

// I2C bus
#define I2C_BUS "/dev/i2c-1"

// Measurement command (High Repeatability, Clock Stretching disabled)
#define MEASURE_CMD 0x2C06

// Global variable for I2C file descriptor
int i2c_fd = -1;

// Signal handler for Ctrl+C
void signal_handler(int sig) {
    printf("\nExiting program...\n");
    if (i2c_fd != -1) {
        close(i2c_fd);
    }
    exit(0);
}

// Function to read data from SHT31
int read_sht31(int fd, float *temperature, float *humidity) {
    uint8_t cmd[2] = {(MEASURE_CMD >> 8) & 0xFF, MEASURE_CMD & 0xFF};
    uint8_t data[6];
    int retries = 3;

    // Send measurement command
    while (retries > 0) {
        if (write(fd, cmd, 2) == 2) {
            break;
        } else {
            perror("Error writing to I2C device");
            retries--;
            usleep(10000); // Wait 10ms before retrying
        }
    }
    if (retries == 0) {
        fprintf(stderr, "Failed to send measurement command after multiple retries.\n");
        return -1;
    }

    // Wait for measurement (typical 10ms, max 15ms)
    usleep(20000);

    // Read 6 bytes of data
    retries = 3;
    while (retries > 0) {
        if (read(fd, data, 6) == 6) {
            break;
        } else {
            perror("Error reading from I2C device");
            retries--;
            usleep(10000); // Wait 10ms before retrying
        }
    }
    if (retries == 0) {
        fprintf(stderr, "Failed to read data after multiple retries.\n");
        return -1;
    }

    // Convert data to temperature and humidity
    int temp_raw = (data[0] << 8) | data[1];
    int hum_raw = (data[3] << 8) | data[4];

    *temperature = -45.0 + (175.0 * (float)temp_raw / 65535.0);
    *humidity = 100.0 * (float)hum_raw / 65535.0;

    // Validate data
    if (*temperature < -40.0 || *temperature > 125.0 || *humidity < 0.0 || *humidity > 100.0) {
        fprintf(stderr, "Invalid sensor reading: Temperature=%.2f, Humidity=%.2f\n", *temperature, *humidity);
        return -1;
    }

    return 0;
}

int main() {
    // Register signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    // Open I2C bus
    i2c_fd = open(I2C_BUS, O_RDWR);
    if (i2c_fd < 0) {
        perror("Error opening I2C bus");
        return 1;
    }

    // Set I2C slave address
    if (ioctl(i2c_fd, I2C_SLAVE, SHT31_ADDR) < 0) {
        perror("Error setting I2C slave address");
        close(i2c_fd);
        return 1;
    }

    float temperature, humidity;

    // Main loop
    while (1) {
        // Read temperature and humidity
        if (read_sht31(i2c_fd, &temperature, &humidity) == 0) {
            // Print temperature and humidity
            printf("Temperature: %.2f °C, Humidity: %.2f %%\n", temperature, humidity);
        } else {
            fprintf(stderr, "Failed to read sensor data.\n");
        }

