        // Clock the data pin high
        gpioWrite(gpio_clock, 1);

        // Clock the data pin low
        gpioWrite(gpio_clock, 0);
    }
}

// Function to set the color of all LEDs in the strip
void set_strip_color(int gpio_data, int gpio_clock, unsigned int color)
{
    for (int i = 0; i < NUM_LEDS; i++)
    {
        set_led_color(gpio_data, gpio_clock, i, color);
    }
}

int main()
{
    // Initialize the pigpio library
    if (gpioInitialise() < 0)
    {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO 18 as an output
    gpioSetMode(DATA_PIN, PI_OUTPUT);

    // Set GPIO 23 as an output
    gpioSetMode(CLOCK_PIN, PI_OUTPUT);

    // Register the signal handler for SIGINT
    signal(SIGINT, sigint_handler);

    // Define the rainbow cycle colors
    unsigned int rainbow_colors[] = {RED, ORANGE, YELLOW, GREEN, BLUE, INDIGO, VIOLET};
    int num_colors = sizeof(rainbow_colors) / sizeof(rainbow_colors[0]);

    // Main loop to perform the rainbow cycle
    while (!terminate)
    {
        for (int cycle = 0; cycle < 3; cycle++)
        {
            for (int color_index = 0; color_index < num_colors; color_index++)
            {
                // Set the color of the LED strip
                set_strip_color(DATA_PIN, CLOCK_PIN, rainbow_colors[color_index]);

                // Wait for 0.005 seconds
                gpioDelay(5000); // Delay in microseconds
            }
        }
    }

    // Reset all LEDs to off before exiting
    set_strip_color(DATA_PIN, CLOCK_PIN, 0x000000);

    // Terminate the pigpio library
    gpioTerminate();

    return 0;
}

