    signal(SIGINT, signal_handler);

    // Open GPIO chip
    gpio_chip = gpiod_chip_open_by_name("gpiochip0");
    if (!gpio_chip) {
        perror("Error opening GPIO chip");
        return 1;
    }

    // Get GPIO lines for GPIO 8 and GPIO 17
    gpio_line_8 = gpiod_chip_get_line(gpio_chip, GPIO_8);
    gpio_line_17 = gpiod_chip_get_line(gpio_chip, GPIO_17);

    if (!gpio_line_8 || !gpio_line_17) {
        perror("Error getting GPIO line");
        gpiod_chip_close(gpio_chip);
        return 1;
    }

    // Request GPIO lines for output
    if (gpiod_line_request_output(gpio_line_8, "gpio_output", 0) < 0) {
        perror("Error requesting GPIO 8 for output");
        gpiod_line_release(gpio_line_8);
        gpiod_line_release(gpio_line_17);
        gpiod_chip_close(gpio_chip);
        return 1;
    }

    if (gpiod_line_request_output(gpio_line_17, "gpio_output", 1) < 0) {
        perror("Error requesting GPIO 17 for output");
        gpiod_line_release(gpio_line_8);
        gpiod_line_release(gpio_line_17);
        gpiod_chip_close(gpio_chip);
        return 1;
    }

    // Set GPIO 8 to HIGH and GPIO 17 to LOW
    if (gpiod_line_set_value(gpio_line_8, 1) < 0) {
