}

int read_sensor() {
    // Simulate reading a sensor value (0 or 1)
    return rand() % 2;
}

int validate_reading(int reading) {
    // Validate the sensor reading
    return (reading == 0 || reading == 1) ? 1 : 0;
}

int main() {
    int i, readings[VALID_READINGS], valid_count = 0;
    int gpio_status;

    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
