#include <errno.h>
#include <time.h>

#define W1_DEVICES_DIR "/sys/bus/w1/devices/"
#define W1_SLAVE_FILE "w1_slave"
#define GPIO_PIN 4
#define NUM_READINGS 3
#define READ_INTERVAL 5 // seconds

static volatile int keep_running = 1;
static char w1_device_id[20] = {0};

// Signal handler for graceful shutdown
void signal_handler(int sig) {
    fprintf(stderr, "\nCaught signal %d, exiting gracefully.\n", sig);
    keep_running = 0;
}

// Function to discover the DS18B20 device ID
int discover_ds18b20_id(char *device_id, size_t device_id_size) {
    DIR *d;
    struct dirent *dir;
    d = opendir(W1_DEVICES_DIR);
    if (d) {
        while ((dir = readdir(d)) != NULL) {
            if (strncmp(dir->d_name, "28-", 3) == 0) {
                strncpy(device_id, dir->d_name, device_id_size - 1);
                device_id[device_id_size - 1] = '\0'; // Ensure null termination
                closedir(d);
                return 0; // Success
            }
        }
        closedir(d);
    }
    fprintf(stderr, "Error: DS18B20 device not found in %s\n", W1_DEVICES_DIR);
    return -1; // Failure
}

// Function to read the temperature from the DS18B20 sensor
float read_temperature(const char *device_id) {
    char filepath[100];
    snprintf(filepath, sizeof(filepath), "%s%s/%s", W1_DEVICES_DIR, device_id, W1_SLAVE_FILE);

    int fd = open(filepath, O_RDONLY);
    if (fd < 0) {
        fprintf(stderr, "Error opening %s: %s\n", filepath, strerror(errno));
        return -1000.0; // Indicate error
    }

    char buffer[256];
    ssize_t bytes_read = read(fd, buffer, sizeof(buffer) - 1);
    close(fd);

    if (bytes_read < 0) {
        fprintf(stderr, "Error reading from %s: %s\n", filepath, strerror(errno));
        return -1000.0; // Indicate error
    }
    buffer[bytes_read] = '\0';

    // Check for CRC error
    if (strstr(buffer, "YES") == NULL) {
        fprintf(stderr, "CRC check failed for device %s\n", device_id);
        return -1000.0; // Indicate error
    }

    // Extract temperature from the string
    char *temp_str = strstr(buffer, "t=");
    if (temp_str == NULL) {
        fprintf(stderr, "Temperature data not found in %s\n", filepath);
        return -1000.0; // Indicate error
    }

    long temperature_raw = strtol(temp_str + 2, NULL, 10);
    float temperature_celsius = (float)temperature_raw / 1000.0;

    return temperature_celsius;
}

int main() {
    // Install signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Discover the DS18B20 device ID
    if (discover_ds18b20_id(w1_device_id, sizeof(w1_device_id)) != 0) {
        return 1;
    }

    printf("DS18B20 device ID: %s\n", w1_device_id);

    // Main loop
    for (int i = 0; i < NUM_READINGS && keep_running; ++i) {
        float temperature = read_temperature(w1_device_id);

        if (temperature > -999.0) {
            printf("Temperature: %.2f °C\n", temperature);
        } else {
            fprintf(stderr, "Failed to read temperature.\n");
        }

        sleep(READ_INTERVAL);
    }

    printf("Exiting.\n");
    return 0;
}

