#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

// Define GPIO pins
#define TRIGGER_PIN 18
#define ECHO_PIN 23
#define LED_PIN 24

// Define constants
#define SPEED_OF_SOUND 34300.0 // Speed of sound in cm/s
#define TIMEOUT_US 50000       // Timeout for echo pulse in microseconds

// Global variables
volatile sig_atomic_t program_running = 1;

// Function prototypes
void signal_handler(int signal);
int initialize_gpio();
void trigger_pulse();
long get_pulse_width();
float calculate_distance(long pulse_width);
void set_led_state(int state);
void cleanup_gpio();

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    program_running = 0;
    printf("\nCaught signal %d, exiting gracefully...\n", signal);
}

// Initialize GPIO pins
int initialize_gpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    gpioSetMode(TRIGGER_PIN, PI_OUTPUT);
    gpioSetMode(ECHO_PIN, PI_INPUT);
    gpioSetMode(LED_PIN, PI_OUTPUT);

    gpioWrite(TRIGGER_PIN, 0); // Ensure trigger is low initially
    gpioWrite(LED_PIN, 0);    // Ensure LED is off initially

    return 0;
}

// Trigger the ultrasonic pulse
void trigger_pulse() {
    gpioWrite(TRIGGER_PIN, 1);
    gpioDelay(10); // 10 us trigger pulse
    gpioWrite(TRIGGER_PIN, 0);
}

// Measure the echo pulse width
long get_pulse_width() {
    long start_tick, end_tick, pulse_width;

    // Wait for echo to go high (with timeout)
    int count = 0;
    while (gpioRead(ECHO_PIN) == 0 && count < TIMEOUT_US) {
        count++;
        gpioDelay(1); // Check every microsecond
    }
    if (count >= TIMEOUT_US) {
        fprintf(stderr, "Timeout waiting for echo high\n");
        return -1; // Timeout
    }
    start_tick = gpioTick();

    // Wait for echo to go low (with timeout)
    count = 0;
    while (gpioRead(ECHO_PIN) == 1 && count < TIMEOUT_US) {
        count++;
        gpioDelay(1);
    }
    if (count >= TIMEOUT_US) {
        fprintf(stderr, "Timeout waiting for echo low\n");
        return -1; // Timeout
    }
    end_tick = gpioTick();

    pulse_width = end_tick - start_tick;
    return pulse_width;
}

// Calculate the distance in centimeters
float calculate_distance(long pulse_width) {
    if (pulse_width < 0) {
        return -1.0; // Indicate error
    }
    return (float)pulse_width * SPEED_OF_SOUND / 2000000.0; // Divide by 2 for one-way distance
}

// Set the LED state
void set_led_state(int state) {
    gpioWrite(LED_PIN, state);
}

// Cleanup GPIO resources
void cleanup_gpio() {
    gpioWrite(LED_PIN, 0); // Turn off LED
    gpioTerminate();
}

int main() {
    // Register signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    // Initialize GPIO
    if (initialize_gpio() != 0) {
        return 1;
    }

    printf("HC-SR04 sensor program started. Press Ctrl+C to exit.\n");

    // Main loop
    while (program_running) {
        trigger_pulse();
        long pulse_width = get_pulse_width();
        float distance = calculate_distance(pulse_width);

        if (distance > 0) {
            printf("Distance: %.2f cm\n", distance);
            set_led_state(1); // Turn on LED
        } else {
            fprintf(stderr, "Error: Invalid distance reading\n");
            set_led_state(0); // Turn off LED
        }

        gpioDelay(100); // Wait 0.1 seconds
        set_led_state(0); // Turn off LED after delay
    }

    // Cleanup GPIO resources before exiting
    cleanup_gpio();

    return 0;
}

