#include <pigpio.h>

#define GPIO_PIN 2
#define VALID_READINGS 3
#define READING_DELAY_MS 100

volatile sig_atomic_t program_running = 1;

void signal_handler(int signal) {
    program_running = 0;
    printf("\nCaught signal %d, exiting gracefully...\n", signal);
}

int read_sensor() {
    int reading = gpioRead(GPIO_PIN);
    if (reading >= 0) {
        return reading;
    } else {
        fprintf(stderr, "Error reading sensor: %d\n", reading);
        return -1; // Indicate an error
    }
}

int validate_reading(int reading) {
    return (reading == 0 || reading == 1) ? 1 : 0;
}

int main() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    gpioSetMode(GPIO_PIN, PI_INPUT);

    signal(SIGINT, signal_handler);

    int valid_read_count = 0;
    int current_state = -1; // Initialize to an invalid state

    while (program_running) {
        int reading = read_sensor();

        if (reading >= 0) {
            if (validate_reading(reading)) {
                valid_read_count++;
                if (valid_read_count >= VALID_READINGS) {
                    if (reading != current_state) {
                        gpioWrite(GPIO_PIN, reading);
                        current_state = reading;
                        printf("GPIO %d set to %d\n", GPIO_PIN, current_state);
                    }
                    valid_read_count = VALID_READINGS; // Keep it at max if valid
                }
            } else {
                valid_read_count = 0; // Reset if invalid
            }
        } else {
            valid_read_count = 0; // Reset on error
        }

        gpioDelay(READING_DELAY_MS * 1000); // Delay in microseconds
    }

    gpioWrite(GPIO_PIN, 0); // Set GPIO to LOW on exit
    gpioTerminate();

    return 0;
}

