// Define valid PWM duty cycle range
#define MIN_DUTY_CYCLE 0
#define MAX_DUTY_CYCLE 1000

// Global variable to indicate program termination
volatile sig_atomic_t program_running = 1;

// Signal handler for Ctrl+C
void signal_handler(int signal) {
    program_running = 0;
    printf("\nCaught signal %d, exiting gracefully...\n", signal);
}

// Function to read PWM duty cycle from a file
int read_pwm_duty_cycle(const char *filename) {
    FILE *fp;
    int duty_cycle;

    fp = fopen(filename, "r");
    if (fp == NULL) {
        fprintf(stderr, "Error: Could not open file %s for reading.\n", filename);
        return -1; // Indicate error
    }

    if (fscanf(fp, "%d", &duty_cycle) != 1) {
        fprintf(stderr, "Error: Could not read duty cycle from file %s.\n", filename);
        fclose(fp);
        return -1; // Indicate error
    }

    fclose(fp);

    return duty_cycle;
}

// Function to set PWM duty cycle for a given GPIO pin
int set_pwm_duty_cycle(int gpio_pin, int duty_cycle) {
    if (duty_cycle < MIN_DUTY_CYCLE || duty_cycle > MAX_DUTY_CYCLE) {
        fprintf(stderr, "Error: Invalid duty cycle value: %d. Duty cycle must be between %d and %d.\n", duty_cycle, MIN_DUTY_CYCLE, MAX_DUTY_CYCLE);
        return -1; // Indicate error
    }

    gpioPWM(gpio_pin, duty_cycle);
    return 0; // Indicate success
}

// Function to report PWM state
void report_pwm_state(int gpio_pin, int duty_cycle) {
    printf("GPIO %d: Duty Cycle = %d\n", gpio_pin, duty_cycle);
}

