    gpioSetMode(PWM_PIN_1, PI_OUTPUT);
    gpioSetMode(PWM_PIN_2, PI_OUTPUT);
    gpioSetMode(PWM_PIN_3, PI_OUTPUT);

    // Set PWM frequency
    gpioSetPWMfrequency(PWM_PIN_1, PWM_FREQUENCY);
    gpioSetPWMfrequency(PWM_PIN_2, PWM_FREQUENCY);
    gpioSetPWMfrequency(PWM_PIN_3, PWM_FREQUENCY);

    // Set PWM range
    gpioSetPWMrange(PWM_PIN_1, PWM_RANGE);
    gpioSetPWMrange(PWM_PIN_2, PWM_RANGE);
    gpioSetPWMrange(PWM_PIN_3, PWM_RANGE);

    // Register signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    // Main loop
    while (program_running) {
        // Read PWM duty cycles from files
        duty_cycle_1 = read_pwm_duty_cycle("pwm1.txt");
        duty_cycle_2 = read_pwm_duty_cycle("pwm2.txt");
        duty_cycle_3 = read_pwm_duty_cycle("pwm3.txt");

        // Set PWM duty cycles if read was successful
        if (duty_cycle_1 != -1) {
            if (set_pwm_duty_cycle(PWM_PIN_1, duty_cycle_1) == 0) {
                report_pwm_state(PWM_PIN_1, duty_cycle_1);
            }
        }

        if (duty_cycle_2 != -1) {
            if (set_pwm_duty_cycle(PWM_PIN_2, duty_cycle_2) == 0) {
