    for (i = 0; i < 85; i++) {
        clock_gettime(CLOCK_MONOTONIC, &start);
        while (gpiod_line_get_value(line) == (i % 2 == 0 ? 0 : 1)) {
            clock_gettime(CLOCK_MONOTONIC, &end);
            elapsed_time = (end.tv_sec - start.tv_sec) * 1000000LL + (end.tv_nsec - start.tv_nsec) / 1000LL;
            if (elapsed_time > MAX_RESPONSE_TIME) {
                fprintf(stderr, "Error: Timeout waiting for response on pin %d\n", pin);
                gpiod_line_release(line);
                return -1;
            }
        }
