    for (i = 0; i < 40; i++) {
        data_bits[i] = 0;
        for (j = 0; j < 2; j++) {
            if (pulse_lengths[2 * i + 2 + j] > 40) {
                data_bits[i] = 1;
                break;
            }
        }
    }

    // Validate checksum
    unsigned int checksum = 0;
    for (i = 0; i < 32; i++) {
        checksum += data_bits[i];
    }
    checksum &= 0xFF;

    if (checksum != data_bits[32]) {
        fprintf(stderr, "Error: Checksum mismatch on pin %d\n", pin);
        gpiod_line_release(line);
        return -1;
    }

    // Extract humidity and temperature
    data->humidity = (data_bits[0] << 8) | data_bits[1];
    data->temperature = (data_bits[2] << 8) | data_bits[3];
    data->valid = 1;

    gpiod_line_release(line);
    return 0;
