#define GPIO_23 23

// Global variables for GPIO lines and chip
struct gpiod_line *gpio_line_17 = NULL;
struct gpiod_line *gpio_line_18 = NULL;
struct gpiod_line *gpio_line_23 = NULL;
struct gpiod_chip *gpio_chip = NULL;

// Signal handler for Ctrl+C
void signal_handler(int sig) {
    printf("\nCaught signal %d, cleaning up...\n", sig);

    // Set GPIO lines to input (safe state)
    if (gpio_line_17) {
        if (gpiod_line_set_value(gpio_line_17, 0) < 0) {
            perror("Error setting GPIO 17 to input");
        }
    }
    if (gpio_line_18) {
        if (gpiod_line_set_value(gpio_line_18, 0) < 0) {
            perror("Error setting GPIO 18 to input");
        }
    }
    if (gpio_line_23) {
        if (gpiod_line_set_value(gpio_line_23, 0) < 0) {
            perror("Error setting GPIO 23 to input");
        }
    }

    // Release GPIO lines
    if (gpio_line_17) {
        gpiod_line_release(gpio_line_17);
    }
    if (gpio_line_18) {
        gpiod_line_release(gpio_line_18);
    }
    if (gpio_line_23) {
        gpiod_line_release(gpio_line_23);
    }

    // Close GPIO chip
    if (gpio_chip) {
        gpiod_chip_close(gpio_chip);
    }

    exit(0);
}

int main() {
    // Register signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    // Open GPIO chip
    gpio_chip = gpiod_chip_open_by_name("gpiochip0");
    if (!gpio_chip) {
        perror("Error opening GPIO chip");
        return 1;
    }

    // Get GPIO lines
    gpio_line_17 = gpiod_chip_get_line(gpio_chip, GPIO_17);
    gpio_line_18 = gpiod_chip_get_line(gpio_chip, GPIO_18);
    gpio_line_23 = gpiod_chip_get_line(gpio_chip, GPIO_23);

    if (!gpio_line_17 || !gpio_line_18 || !gpio_line_23) {
        perror("Error getting GPIO line");
        gpiod_chip_close(gpio_chip);
        return 1;
    }

    // Request GPIO lines for output
    if (gpiod_line_request_output(gpio_line_17, "gpio_output", 1) < 0) {
        perror("Error requesting GPIO 17 for output");
        gpiod_line_release(gpio_line_17);
        gpiod_line_release(gpio_line_18);
        gpiod_line_release(gpio_line_23);
        gpiod_chip_close(gpio_chip);
        return 1;
    }
    if (gpiod_line_request_output(gpio_line_18, "gpio_output", 0) < 0) {
        perror("Error requesting GPIO 18 for output");
        gpiod_line_release(gpio_line_17);
        gpiod_line_release(gpio_line_18);
        gpiod_line_release(gpio_line_23);
        gpiod_chip_close(gpio_chip);
        return 1;
    }
    if (gpiod_line_request_output(gpio_line_23, "gpio_output", 1) < 0) {
        perror("Error requesting GPIO 23 for output");
        gpiod_line_release(gpio_line_17);
        gpiod_line_release(gpio_line_18);
        gpiod_line_release(gpio_line_23);
        gpiod_chip_close(gpio_chip);
        return 1;
    }

    // Set GPIO line values and print to stdout
    if (gpiod_line_set_value(gpio_line_17, 1) < 0) {
        perror("Error setting GPIO 17 value");
    } else {
        printf("GPIO 17 set to HIGH\n");
    }
    if (gpiod_line_set_value(gpio_line_18, 0) < 0) {
        perror("Error setting GPIO 18 value");
    } else {
        printf("GPIO 18 set to LOW\n");
    }
    if (gpiod_line_set_value(gpio_line_23, 1) < 0) {
        perror("Error setting GPIO 23 value");
    } else {
        printf("GPIO 23 set to HIGH\n");
    }

    // Wait for 5 seconds
    sleep(5);

    // Release GPIO lines
    gpiod_line_release(gpio_line_17);
    gpiod_line_release(gpio_line_18);
    gpiod_line_release(gpio_line_23);

    // Close GPIO chip
    gpiod_chip_close(gpio_chip);

    return 0;
}

