#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

// Define GPIO pins
#define GPIO_4 4
#define GPIO_17 17
#define GPIO_18 18
#define GPIO_27 27

// Define PWM frequency
#define PWM_FREQUENCY 1000

// Define PWM range
#define PWM_RANGE 1000

// Define duty cycle increments
#define DUTY_CYCLE_INCREMENT 10

// Define number of cycles
#define NUM_CYCLES 5

// Global variable to track program termination
volatile sig_atomic_t program_running = 1;

// Signal handler for Ctrl+C
void signal_handler(int signal) {
    program_running = 0;
    printf("\nCaught signal %d, exiting gracefully...\n", signal);
}

// Function to set PWM duty cycle for a given GPIO pin
void set_pwm_duty_cycle(int gpio, int duty_cycle) {
    gpioPWM(gpio, duty_cycle);
}

// Function to report the state of a GPIO pin
void report_gpio_state(int gpio, int duty_cycle) {
    printf("GPIO %d: Duty Cycle = %d\n", gpio, duty_cycle);
}

int main() {
    // Initialize pigpio library
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO pins as outputs
    gpioSetMode(GPIO_4, PI_OUTPUT);
    gpioSetMode(GPIO_17, PI_OUTPUT);
    gpioSetMode(GPIO_18, PI_OUTPUT);
    gpioSetMode(GPIO_27, PI_OUTPUT);

    // Set PWM frequency for all GPIO pins
    gpioSetPWMfrequency(GPIO_4, PWM_FREQUENCY);
    gpioSetPWMfrequency(GPIO_17, PWM_FREQUENCY);
    gpioSetPWMfrequency(GPIO_18, PWM_FREQUENCY);
    gpioSetPWMfrequency(GPIO_27, PWM_FREQUENCY);

    // Set PWM range for all GPIO pins
    gpioSetPWMrange(GPIO_4, PWM_RANGE);
    gpioSetPWMrange(GPIO_17, PWM_RANGE);
    gpioSetPWMrange(GPIO_18, PWM_RANGE);
    gpioSetPWMrange(GPIO_27, PWM_RANGE);

    // Register signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    // Main loop
    for (int cycle = 0; cycle < NUM_CYCLES && program_running; cycle++) {
        printf("Cycle %d\n", cycle + 1);

        // Increment duty cycle for each GPIO pin
        for (int duty_cycle = 0; duty_cycle <= PWM_RANGE && program_running; duty_cycle += DUTY_CYCLE_INCREMENT) {
            set_pwm_duty_cycle(GPIO_4, duty_cycle);
            set_pwm_duty_cycle(GPIO_17, duty_cycle);
            set_pwm_duty_cycle(GPIO_18, duty_cycle);
            set_pwm_duty_cycle(GPIO_27, duty_cycle);

            report_gpio_state(GPIO_4, duty_cycle);
            report_gpio_state(GPIO_17, duty_cycle);
            report_gpio_state(GPIO_18, duty_cycle);
            report_gpio_state(GPIO_27, duty_cycle);

            gpioDelay(100000); // Delay for 100ms
        }

        // Decrement duty cycle for each GPIO pin
        for (int duty_cycle = PWM_RANGE; duty_cycle >= 0 && program_running; duty_cycle -= DUTY_CYCLE_INCREMENT) {
            set_pwm_duty_cycle(GPIO_4, duty_cycle);
            set_pwm_duty_cycle(GPIO_17, duty_cycle);
            set_pwm_duty_cycle(GPIO_18, duty_cycle);
            set_pwm_duty_cycle(GPIO_27, duty_cycle);

            report_gpio_state(GPIO_4, duty_cycle);
            report_gpio_state(GPIO_17, duty_cycle);
            report_gpio_state(GPIO_18, duty_cycle);
            report_gpio_state(GPIO_27, duty_cycle);

            gpioDelay(100000); // Delay for 100ms
        }
    }

    // Stop PWM output
    set_pwm_duty_cycle(GPIO_4, 0);
    set_pwm_duty_cycle(GPIO_17, 0);
    set_pwm_duty_cycle(GPIO_18, 0);
    set_pwm_duty_cycle(GPIO_27, 0);

    // Release GPIO pins
    gpioSetMode(GPIO_4, PI_INPUT);
    gpioSetMode(GPIO_17, PI_INPUT);
    gpioSetMode(GPIO_18, PI_INPUT);
    gpioSetMode(GPIO_27, PI_INPUT);

    // Terminate pigpio library
    gpioTerminate();

    printf("Program terminated.\n");
    return 0;
}

