#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

// Define GPIO pins for DHT22 sensors
#define DHT22_PIN_1 4
#define DHT22_PIN_2 17

// Define the number of cycles to run
#define NUM_CYCLES 3

// Define the delay between cycles (seconds)
#define CYCLE_DELAY 60

// Structure to hold DHT22 data
typedef struct {
    float temperature;
    float humidity;
    int valid;
} DHT22Data;

// Global variable to indicate program termination
volatile sig_atomic_t program_running = 1;

// Signal handler for Ctrl+C
void signal_handler(int signal) {
    program_running = 0;
    printf("\nCaught signal %d, exiting gracefully...\n", signal);
}

// Function to read data from a DHT22 sensor
DHT22Data read_dht22(int gpio_pin) {
    DHT22Data data = {0.0, 0.0, 0};
    int result;
    int i;
    int data_bits[40] = {0};
    int bit_count = 0;
    int pulse_lengths[85]; // Increased size to accommodate longer pulses

    // Set GPIO pin as output
    gpioSetMode(gpio_pin, PI_OUTPUT);
    gpioWrite(gpio_pin, 0);
    gpioDelay(1); // > 1ms
    gpioWrite(gpio_pin, 1);
    gpioDelay(30); // 20-40us

    // Set GPIO pin as input
    gpioSetMode(gpio_pin, PI_INPUT);

    // Measure pulse lengths
    for (i = 0; i < 85; i++) {
        int count = 0;
        while (gpioRead(gpio_pin) == (i % 2 == 0 ? 0 : 1)) {
            count++;
            gpioDelay(1); // Delay 1us
            if (count > 200) { // Timeout after 200us
                fprintf(stderr, "Error: Timeout waiting for GPIO %d\n", gpio_pin);
                return data; // Return invalid data
            }
        }
        pulse_lengths[i] = count;
    }

    // Decode data bits
    for (i = 3; i < 43; i++) {
        data_bits[bit_count++] = (pulse_lengths[2 * i + 2] > pulse_lengths[2 * i + 3]);
    }

    // Convert data bits to bytes
    unsigned char bytes[5] = {0};
    for (i = 0; i < 40; i++) {
        bytes[i / 8] <<= 1;
        if (data_bits[i]) {
            bytes[i / 8] |= 1;
        }
    }

    // Validate checksum
    if (bytes[4] != ((bytes[0] + bytes[1] + bytes[2] + bytes[3]) & 0xFF)) {
        fprintf(stderr, "Error: Checksum failure on GPIO %d\n", gpio_pin);
        return data; // Return invalid data
    }

    // Convert data to temperature and humidity
    data.humidity = (float)(((bytes[0] << 8) | bytes[1])) / 10.0;
    data.temperature = (float)(((bytes[2] & 0x7F) << 8) | bytes[3]) / 10.0;
    if (bytes[2] & 0x80) {
        data.temperature *= -1.0;
    }

    data.valid = 1; // Set data as valid
    return data;
}

// Function to log data to a file
void log_data(int gpio_pin, float temperature, float humidity) {
    FILE *fp = fopen("dht22_log.txt", "a");
    if (fp == NULL) {
        fprintf(stderr, "Error: Could not open log file\n");
        return;
    }

    time_t t = time(NULL);
    struct tm *tm = localtime(&t);
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", tm);

    fprintf(fp, "%s, GPIO: %d, Temperature: %.1f C, Humidity: %.1f %%\n", timestamp, gpio_pin, temperature, humidity);
    fclose(fp);
}

int main() {
    // Initialize pigpio library
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return 1;
    }

    // Set signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    int cycle_count = 0;

    // Main loop
    while (program_running && cycle_count < NUM_CYCLES) {
        printf("Cycle %d/%d\n", cycle_count + 1, NUM_CYCLES);

        // Read data from DHT22 sensor 1
        DHT22Data data1 = read_dht22(DHT22_PIN_1);
        if (data1.valid) {
            printf("GPIO %d: Temperature = %.1f C, Humidity = %.1f %%\n", DHT22_PIN_1, data1.temperature, data1.humidity);
            log_data(DHT22_PIN_1, data1.temperature, data1.humidity);
        } else {
            fprintf(stderr, "Error: Invalid data from GPIO %d\n", DHT22_PIN_1);
        }

        // Read data from DHT22 sensor 2
        DHT22Data data2 = read_dht22(DHT22_PIN_2);
        if (data2.valid) {
