#include <stdio.h>
#include <stdlib.h>
#include <gpiod.h>
#include <unistd.h>
#include <signal.h>
#include <time.h>

// Define GPIO pins
#define GPIO_8 8
#define GPIO_9 9
#define GPIO_10 10
#define GPIO_11 11
#define GPIO_23 23

// Define the number of cycles
#define NUM_CYCLES 3

// Define the delay between cycles (in seconds)
#define DELAY_SEC 1

// Global variables for GPIO lines and chip
struct gpiod_line *gpio_lines[5];
struct gpiod_chip *gpio_chip;

// Signal handler for Ctrl+C
void signal_handler(int sig) {
    printf("\nCaught signal %d, cleaning up...\n", sig);

    // Set all GPIO pins to input (safe state)
    for (int i = 0; i < 5; i++) {
        if (gpio_lines[i] != NULL) {
            gpiod_line_set_value(gpio_lines[i], 0); // Set to 0 to avoid shorts
            gpiod_line_release(gpio_lines[i]);
        }
    }

    // Close the GPIO chip
    if (gpio_chip != NULL) {
        gpiod_chip_close(gpio_chip);
    }

    exit(0);
}

int main() {
    // Register the signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    // Open the GPIO chip
    gpio_chip = gpiod_chip_open_by_name("gpiochip0");
    if (!gpio_chip) {
        perror("Error opening GPIO chip");
        return 1;
    }

    // Get the GPIO lines
    gpio_lines[0] = gpiod_chip_get_line(gpio_chip, GPIO_8);
    gpio_lines[1] = gpiod_chip_get_line(gpio_chip, GPIO_9);
    gpio_lines[2] = gpiod_chip_get_line(gpio_chip, GPIO_10);
    gpio_lines[3] = gpiod_chip_get_line(gpio_chip, GPIO_11);
    gpio_lines[4] = gpiod_chip_get_line(gpio_chip, GPIO_23);

    if (!gpio_lines[0] || !gpio_lines[1] || !gpio_lines[2] || !gpio_lines[3] || !gpio_lines[4]) {
        perror("Error getting GPIO line");
        // Release any previously acquired lines
        for (int i = 0; i < 5; i++) {
            if (gpio_lines[i] != NULL) {
                gpiod_line_release(gpio_lines[i]);
            }
        }
        gpiod_chip_close(gpio_chip);
        return 1;
    }

    // Request the GPIO lines for output
    for (int i = 0; i < 5; i++) {
        if (gpiod_line_request_output(gpio_lines[i], "gpio_output", 0) < 0) {
            perror("Error requesting GPIO line for output");
            // Release any previously acquired lines
            for (int j = 0; j < 5; j++) {
                if (gpio_lines[j] != NULL) {
                    gpiod_line_release(gpio_lines[j]);
                }
            }
            gpiod_chip_close(gpio_chip);
            return 1;
        }
    }

    // Main loop
    for (int cycle = 0; cycle < NUM_CYCLES; cycle++) {
        // Set GPIO 8 to HIGH
        if (gpiod_line_set_value(gpio_lines[0], 1) < 0) {
            perror("Error setting GPIO 8 HIGH");
        }
        printf("GPIO 8 HIGH\n");

        // Set GPIO 9 to LOW
        if (gpiod_line_set_value(gpio_lines[1], 0) < 0) {
            perror("Error setting GPIO 9 LOW");
        }
        printf("GPIO 9 LOW\n");

        // Set GPIO 10 to HIGH
        if (gpiod_line_set_value(gpio_lines[2], 1) < 0) {
            perror("Error setting GPIO 10 HIGH");
        }
        printf("GPIO 10 HIGH\n");

        // Set GPIO 11 to LOW
        if (gpiod_line_set_value(gpio_lines[3], 0) < 0) {
            perror("Error setting GPIO 11 LOW");
        }
        printf("GPIO 11 LOW\n");

        // Set GPIO 23 to HIGH
        if (gpiod_line_set_value(gpio_lines[4], 1) < 0) {
            perror("Error setting GPIO 23 HIGH");
        }
        printf("GPIO 23 HIGH\n");

        sleep(DELAY_SEC);

        // Set GPIO 8 to LOW
        if (gpiod_line_set_value(gpio_lines[0], 0) < 0) {
            perror("Error setting GPIO 8 LOW");
        }
        printf("GPIO 8 LOW\n");

        // Set GPIO 9 to HIGH
        if (gpiod_line_set_value(gpio_lines[1], 1) < 0) {
            perror("Error setting GPIO 9 HIGH");
        }
        printf("GPIO 9 HIGH\n");

        // Set GPIO 10 to LOW
        if (gpiod_line_set_value(gpio_lines[2], 0) < 0) {
            perror("Error setting GPIO 10 LOW");
        }
        printf("GPIO 10 LOW\n");

        // Set GPIO 11 to HIGH
        if (gpiod_line_set_value(gpio_lines[3], 1) < 0) {
            perror("Error setting GPIO 11 HIGH");
        }
        printf("GPIO 11 HIGH\n");

        // Set GPIO 23 to LOW
        if (gpiod_line_set_value(gpio_lines[4], 0) < 0) {
            perror("Error setting GPIO 23 LOW");
        }
        printf("GPIO 23 LOW\n");

        sleep(DELAY_SEC);
    }

    // Clean up and exit
    for (int i = 0; i < 5; i++) {
        if (gpio_lines[i] != NULL) {
            gpiod_line_release(gpio_lines[i]);
        }
    }
    gpiod_chip_close(gpio_chip);

    return 0;
}

