#include <signal.h>
#include <errno.h>

// Define GPIO pins
#define GPIO_16 16
#define GPIO_20 20

// Global variables for GPIO lines and chip
struct gpiod_line *gpio_line_16 = NULL;
struct gpiod_line *gpio_line_20 = NULL;
struct gpiod_chip *gpio_chip = NULL;

// Signal handler for Ctrl+C
void signal_handler(int sig) {
    printf("\nCaught signal %d, cleaning up...\n", sig);

    // Release GPIO lines
    if (gpio_line_16) {
        gpiod_line_release(gpio_line_16);
    }
    if (gpio_line_20) {
        gpiod_line_release(gpio_line_20);
    }

    // Close GPIO chip
    if (gpio_chip) {
        gpiod_chip_close(gpio_chip);
    }

    exit(0);
}

int main() {
    // Register signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    // Open GPIO chip
    gpio_chip = gpiod_chip_open_by_name("gpiochip0");
    if (!gpio_chip) {
        fprintf(stderr, "Error opening GPIO chip: %s\n", strerror(errno));
        return 1;
    }

    // Get GPIO lines
    gpio_line_16 = gpiod_chip_get_line(gpio_chip, GPIO_16);
    if (!gpio_line_16) {
        fprintf(stderr, "Error getting GPIO %d line: %s\n", GPIO_16, strerror(errno));
        gpiod_chip_close(gpio_chip);
        return 1;
    }

    gpio_line_20 = gpiod_chip_get_line(gpio_chip, GPIO_20);
    if (!gpio_line_20) {
        fprintf(stderr, "Error getting GPIO %d line: %s\n", GPIO_20, strerror(errno));
        gpiod_line_release(gpio_line_16);
        gpiod_chip_close(gpio_chip);
        return 1;
    }

    // Request GPIO lines for output
    if (gpiod_line_request_output(gpio_line_16, "gpio_output", 0) < 0) {
        fprintf(stderr, "Error requesting GPIO %d for output: %s\n", GPIO_16, strerror(errno));
        gpiod_line_release(gpio_line_16);
        gpiod_line_release(gpio_line_20);
        gpiod_chip_close(gpio_chip);
        return 1;
    }

    if (gpiod_line_request_output(gpio_line_20, "gpio_output", 0) < 0) {
        fprintf(stderr, "Error requesting GPIO %d for output: %s\n", GPIO_20, strerror(errno));
        gpiod_line_release(gpio_line_16);
        gpiod_line_release(gpio_line_20);
        gpiod_chip_close(gpio_chip);
        return 1;
    }

    // Main loop
    while (1) {
        // Set GPIO 16 HIGH
        if (gpiod_line_set_value(gpio_line_16, 1) < 0) {
            fprintf(stderr, "Error setting GPIO %d HIGH: %s\n", GPIO_16, strerror(errno));
        }
        printf("GPIO %d: HIGH\n", GPIO_16);

        // Set GPIO 20 LOW
        if (gpiod_line_set_value(gpio_line_20, 0) < 0) {
            fprintf(stderr, "Error setting GPIO %d LOW: %s\n", GPIO_20, strerror(errno));
        }
        printf("GPIO %d: LOW\n", GPIO_20);

        // Wait for 0.1 seconds
        struct timespec sleep_time;
        sleep_time.tv_sec = 0;
        sleep_time.tv_nsec = 100 * 1000 * 1000; // 100 milliseconds
        nanosleep(&sleep_time, NULL);

        // Set GPIO 16 LOW
        if (gpiod_line_set_value(gpio_line_16, 0) < 0) {
            fprintf(stderr, "Error setting GPIO %d LOW: %s\n", GPIO_16, strerror(errno));
        }
        printf("GPIO %d: LOW\n", GPIO_16);

        // Set GPIO 20 HIGH
        if (gpiod_line_set_value(gpio_line_20, 1) < 0) {
            fprintf(stderr, "Error setting GPIO %d HIGH: %s\n", GPIO_20, strerror(errno));
        }
        printf("GPIO %d: HIGH\n", GPIO_20);

        // Wait for 0.1 seconds
        nanosleep(&sleep_time, NULL);
    }

    return 0;
}

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/spi/spidev.h>
#include <signal.h>
#include <errno.h>
#include <string.h>

// Define SPI device and settings
#define SPI_DEVICE "/dev/spidev0.0"
#define SPI_MODE SPI_MODE_0
#define SPI_BITS_PER_WORD 8
#define SPI_SPEED 1000000 // 1 MHz

// Global variable for SPI file descriptor
int spi_fd = -1;

// Signal handler for Ctrl+C
void signal_handler(int sig) {
    printf("\nCaught signal %d, cleaning up...\n", sig);
    if (spi_fd != -1) {
        close(spi_fd);
    }
    exit(0);
}

// Function to read data from MAX31855
int read_max31855(int fd, uint8_t *data) {
    struct spi_ioc_transfer transfer = {
        .tx_buf = (unsigned long)NULL, // No transmit data
        .rx_buf = (unsigned long)data,
        .len = 4,
        .speed_hz = SPI_SPEED,
        .bits_per_word = SPI_BITS_PER_WORD,
    };

    if (ioctl(fd, SPI_IOC_MESSAGE(1), &transfer) < 0) {
        perror("SPI transfer failed");
        return -1;
    }

    return 0;
}

// Function to process raw data and extract temperature
float process_data(uint8_t *data) {
    // Check for fault bits
    if (data[3] & 0x07) {
        fprintf(stderr, "Error: MAX31855 fault detected!\n");
        if (data[3] & 0x01) fprintf(stderr, "  Open circuit\n");
        if (data[3] & 0x02) fprintf(stderr, "  Short to GND\n");
        if (data[3] & 0x04) fprintf(stderr, "  Short to VCC\n");
        return -1000.0; // Indicate error
    }

    // Extract temperature data (bits 31:18)
    int16_t raw_temp = ((data[0] << 8) | data[1]) >> 2;

    // Convert to Celsius
    float temperature = raw_temp * 0.25;

    return temperature;
}

int main() {
    // Register signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    // Open SPI device
    spi_fd = open(SPI_DEVICE, O_RDWR);
    if (spi_fd < 0) {
        perror("Failed to open SPI device");
        return 1;
    }

    // Configure SPI mode
    uint8_t mode = SPI_MODE;
    if (ioctl(spi_fd, SPI_IOC_WR_MODE, &mode) < 0) {
        perror("Failed to set SPI mode");
        close(spi_fd);
        return 1;
    }

    // Configure bits per word
    uint8_t bits = SPI_BITS_PER_WORD;
    if (ioctl(spi_fd, SPI_IOC_WR_BITS_PER_WORD, &bits) < 0) {
        perror("Failed to set bits per word");
        close(spi_fd);
        return 1;
    }

    // Configure SPI speed
    uint32_t speed = SPI_SPEED;
    if (ioctl(spi_fd, SPI_IOC_WR_MAX_SPEED_HZ, &speed) < 0) {
        perror("Failed to set SPI speed");
        close(spi_fd);
        return 1;
    }

    uint8_t data[4];

    // Main loop
    while (1) {
        // Read data from MAX31855
        if (read_max31855(spi_fd, data) == 0) {
            // Process the data
            float temperature = process_data(data);

            // Print the temperature
            if (temperature != -1000.0) {
                printf("Temperature: %.2f °C\n", temperature);
            } else {
                fprintf(stderr, "Failed to read temperature.\n");
            }
        } else {
            fprintf(stderr, "Failed to read from SPI.\n");
        }

        // Wait for 1 second
        sleep(1);
    }

    // Close SPI device (this will not be reached in the infinite loop)
    close(spi_fd);

    return 0;
}

