        gpioDelay(100000);
    }

    // Clean up and terminate pigpio library
    gpioTerminate();
    printf("pigpio terminated.\n");

    return 0;
}

#include <stdio.h>
#include <stdlib.h>
#include <gpiod.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>

// Define GPIO pins
#define TRIGGER_PIN 4
#define ECHO_PIN 17

// Define GPIO chip name
#define GPIO_CHIP "gpiochip0"

// Define timeout duration (in seconds)
#define TIMEOUT 1

// Global variables for GPIO lines and chip
struct gpiod_line *trigger_line = NULL;
struct gpiod_line *echo_line = NULL;
struct gpiod_chip *chip = NULL;

// Signal handler for Ctrl+C
void signal_handler(int sig) {
    printf("\nCaught signal %d, cleaning up...\n", sig);

    // Release GPIO lines
    if (trigger_line) {
        gpiod_line_release(trigger_line);
    }
    if (echo_line) {
        gpiod_line_release(echo_line);
    }

    // Close GPIO chip
    if (chip) {
        gpiod_chip_close(chip);
    }

    exit(0);
}

// Function to measure distance using HC-SR04
float measure_distance() {
    struct timespec start, end;
    long long start_ns, end_ns, diff_ns;
    float distance;

    // Trigger the sensor
    if (gpiod_line_set_value(trigger_line, 1) < 0) {
        perror("Error setting trigger high");
        return -1.0;
    }
    usleep(10); // 10 microseconds
    if (gpiod_line_set_value(trigger_line, 0) < 0) {
        perror("Error setting trigger low");
        return -1.0;
    }

    // Wait for echo to go high
    int timeout_count = 0;
    while (gpiod_line_get_value(echo_line) == 0) {
        clock_gettime(CLOCK_MONOTONIC, &start);
        start_ns = start.tv_sec * 1000000000LL + start.tv_nsec;
        timeout_count++;
        if (timeout_count > TIMEOUT * 1000000) { // Check every microsecond for 1 second
            fprintf(stderr, "Timeout waiting for echo high\n");
            return -1.0;
        }
        usleep(1); // Small delay to avoid busy-waiting
    }

    // Wait for echo to go low
    timeout_count = 0;
    while (gpiod_line_get_value(echo_line) == 1) {
        clock_gettime(CLOCK_MONOTONIC, &end);
        end_ns = end.tv_sec * 1000000000LL + end.tv_nsec;
        timeout_count++;
        if (timeout_count > TIMEOUT * 1000000) { // Check every microsecond for 1 second
            fprintf(stderr, "Timeout waiting for echo low\n");
            return -1.0;
        }
        usleep(1); // Small delay to avoid busy-waiting
    }

    // Calculate pulse duration in nanoseconds
    diff_ns = end_ns - start_ns;

    // Calculate distance in centimeters (speed of sound: 343 m/s)
    distance = (float)diff_ns / 1000000000.0 * 34300.0 / 2.0;

    return distance;
}

int main() {
    // Register signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    // Open GPIO chip
    chip = gpiod_chip_open_by_name(GPIO_CHIP);
    if (!chip) {
        perror("Error opening GPIO chip");
        return 1;
    }

    // Get GPIO lines
    trigger_line = gpiod_chip_get_line(chip, TRIGGER_PIN);
    if (!trigger_line) {
        perror("Error getting trigger line");
        gpiod_chip_close(chip);
        return 1;
    }

    echo_line = gpiod_chip_get_line(chip, ECHO_PIN);
    if (!echo_line) {
        perror("Error getting echo line");
        gpiod_line_release(trigger_line);
        gpiod_chip_close(chip);
        return 1;
    }

    // Request GPIO lines for output and input
    if (gpiod_line_request_output(trigger_line, "trigger", 0) < 0) {
        perror("Error requesting trigger line for output");
        gpiod_line_release(trigger_line);
        gpiod_line_release(echo_line);
        gpiod_chip_close(chip);
        return 1;
    }

    if (gpiod_line_request_input(echo_line, "echo") < 0) {
        perror("Error requesting echo line for input");
        gpiod_line_release(trigger_line);
        gpiod_line_release(echo_line);
        gpiod_chip_close(chip);
        return 1;
    }

    // Main loop
    while (1) {
        float distance = measure_distance();

        if (distance >= 0) {
            printf("Distance: %.2f cm\n", distance);
        } else {
            fprintf(stderr, "Error measuring distance\n");
        }

        sleep(1); // Wait 1 second
    }

    // The following lines will never be reached due to the infinite loop.
    // However, they are included for completeness and to avoid compiler warnings.
    gpiod_line_release(trigger_line);
    gpiod_line_release(echo_line);
    gpiod_chip_close(chip);

    return 0;
}

