#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <fcntl.h>
#include <unistd.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <signal.h>
#include <errno.h>
#include <string.h>

// BMP280 I2C address
#define BMP280_I2C_ADDR 0x76

// BMP280 register addresses
#define BMP280_REG_TEMP_MSB 0xFA
#define BMP280_REG_TEMP_LSB 0xFB
#define BMP280_REG_TEMP_XLSB 0xFC
#define BMP280_REG_PRESS_MSB 0xF7
#define BMP280_REG_PRESS_LSB 0xF8
#define BMP280_REG_PRESS_XLSB 0xF9
#define BMP280_REG_CONFIG 0xF5
#define BMP280_REG_CTRL_MEAS 0xF4
#define BMP280_REG_RESET 0xE0

// Calibration data registers
#define BMP280_REG_CALIB_00 0x88

// Global variables
int i2c_fd;
volatile sig_atomic_t program_running = 1;

// Calibration data structure
struct bmp280_calib_data {
    uint16_t dig_T1;
    int16_t dig_T2;
    int16_t dig_T3;
    uint16_t dig_P1;
    int16_t dig_P2;
    int16_t dig_P3;
    int16_t dig_P4;
    int16_t dig_P5;
    int16_t dig_P6;
    int16_t dig_P7;
    int16_t dig_P8;
    int16_t dig_P9;
};

struct bmp280_calib_data calib;

// Function prototypes
int i2c_read_bytes(int fd, uint8_t reg, uint8_t *data, int len);
int i2c_write_byte(int fd, uint8_t reg, uint8_t data);
int bmp280_init(int fd);
int bmp280_read_raw_data(int fd, int32_t *temperature, int32_t *pressure);
double bmp280_compensate_temperature(int32_t raw_temp);
double bmp280_compensate_pressure(int32_t raw_pressure, double t_fine);
void signal_handler(int sig);
int read_calibration_data(int fd, struct bmp280_calib_data *calib);

// Signal handler for graceful shutdown
void signal_handler(int sig) {
    program_running = 0;
    printf("\nCaught signal %d, exiting gracefully.\n", sig);
}

// I2C read function
int i2c_read_bytes(int fd, uint8_t reg, uint8_t *data, int len) {
    if (write(fd, &reg, 1) != 1) {
        perror("Failed to write register address");
        return -1;
    }
    if (read(fd, data, len) != len) {
        perror("Failed to read data");
        return -1;
    }
    return 0;
}

// I2C write function
int i2c_write_byte(int fd, uint8_t reg, uint8_t data) {
    uint8_t buf[2];
    buf[0] = reg;
    buf[1] = data;
    if (write(fd, buf, 2) != 2) {
        perror("Failed to write data");
        return -1;
    }
    return 0;
}

// BMP280 initialization function
int bmp280_init(int fd) {
    // Reset the device
    if (i2c_write_byte(fd, BMP280_REG_RESET, 0xB6) != 0) {
        fprintf(stderr, "Error resetting BMP280\n");
        return -1;
    }
    usleep(10000); // Wait for the reset to complete

    // Set the configuration register (t_sb = 0.5ms, filter = off)
    if (i2c_write_byte(fd, BMP280_REG_CONFIG, 0x00) != 0) {
        fprintf(stderr, "Error writing to config register\n");
        return -1;
    }

    // Set the control measurement register (osrs_t = x1, osrs_p = x1, normal mode)
    if (i2c_write_byte(fd, BMP280_REG_CTRL_MEAS, 0x27) != 0) {
        fprintf(stderr, "Error writing to control measurement register\n");
        return -1;
    }

    return 0;
}

// Read raw temperature and pressure data from the BMP280
int bmp280_read_raw_data(int fd, int32_t *temperature, int32_t *pressure) {
    uint8_t data[6];

    if (i2c_read_bytes(fd, BMP280_REG_PRESS_MSB, data, 6) != 0) {
        fprintf(stderr, "Error reading raw data\n");
        return -1;
    }

    *pressure = (data[0] << 12) | (data[1] << 4) | (data[2] >> 4);
    *temperature = (data[3] << 12) | (data[4] << 4) | (data[5] >> 4);

    return 0;
}

// Compensate temperature using calibration data
double bmp280_compensate_temperature(int32_t raw_temp) {
    double var1, var2, T;
    double dig_T1 = (double)calib.dig_T1;
    double dig_T2 = (double)calib.dig_T2;
    double dig_T3 = (double)calib.dig_T3;

    var1 = (((double)raw_temp) / 16384.0 - dig_T1 / 1024.0) * dig_T2;
    var2 = ((((double)raw_temp) / 131072.0 - dig_T1 / 8192.0) * (((double)raw_temp) / 131072.0 - dig_T1 / 8192.0)) * dig_T3;
    double t_fine = (var1 + var2);
    T = (var1 + var2) / 5120.0;
    return T;
}

// Compensate pressure using calibration data
double bmp280_compensate_pressure(int32_t raw_pressure, double t_fine) {
    double var1, var2, p;
    double dig_P1 = (double)calib.dig_P1;
    double dig_P2 = (double)calib.dig_P2;
    double dig_P3 = (double)calib.dig_P3;
    double dig_P4 = (double)calib.dig_P4;
    double dig_P5 = (double)calib.dig_P5;
    double dig_P6 = (double)calib.dig_P6;
    double dig_P7 = (double)calib.dig_P7;
    double dig_P8 = (double)calib.dig_P8;
    double dig_P9 = (double)calib.dig_P9;

    var1 = (t_fine / 2.0) - 64000.0;
    var2 = var1 * var1 * dig_P6 / 32768.0;
    var2 = var2 + var1 * dig_P5 * 2.0;
    var2 = (var2 / 4.0) + (dig_P4 * 65536.0);
    var1 = (dig_P3 * var1 * var1 / 524288.0 + dig_P2 * var1) / 524288.0;
    var1 = (1.0 + var1 / 32768.0) * dig_P1;

    if (var1 == 0)
    {
        return 0;
    }

    p = 1048576.0 - (double)raw_pressure;
    p = (p - (var2 / 4096.0)) * 6250.0 / var1;
    var1 = dig_P9 * p * p / 2147483648.0;
    var2 = p * dig_P8 / 32768.0;
    p = p + (var1 + var2 + dig_P7) / 16.0;

    return p;
}

// Read calibration data from the BMP280
int read_calibration_data(int fd, struct bmp280_calib_data *calib) {
    uint8_t data[26];

    if (i2c_read_bytes(fd, BMP280_REG_CALIB_00, data, 26) != 0) {
        fprintf(stderr, "Error reading calibration data\n");
        return -1;
    }

    calib->dig_T1 = (data[1] << 8) | data[0];
    calib->dig_T2 = (data[3] << 8) | (int8_t)data[2];
    calib->dig_T3 = (data[5] << 8) | (int8_t)data[4];
    calib->dig_P1 = (data[7] << 8) | data[6];
    calib->dig_P2 = (data[9] << 8) | (int8_t)data[8];
    calib->dig_P3 = (data[11] << 8) | (int8_t)data[10];
    calib->dig_P4 = (data[13] << 8) | (int8_t)data[12];
    calib->dig_P5 = (data[15] << 8) | (int8_t)data[14];
    calib->dig_P6 = (data[17] << 8) | (int8_t)data[16];
    calib->dig_P7 = (data[19] << 8) | (int8_t)data[18];
    calib->dig_P8 = (data[21] << 8) | (int8_t)data[20];
    calib->dig_P9 = (data[23] << 8) | (int8_t)data[22];

    return 0;
}

int main() {
    int32_t raw_temperature, raw_pressure;
    double temperature, pressure;
    int i;

    // Register signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    // Open I2C device
    i2c_fd = open("/dev/i2c-1", O_RDWR);
    if (i2c_fd < 0) {
        perror("Failed to open I2C device");
        return 1;
    }

    // Specify the address of the slave device
    if (ioctl(i2c_fd, I2C_SLAVE, BMP280_I2C_ADDR) < 0) {
        perror("Failed to acquire bus access and/or talk to slave");
        close(i2c_fd);
        return 1;
    }

    // Read calibration data
    if (read_calibration_data(i2c_fd, &calib) != 0) {
        fprintf(stderr, "Failed to read calibration data. Exiting.\n");
        close(i2c_fd);
        return 1;
    }

    // Initialize BMP280
    if (bmp280_init(i2c_fd) != 0) {
        fprintf(stderr, "Failed to initialize BMP280. Exiting.\n");
        close(i2c_fd);
        return 1;
    }

    // Main loop
    for (i = 0; i < 3 && program_running; i++) {
        // Read raw data
        if (bmp280_read_raw_data(i2c_fd, &raw_temperature, &raw_pressure) == 0) {
            // Compensate temperature and pressure
            temperature = bmp280_compensate_temperature(raw_temperature);
            pressure = bmp280_compensate_pressure(raw_pressure, temperature);

            // Print the results
            printf("Temperature: %.2f \u00b0C, Pressure: %.2f Pa\n", temperature, pressure);
        } else {
            fprintf(stderr, "Failed to read sensor data. Retrying...\n");
            // Attempt to re-initialize the sensor
            if (bmp280_init(i2c_fd) != 0) {
                fprintf(stderr, "Failed to re-initialize BMP280. Exiting.\n");
                program_running = 0; // Exit the loop if re-initialization fails
            }
        }

        sleep(1); // Wait for 1 second
    }

    // Close I2C device
    close(i2c_fd);

    return 0;
}

#include <stdio.h>
#include <stdlib.h>
#include <gpiod.h>
#include <signal.h>
#include <unistd.h>

// Define GPIO pins
#define GPIO_17 17
#define GPIO_22 22
#define GPIO_23 23
#define GPIO_24 24

// Global variables for GPIO lines and chip
struct gpiod_line *gpio_lines[4];
struct gpiod_chip *gpio_chip;

// Signal handler for Ctrl+C
void signal_handler(int sig) {
    printf("\nCaught signal %d, cleaning up...\n", sig);

    // Set all GPIO pins to input (safe state)
    for (int i = 0; i < 4; i++) {
        if (gpio_lines[i] != NULL) {
            gpiod_line_set_value(gpio_lines[i], 0); // Set to 0 to avoid floating
            gpiod_line_release(gpio_lines[i]);
        }
    }

    if (gpio_chip != NULL) {
        gpiod_chip_close(gpio_chip);
    }

    exit(0);
}

int main() {
    // Register signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    // Open GPIO chip
    gpio_chip = gpiod_chip_open_by_name("gpiochip0");
    if (!gpio_chip) {
        perror("Error opening GPIO chip");
        return 1;
    }

    // Get GPIO lines
    gpio_lines[0] = gpiod_chip_get_line(gpio_chip, GPIO_17);
    gpio_lines[1] = gpiod_chip_get_line(gpio_chip, GPIO_22);
    gpio_lines[2] = gpiod_chip_get_line(gpio_chip, GPIO_23);
    gpio_lines[3] = gpiod_chip_get_line(gpio_chip, GPIO_24);

    if (!gpio_lines[0] || !gpio_lines[1] || !gpio_lines[2] || !gpio_lines[3]) {
        perror("Error getting GPIO line");
        gpiod_chip_close(gpio_chip);
        return 1;
    }

    // Request GPIO lines for output
    for (int i = 0; i < 4; i++) {
        if (gpiod_line_request_output(gpio_lines[i], "gpio_output", 0) < 0) {
            perror("Error requesting GPIO line for output");
            // Release previously requested lines
            for (int j = 0; j < i; j++) {
                gpiod_line_release(gpio_lines[j]);
            }
            gpiod_chip_close(gpio_chip);
            return 1;
        }
    }

    // Set GPIO pin states
    int states[4] = {1, 0, 1, 0};
    for (int i = 0; i < 4; i++) {
        if (gpiod_line_set_value(gpio_lines[i], states[i]) < 0) {
            perror("Error setting GPIO line value");
            // Release previously set lines
            for (int j = 0; j < 4; j++) {
                gpiod_line_release(gpio_lines[j]);
            }
            gpiod_chip_close(gpio_chip);
            return 1;
        }
        printf("GPIO %d set to %d\n", i + GPIO_17, states[i]);
    }

    // Wait for 5 seconds
    sleep(5);

    // Release GPIO lines
    for (int i = 0; i < 4; i++) {
        gpiod_line_release(gpio_lines[i]);
    }

    // Close GPIO chip
    gpiod_chip_close(gpio_chip);

    return 0;
}

#include <stdio.h>
#include <stdlib.h>
