static struct gpiod_chip *chip;
static struct gpiod_line *line;
static volatile sig_atomic_t terminate = 0;

// Signal handler for Ctrl+C
void sigint_handler(int sig)
{
    terminate = 1;
}

// Function to export the GPIO pin
int export_gpio(int pin)
{
    char buffer[64];
    int len;
    FILE *fp = NULL;

    fp = fopen("/sys/class/gpio/export", "w");
    if (fp == NULL) {
        perror("Failed to open export file");
        return -1;
    }

    len = snprintf(buffer, sizeof(buffer), "%d", pin);
    if (fwrite(buffer, 1, len, fp) != len) {
        perror("Failed to write to export file");
        fclose(fp);
        return -1;
    }

    fclose(fp);
    return 0;
}

// Function to unexport the GPIO pin
int unexport_gpio(int pin)
{
    char buffer[64];
    int len;
    FILE *fp = NULL;

    fp = fopen("/sys/class/gpio/unexport", "w");
    if (fp == NULL) {
        perror("Failed to open unexport file");
        return -1;
    }

    len = snprintf(buffer, sizeof(buffer), "%d", pin);
    if (fwrite(buffer, 1, len, fp) != len) {
        perror("Failed to write to unexport file");
        fclose(fp);
        return -1;
    }

    fclose(fp);
    return 0;
}

// Function to set the GPIO direction
int set_gpio_direction(int pin, const char *direction)
{
    char path[64];
    FILE *fp = NULL;

    snprintf(path, sizeof(path), "/sys/class/gpio/gpio%d/direction", pin);
    fp = fopen(path, "w");
    if (fp == NULL) {
        perror("Failed to open direction file");
        return -1;
    }

    if (fprintf(fp, "%s", direction) < 0) {
        perror("Failed to write to direction file");
        fclose(fp);
        return -1;
    }

    fclose(fp);
    return 0;
}

// Function to set the GPIO value
int set_gpio_value(int pin, int value)
{
    char path[64];
    FILE *fp = NULL;

    snprintf(path, sizeof(path), "/sys/class/gpio/gpio%d/value", pin);
    fp = fopen(path, "w");
    if (fp == NULL) {
        perror("Failed to open value file");
        return -1;
    }

    if (fprintf(fp, "%d", value) < 0) {
        perror("Failed to write to value file");
        fclose(fp);
        return -1;
    }

    fclose(fp);
    return 0;
}

// Function to read the GPIO value
int read_gpio_value(int pin)
{
    char path[64];
    FILE *fp = NULL;
    int value;

    snprintf(path, sizeof(path), "/sys/class/gpio/gpio%d/value", pin);
    fp = fopen(path, "r");
    if (fp == NULL) {
        perror("Failed to open value file for reading");
        return -1;
    }

    if (fscanf(fp, "%d", &value) != 1) {
        perror("Failed to read value from file");
        fclose(fp);
        return -1;
    }

    fclose(fp);
    return value;
}

// Function to validate the GPIO value
int validate_gpio_value(int value)
{
    return (value == 0 || value == 1) ? 0 : -1;
}

// Function to report the GPIO state
void report_gpio_state(int value)
{
    printf("GPIO state: %d\n", value);
}

int main()
{
    int value;

    // Register signal handler for Ctrl+C
    signal(SIGINT, sigint_handler);

    // Export GPIO pin
    if (export_gpio(GPIO_PIN) != 0) {
        fprintf(stderr, "Failed to export GPIO %d\n", GPIO_PIN);
        return 1;
    }

    // Set GPIO direction to output
    if (set_gpio_direction(GPIO_PIN, "out") != 0) {
        fprintf(stderr, "Failed to set GPIO %d direction to output\n", GPIO_PIN);
        unexport_gpio(GPIO_PIN);
        return 1;
    }

    // Main loop
    while (!terminate) {
