#include <errno.h>

#define GPIO_PIN 17
#define GPIO_CHIP "gpiochip0"
#define MAX_RETRIES 3
#define RETRY_DELAY_MS 10

static struct gpiod_chip *chip;
static struct gpiod_line *line;
static volatile sig_atomic_t terminate = 0;

// Signal handler for graceful shutdown
void signal_handler(int sig) {
    terminate = 1;
    printf("\nCaught signal %d, exiting gracefully.\n", sig);
}

// Function to read the GPIO value from the specified line
int read_gpio(struct gpiod_line *line) {
    int value, retries = 0;

    while (retries < MAX_RETRIES) {
        value = gpiod_line_get_value(line);
        if (value >= 0) {
            return value;
        } else {
            fprintf(stderr, "Error reading GPIO value: %s\n", strerror(errno));
            retries++;
            usleep(RETRY_DELAY_MS * 1000); // Exponential backoff
        }
    }

    fprintf(stderr, "Failed to read GPIO value after %d retries.\n", MAX_RETRIES);
    return -1; // Indicate failure
}

// Function to set the GPIO value on the specified line
int set_gpio(struct gpiod_line *line, int value) {
    int ret, retries = 0;

    while (retries < MAX_RETRIES) {
        ret = gpiod_line_set_value(line, value);
        if (ret == 0) {
            return 0; // Success
        } else {
            fprintf(stderr, "Error setting GPIO value: %s\n", strerror(errno));
            retries++;
            usleep(RETRY_DELAY_MS * 1000); // Exponential backoff
        }
    }

    fprintf(stderr, "Failed to set GPIO value after %d retries.\n", MAX_RETRIES);
    return -1; // Indicate failure
}

int main() {
    int gpio_value;
    struct timespec sleep_time;

    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Open the GPIO chip
    chip = gpiod_chip_open_by_name(GPIO_CHIP);
    if (!chip) {
        fprintf(stderr, "Error opening GPIO chip: %s\n", strerror(errno));
        return 1;
    }

    // Get the GPIO line
    line = gpiod_chip_get_line(chip, GPIO_PIN);
    if (!line) {
        fprintf(stderr, "Error getting GPIO line: %s\n", strerror(errno));
        gpiod_chip_close(chip);
        return 1;
    }

    // Request the GPIO line for output
    if (gpiod_line_request_output(line, "gpio_control", 0) < 0) {
        fprintf(stderr, "Error requesting GPIO line for output: %s\n", strerror(errno));
        gpiod_chip_close(chip);
        return 1;
    }

    // Main loop
    while (!terminate) {
        // Read the GPIO value
        gpio_value = read_gpio(line);
        if (gpio_value < 0) {
            fprintf(stderr, "Error reading GPIO value, exiting.\n");
            break;
        }

        // Set the GPIO value
        if (set_gpio(line, gpio_value) < 0) {
            fprintf(stderr, "Error setting GPIO value, exiting.\n");
            break;
        }

        // Report the GPIO state
        printf("GPIO %d set to %d\n", GPIO_PIN, gpio_value);

        // Sleep for 1 second
        sleep_time.tv_sec = 1;
        sleep_time.tv_nsec = 0;
        nanosleep(&sleep_time, NULL);
    }

    // Release the GPIO line
    gpiod_line_release(line);

    // Close the GPIO chip
    gpiod_chip_close(chip);

    return 0;
}

