#define READ_TIMEOUT_MS 100
#define MAX_READ_LENGTH 256

volatile sig_atomic_t program_running = 1;
int uart_fd = -1;

void signal_handler(int signal) {
    program_running = 0;
    printf("\nCaught signal %d, exiting gracefully...\n", signal);
}

int setup_uart(const char *device, speed_t baud_rate) {
    int fd = open(device, O_RDWR | O_NOCTTY | O_SYNC);
    if (fd == -1) {
        perror("Error opening UART");
        return -1;
    }

    struct termios tty;
    if (tcgetattr(fd, &tty) != 0) {
        perror("Error getting termios attributes");
        close(fd);
        return -1;
    }

    tty.c_cflag = baud_rate | CS8 | CLOCAL | CREAD;  // 8N1, no parity
    tty.c_iflag = IGNPAR;                           // Ignore parity errors
    tty.c_oflag = 0;
    tty.c_lflag = 0; // Non-canonical mode

    tty.c_cc[VMIN] = 0;  // Read at least 0 characters
    tty.c_cc[VTIME] = 1; // Wait for 0.1 seconds (10 deciseconds)

    if (tcsetattr(fd, TCSANOW, &tty) != 0) {
        perror("Error setting termios attributes");
        close(fd);
        return -1;
    }

    return fd;
}

int read_data(int fd, char *buffer, size_t max_length) {
    fd_set readfds;
    struct timeval timeout;

    FD_ZERO(&readfds);
    FD_SET(fd, &readfds);

    timeout.tv_sec = 0;
    timeout.tv_usec = READ_TIMEOUT_MS * 1000; // Convert milliseconds to microseconds

    int select_result = select(fd + 1, &readfds, NULL, NULL, &timeout);

    if (select_result == -1) {
        perror("Error in select");
        return -1;
    } else if (select_result == 0) {
        // Timeout occurred
        return 0;
    } else {
        // Data is available
        ssize_t bytes_read = read(fd, buffer, max_length - 1);
        if (bytes_read == -1) {
            perror("Error reading from UART");
            return -1;
        } else {
            buffer[bytes_read] = '\0'; // Null-terminate the string
            return bytes_read;
        }
    }
}

int main() {
    signal(SIGINT, signal_handler);

    uart_fd = setup_uart(UART_DEVICE, BAUD_RATE);
    if (uart_fd == -1) {
        return EXIT_FAILURE;
    }

    char read_buffer[MAX_READ_LENGTH];
    struct timespec sleep_time;
    sleep_time.tv_sec = 0;
    sleep_time.tv_nsec = 100 * 1000 * 1000; // 0.1 seconds

    printf("Reading data from %s at %d baud...\n", UART_DEVICE, BAUD_RATE);

    while (program_running) {
        int bytes_read = read_data(uart_fd, read_buffer, MAX_READ_LENGTH);
        if (bytes_read > 0) {
            printf("Received: %s", read_buffer);
        } else if (bytes_read < 0) {
            fprintf(stderr, "Error reading data. Exiting.\n");
            break;
        }

        nanosleep(&sleep_time, NULL);
    }

    if (uart_fd != -1) {
        close(uart_fd);
    }

    printf("Program finished.\n");
    return EXIT_SUCCESS;
}

