#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <fcntl.h>
#include <unistd.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <signal.h>
#include <errno.h>
#include <string.h>

// ADXL345 I2C address
#define ADXL345_ADDRESS 0x53

// ADXL345 registers
#define ADXL345_POWER_CTL 0x2D
#define ADXL345_DATAX0 0x32
#define ADXL345_DATAX1 0x33
#define ADXL345_DATAY0 0x34
#define ADXL345_DATAY1 0x35
#define ADXL345_DATAZ0 0x36
#define ADXL345_DATAZ1 0x37

// I2C device file
#define I2C_DEVICE "/dev/i2c-1"

// Global variable for I2C file descriptor
int i2c_fd = -1;

// Signal handler for Ctrl+C
void signal_handler(int sig) {
    printf("\nExiting program...\n");
    if (i2c_fd != -1) {
        close(i2c_fd);
    }
    exit(0);
}

// Function to initialize the ADXL345
int adxl345_init(int fd) {
    // Set POWER_CTL register to start measurement
    if (i2c_smbus_write_byte_data(fd, ADXL345_POWER_CTL, 0x08) < 0) {
        perror("Error writing to POWER_CTL register");
        return -1;
    }
    return 0;
}

// Function to read acceleration data from the ADXL345
int adxl345_read_acceleration(int fd, int16_t *x, int16_t *y, int16_t *z) {
    uint8_t data[6];

    // Read 6 bytes of data starting from DATAX0
    if (read(fd, data, 6) != 6) {
        perror("Error reading acceleration data");
        return -1;
    }

    // Combine high and low bytes for each axis
    *x = (int16_t)((data[1] << 8) | data[0]);
    *y = (int16_t)((data[3] << 8) | data[2]);
    *z = (int16_t)((data[5] << 8) | data[4]);

    return 0;
}

int main() {
    // Register signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    // Open I2C device
    i2c_fd = open(I2C_DEVICE, O_RDWR);
    if (i2c_fd < 0) {
        perror("Error opening I2C device");
        return 1;
    }

    // Specify slave address
    if (ioctl(i2c_fd, I2C_SLAVE, ADXL345_ADDRESS) < 0) {
        perror("Error setting I2C slave address");
        close(i2c_fd);
        return 1;
    }

    // Initialize ADXL345
    if (adxl345_init(i2c_fd) < 0) {
        close(i2c_fd);
        return 1;
    }

    int16_t x, y, z;

    // Main loop
    while (1) {
        // Read acceleration data
        if (adxl345_read_acceleration(i2c_fd, &x, &y, &z) == 0) {
            // Print acceleration values
            printf("X: %d, Y: %d, Z: %d\n", x, y, z);
        } else {
            fprintf(stderr, "Failed to read acceleration data. Retrying...\n");
        }

        // Delay for 100 milliseconds
        usleep(100000);
    }

    // Close I2C device (this will not be reached in the infinite loop)
    close(i2c_fd);

    return 0;
}

