    int gpios[] = {GPIO_4, GPIO_17, GPIO_18, GPIO_22, GPIO_23, GPIO_24, GPIO_25, GPIO_27};
    int num_gpios = sizeof(gpios) / sizeof(gpios[0]);

    for (int i = 0; i < num_gpios; i++) {
        if (gpioSetMode(gpios[i], PI_OUTPUT) != 0) {
            fprintf(stderr, "Error setting GPIO %d as output\n", gpios[i]);
            gpioTerminate();
            return 1;
        }
    }

    // Register signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    // Main loop
    while (program_running) {
        for (int i = 0; i < num_gpios; i++) {
            // Set GPIO high
            if (set_gpio_state(gpios[i], 1) == 0) {
                report_gpio_state(gpios[i], 1);
            }

            // Wait for 50 milliseconds
            gpioDelay(50000); // 50 milliseconds = 50000 microseconds

            // Set GPIO low
            if (set_gpio_state(gpios[i], 0) == 0) {
                report_gpio_state(gpios[i], 0);
            }

            // Wait for 50 milliseconds
            gpioDelay(50000); // 50 milliseconds = 50000 microseconds
        }
    }

    // Clean up and terminate pigpio library
    gpioTerminate();
    printf("pigpio terminated.\n");

    return 0;
}

