#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define GPIO_PIN 18
#define PWM_FREQUENCY 1000 // Hz
#define PWM_RANGE 1000

volatile sig_atomic_t program_running = 1;

void signal_handler(int signal) {
    program_running = 0;
    printf("\nCaught signal %d, exiting gracefully...\n", signal);
}

int main() {
    int duty_cycle;

    // Register signal handlers for graceful shutdown
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize pigpio library
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO 18 as output
    gpioSetMode(GPIO_PIN, PI_OUTPUT);

    // Set PWM frequency
    gpioSetPWMfrequency(GPIO_PIN, PWM_FREQUENCY);

    // Set PWM range
    gpioSetPWMrange(GPIO_PIN, PWM_RANGE);

    printf("PWM control program started. Press Ctrl+C to exit.\n");

    while (program_running) {
        // Cycle through duty cycles from 0 to 1000
        for (duty_cycle = 0; duty_cycle <= PWM_RANGE; duty_cycle++) {
            gpioPWM(GPIO_PIN, duty_cycle);
            printf("Duty Cycle: %d\n", duty_cycle);
            usleep(10000); // 10ms delay
        }

        // Cycle through duty cycles from 1000 to 0
        for (duty_cycle = PWM_RANGE; duty_cycle >= 0; duty_cycle--) {
            gpioPWM(GPIO_PIN, duty_cycle);
            printf("Duty Cycle: %d\n", duty_cycle);
            usleep(10000); // 10ms delay
        }
    }

    // Stop PWM output
    gpioPWM(GPIO_PIN, 0);

    // Release GPIO resources
    gpioTerminate();

    printf("Program terminated.\n");
    return 0;
}

#include <stdio.h>
#include <stdlib.h>
#include <gpiod.h>
#include <unistd.h>
#include <signal.h>
#include <errno.h>

// Define GPIO pins
#define GPIO_4 4
#define GPIO_17 17

// Define chip name
#define CHIP_NAME "gpiochip0"

// Global variables for GPIO lines and chip
struct gpiod_line *gpio4_line = NULL;
struct gpiod_line *gpio17_line = NULL;
struct gpiod_chip *chip = NULL;

// Signal handler for Ctrl+C
void signal_handler(int sig) {
    printf("\nCaught signal %d, cleaning up...\n", sig);

    // Release GPIO lines
    if (gpio4_line) {
        gpiod_line_release(gpio4_line);
    }
    if (gpio17_line) {
        gpiod_line_release(gpio17_line);
    }

    // Close GPIO chip
    if (chip) {
        gpiod_chip_close(chip);
    }

    exit(0);
}

int main() {
    int i;
    int ret;

    // Register signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    // Open GPIO chip
    chip = gpiod_chip_open_by_name(CHIP_NAME);
    if (!chip) {
        perror("Error opening GPIO chip");
        return 1;
    }

    // Get GPIO lines for GPIO 4 and GPIO 17
    gpio4_line = gpiod_chip_get_line(chip, GPIO_4);
    if (!gpio4_line) {
        perror("Error getting GPIO 4 line");
        gpiod_chip_close(chip);
        return 1;
    }

    gpio17_line = gpiod_chip_get_line(chip, GPIO_17);
    if (!gpio17_line) {
        perror("Error getting GPIO 17 line");
        gpiod_line_release(gpio4_line);
        gpiod_chip_close(chip);
        return 1;
    }

    // Request GPIO lines for output
    ret = gpiod_line_request_output(gpio4_line, "gpio4_output", 0);
    if (ret < 0) {
        perror("Error requesting GPIO 4 for output");
        gpiod_line_release(gpio4_line);
        gpiod_line_release(gpio17_line);
        gpiod_chip_close(chip);
        return 1;
    }

    ret = gpiod_line_request_output(gpio17_line, "gpio17_output", 0);
    if (ret < 0) {
        perror("Error requesting GPIO 17 for output");
        gpiod_line_release(gpio4_line);
        gpiod_line_release(gpio17_line);
        gpiod_chip_close(chip);
        return 1;
    }

    // Main loop: toggle GPIO 4 and GPIO 17
    for (i = 0; i < 5; i++) {
        // Set GPIO 4 high
        ret = gpiod_line_set_value(gpio4_line, 1);
        if (ret < 0) {
            perror("Error setting GPIO 4 high");
            gpiod_line_release(gpio4_line);
            gpiod_line_release(gpio17_line);
            gpiod_chip_close(chip);
            return 1;
        }
        printf("GPIO 4 set high\n");

        // Set GPIO 17 low
        ret = gpiod_line_set_value(gpio17_line, 0);
        if (ret < 0) {
            perror("Error setting GPIO 17 low");
            gpiod_line_release(gpio4_line);
            gpiod_line_release(gpio17_line);
            gpiod_chip_close(chip);
            return 1;
        }
        printf("GPIO 17 set low\n");

        sleep(1);

        // Set GPIO 4 low
        ret = gpiod_line_set_value(gpio4_line, 0);
        if (ret < 0) {
            perror("Error setting GPIO 4 low");
            gpiod_line_release(gpio4_line);
            gpiod_line_release(gpio17_line);
            gpiod_chip_close(chip);
            return 1;
        }
        printf("GPIO 4 set low\n");

        // Set GPIO 17 high
        ret = gpiod_line_set_value(gpio17_line, 1);
        if (ret < 0) {
            perror("Error setting GPIO 17 high");
            gpiod_line_release(gpio4_line);
            gpiod_line_release(gpio17_line);
            gpiod_chip_close(chip);
            return 1;
        }
        printf("GPIO 17 set high\n");

        sleep(1);
    }

    // Release GPIO lines
    gpiod_line_release(gpio4_line);
    gpiod_line_release(gpio17_line);

    // Close GPIO chip
    gpiod_chip_close(chip);

    printf("Program finished.\n");
    return 0;
}

