#define MAX_READING 1

// Global variables for cleanup
static struct gpiod_chip *chip = NULL;
static struct gpiod_line *line = NULL;
static volatile sig_atomic_t terminate = 0;

// Signal handler for Ctrl+C
void sigint_handler(int sig)
{
    terminate = 1;
}

// Function to read the GPIO value
int read_gpio(struct gpiod_line *line)
{
    int value;
    struct timespec ts;
    ts.tv_sec = 0;
    ts.tv_nsec = 100000000; // 100ms timeout

    value = gpiod_line_get_value_timed(line, &ts);
    if (value < 0) {
        if (errno == ETIMEDOUT) {
            fprintf(stderr, "Error: Timeout reading GPIO value.\n");
            return -1; // Indicate timeout
        } else {
            fprintf(stderr, "Error: Failed to read GPIO value: %s\n", strerror(errno));
            return -1; // Indicate error
        }
    }
    return value;
}

// Function to validate the reading
int validate_reading(int reading)
{
    if (reading >= MIN_READING && reading <= MAX_READING) {
        return 0; // Valid reading
    } else {
        fprintf(stderr, "Error: Invalid reading: %d. Must be between %d and %d.\n", reading, MIN_READING, MAX_READING);
        return -1; // Invalid reading
    }
}

// Function to set the GPIO output
int set_gpio_output(struct gpiod_line *line, int value)
{
    int ret;
    ret = gpiod_line_set_value(line, value);
    if (ret < 0) {
        fprintf(stderr, "Error: Failed to set GPIO value: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

// Function to report the GPIO state
void report_gpio_state(int value)
{
    printf("GPIO state: %d\n", value);
}

// Function to release GPIO resources
void release_gpio(struct gpiod_chip *chip, struct gpiod_line *line)
{
    if (line) {
        gpiod_line_release(line);
    }
    if (chip) {
        gpiod_chip_close(chip);
    }
}

