// TCS34725 Registers
#define TCS34725_ADDRESS         0x29
#define TCS34725_COMMAND_BIT     0x80
#define TCS34725_ENABLE          0x00
#define TCS34725_ATIME           0x01
#define TCS34725_WTIME           0x03
#define TCS34725_AILTL           0x04
#define TCS34725_AILTH           0x05
#define TCS34725_AIHTL           0x06
#define TCS34725_AIHTH           0x07
#define TCS34725_ID              0x12
#define TCS34725_STATUS          0x13
#define TCS34725_CDATA           0x14
#define TCS34725_RDATA           0x16
#define TCS34725_GDATA           0x18
#define TCS34725_BDATA           0x1A

// Enable Register Values
#define TCS34725_ENABLE_AIEN     0x10  // ALS Interrupt Enable
#define TCS34725_ENABLE_WEN      0x08  // Wait enable - Writing 1 activates the wait timer
#define TCS34725_ENABLE_AEN      0x02  // ALS Enable
#define TCS34725_ENABLE_PON      0x01  // Power on

// Integration Time Values
#define TCS34725_INTEGRATIONTIME_2_4MS  0xFF   //  2.4ms - 1 cycle    - Max Count: 1024
#define TCS34725_INTEGRATIONTIME_24MS   0xF6   // 24ms  - 10 cycles   - Max Count: 10240
#define TCS34725_INTEGRATIONTIME_50MS   0xEB   // 50ms  - 20 cycles   - Max Count: 20480
#define TCS34725_INTEGRATIONTIME_101MS  0xD5   // 101ms - 42 cycles   - Max Count: 43008
#define TCS34725_INTEGRATIONTIME_154MS  0xC0   // 154ms - 64 cycles   - Max Count: 65535
#define TCS34725_INTEGRATIONTIME_207MS  0xAC   // 207ms - 80 cycles   - Max Count: 65535
#define TCS34725_INTEGRATIONTIME_260MS  0x97   // 260ms - 97 cycles   - Max Count: 65535
#define TCS34725_INTEGRATIONTIME_313MS  0x82   // 313ms - 113 cycles  - Max Count: 65535

// Gain Values
#define TCS34725_GAIN_1X           0x00   // No gain
#define TCS34725_GAIN_4X           0x01   // 4x gain
#define TCS34725_GAIN_16X          0x02   // 16x gain
#define TCS34725_GAIN_60X          0x03   // 60x gain

// Global variables
int i2c_fd;
volatile sig_atomic_t program_running = 1;

// Function prototypes
int tcs34725_init(int fd);
int tcs34725_read_data(int fd, uint16_t *clear, uint16_t *red, uint16_t *green, uint16_t *blue);
void signal_handler(int signal);

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    program_running = 0;
    printf("\nCaught signal %d, exiting gracefully.\n", signal);
}

// Initialize the TCS34725 sensor
int tcs34725_init(int fd) {
    uint8_t enable_value = TCS34725_ENABLE_PON; // Power on
    uint8_t integration_time = TCS34725_INTEGRATIONTIME_2_4MS; // 2.4ms integration time
    uint8_t gain = TCS34725_GAIN_1X; // No gain

    // Enable power-on
    if (i2c_smbus_write_byte_data(fd, TCS34725_COMMAND_BIT | TCS34725_ENABLE, enable_value) < 0) {
        perror("Error writing to TCS34725_ENABLE");
        return -1;
    }
    usleep(30000); // Wait for power-on (30ms)

    // Set integration time
    if (i2c_smbus_write_byte_data(fd, TCS34725_COMMAND_BIT | TCS34725_ATIME, integration_time) < 0) {
        perror("Error writing to TCS34725_ATIME");
        return -1;
    }

    // Set gain
    if (i2c_smbus_write_byte_data(fd, TCS34725_COMMAND_BIT | TCS34725_CONTROL, gain) < 0) {
        perror("Error writing to TCS34725_CONTROL");
        return -1;
    }

    // Enable ALS (Ambient Light Sensing)
    enable_value |= TCS34725_ENABLE_AEN;
    if (i2c_smbus_write_byte_data(fd, TCS34725_COMMAND_BIT | TCS34725_ENABLE, enable_value) < 0) {
        perror("Error writing to TCS34725_ENABLE");
        return -1;
    }

    return 0;
}

// Read color data from the TCS34725 sensor
int tcs34725_read_data(int fd, uint16_t *clear, uint16_t *red, uint16_t *green, uint16_t *blue) {
    uint8_t data[8];

    // Read all color data registers in one go
    if (read(fd, data, 8) != 8) {
        perror("Error reading color data");
        return -1;
    }

    *clear = (data[1] << 8) | data[0];
    *red   = (data[3] << 8) | data[2];
    *green = (data[5] << 8) | data[4];
    *blue  = (data[7] << 8) | data[6];

    return 0;
}

int main() {
    const char *i2c_device = "/dev/i2c-1"; // I2C device file
    uint16_t clear, red, green, blue;

    // Register signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    // Open I2C device
    i2c_fd = open(i2c_device, O_RDWR);
    if (i2c_fd < 0) {
        perror("Error opening I2C device");
        return 1;
    }

    // Specify slave address
    if (ioctl(i2c_fd, I2C_SLAVE, TCS34725_ADDRESS) < 0) {
        perror("Error setting I2C slave address");
        close(i2c_fd);
        return 1;
    }

    // Initialize the sensor
    if (tcs34725_init(i2c_fd) < 0) {
        fprintf(stderr, "TCS34725 initialization failed.\n");
        close(i2c_fd);
        return 1;
    }

    printf("TCS34725 sensor initialized successfully.\n");

    // Main loop
    while (program_running) {
        // Read color data
        if (tcs34725_read_data(i2c_fd, &clear, &red, &green, &blue) == 0) {
            // Print color data
            printf("Clear: %5u, Red: %5u, Green: %5u, Blue: %5u\n", clear, red, green, blue);
        } else {
            fprintf(stderr, "Failed to read color data.\n");
        }

        // Wait for 0.5 seconds
        usleep(500000);
    }

    // Close I2C device
    close(i2c_fd);

    printf("I2C device closed.\n");

    return 0;
}

