#define GPIO_22 22
#define GPIO_23 23
#define GPIO_24 24
#define GPIO_27 27

// Define the number of GPIO pins
#define NUM_GPIOS 7

// Array of GPIO pins
int gpio_pins[NUM_GPIOS] = {GPIO_4, GPIO_17, GPIO_18, GPIO_22, GPIO_23, GPIO_24, GPIO_27};

// Array of GPIO lines
struct gpiod_line *gpio_lines[NUM_GPIOS];

// GPIO chip
struct gpiod_chip *gpio_chip;

// Signal handler for Ctrl+C
void signal_handler(int sig) {
    printf("\nCaught signal %d, cleaning up...\n", sig);

    // Release GPIO lines
    for (int i = 0; i < NUM_GPIOS; i++) {
        if (gpio_lines[i] != NULL) {
            if (gpiod_line_release(gpio_lines[i]) < 0) {
                fprintf(stderr, "Error releasing GPIO %d: %s\n", gpio_pins[i], strerror(errno));
            }
        }
    }

    // Close GPIO chip
    if (gpio_chip != NULL) {
        if (gpiod_chip_close(gpio_chip) < 0) {
            fprintf(stderr, "Error closing GPIO chip: %s\n", strerror(errno));
        }
    }

    exit(0);
}

int main() {
    // Install signal handler
    signal(SIGINT, signal_handler);

    // Open GPIO chip
    gpio_chip = gpiod_chip_open_by_name("gpiochip0");
    if (!gpio_chip) {
        fprintf(stderr, "Error opening GPIO chip: %s\n", strerror(errno));
        return 1;
    }

    // Get GPIO lines
    for (int i = 0; i < NUM_GPIOS; i++) {
        gpio_lines[i] = gpiod_chip_get_line(gpio_chip, gpio_pins[i]);
        if (!gpio_lines[i]) {
            fprintf(stderr, "Error getting GPIO %d: %s\n", gpio_pins[i], strerror(errno));
            // Release previously acquired lines
            for (int j = 0; j < i; j++) {
                gpiod_line_release(gpio_lines[j]);
            }
            gpiod_chip_close(gpio_chip);
            return 1;
        }
    }

    // Request GPIO lines for output
    for (int i = 0; i < NUM_GPIOS; i++) {
        if (gpiod_line_request_output(gpio_lines[i], "gpio_output", 0) < 0) {
            fprintf(stderr, "Error requesting GPIO %d for output: %s\n", gpio_pins[i], strerror(errno));
            // Release previously acquired lines
            for (int j = 0; j < NUM_GPIOS; j++) {
                if (gpio_lines[j] != NULL) {
                    gpiod_line_release(gpio_lines[j]);
                }
            }
            gpiod_chip_close(gpio_chip);
            return 1;
        }
    }

    // Set GPIO lines to HIGH
    for (int i = 0; i < NUM_GPIOS; i++) {
        if (gpiod_line_set_value(gpio_lines[i], 1) < 0) {
            fprintf(stderr, "Error setting GPIO %d to HIGH: %s\n", gpio_pins[i], strerror(errno));
            // Release previously acquired lines
            for (int j = 0; j < NUM_GPIOS; j++) {
                if (gpio_lines[j] != NULL) {
                    gpiod_line_release(gpio_lines[j]);
                }
            }
            gpiod_chip_close(gpio_chip);
            return 1;
        }
        printf("GPIO %d set to HIGH\n", gpio_pins[i]);
    }

    // Wait for 5 seconds
    sleep(5);

    // Set GPIO lines to LOW
    for (int i = 0; i < NUM_GPIOS; i++) {
        if (gpiod_line_set_value(gpio_lines[i], 0) < 0) {
            fprintf(stderr, "Error setting GPIO %d to LOW: %s\n", gpio_pins[i], strerror(errno));
            // Release previously acquired lines
            for (int j = 0; j < NUM_GPIOS; j++) {
                if (gpio_lines[j] != NULL) {
                    gpiod_line_release(gpio_lines[j]);
                }
            }
            gpiod_chip_close(gpio_chip);
            return 1;
        }
        printf("GPIO %d set to LOW\n", gpio_pins[i]);
    }

    // Wait for 5 seconds
    sleep(5);

    // Release GPIO lines
    for (int i = 0; i < NUM_GPIOS; i++) {
        if (gpiod_line_release(gpio_lines[i]) < 0) {
            fprintf(stderr, "Error releasing GPIO %d: %s\n", gpio_pins[i], strerror(errno));
        }
    }

    // Close GPIO chip
    if (gpiod_chip_close(gpio_chip) < 0) {
        fprintf(stderr, "Error closing GPIO chip: %s\n", strerror(errno));
    }

    return 0;
}

