struct gpiod_line *trigger_line, *echo_line, *led_line;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int init_gpio();
void trigger_pulse();
long long get_pulse_width();
float calculate_distance(long long pulse_width);
void set_led_state(int state);
void cleanup_gpio();
void signal_handler(int sig);

// Signal handler for graceful shutdown
void signal_handler(int sig) {
    terminate = 1;
    printf("\nCaught signal %d, exiting gracefully.\n", sig);
}

// Initialize GPIO pins
int init_gpio() {
    chip = gpiod_chip_open_by_name("gpiochip0");
    if (!chip) {
        perror("Error opening GPIO chip");
        return -1;
    }

    trigger_line = gpiod_chip_get_line(chip, TRIGGER_PIN);
    if (!trigger_line) {
        perror("Error getting trigger line");
        gpiod_chip_close(chip);
        return -1;
    }

    echo_line = gpiod_chip_get_line(chip, ECHO_PIN);
    if (!echo_line) {
        perror("Error getting echo line");
        gpiod_chip_close(chip);
        return -1;
    }

    led_line = gpiod_chip_get_line(chip, LED_PIN);
    if (!led_line) {
        perror("Error getting LED line");
        gpiod_chip_close(chip);
        return -1;
    }

    if (gpiod_line_request_output(trigger_line, "trigger", 0) < 0) {
        perror("Error requesting trigger line as output");
        gpiod_chip_close(chip);
        return -1;
    }

    if (gpiod_line_request_input(echo_line, "echo") < 0) {
        perror("Error requesting echo line as input");
        gpiod_chip_close(chip);
        return -1;
    }

    if (gpiod_line_request_output(led_line, "led", 0) < 0) {
        perror("Error requesting LED line as output");
        gpiod_chip_close(chip);
        return -1;
    }

    return 0;
}

// Send a 10us trigger pulse
void trigger_pulse() {
    struct timespec start, end;
    clock_gettime(CLOCK_MONOTONIC, &start);
    gpiod_line_set_value(trigger_line, 1);
    usleep(10);
    gpiod_line_set_value(trigger_line, 0);
    clock_gettime(CLOCK_MONOTONIC, &end);
    long long elapsed_ns = (end.tv_sec - start.tv_sec) * 1000000000LL + (end.tv_nsec - start.tv_nsec);
    if (elapsed_ns > TIMEOUT_US * 1000) {
        fprintf(stderr, "Timeout waiting for trigger to be sent.\n");
    }
}

// Measure the echo pulse width
long long get_pulse_width() {
    struct timespec start, end;
    long long start_ns, end_ns;

    // Wait for echo to go high
    clock_gettime(CLOCK_MONOTONIC, &start);
    while (gpiod_line_get_value(echo_line) == 0) {
        clock_gettime(CLOCK_MONOTONIC, &end);
        start_ns = (end.tv_sec - start.tv_sec) * 1000000000LL + (end.tv_nsec - start.tv_nsec);
        if (start_ns > TIMEOUT_US * 1000) {
            fprintf(stderr, "Timeout waiting for echo to go high.\n");
            return -1;
        }
    }

    // Wait for echo to go low
    clock_gettime(CLOCK_MONOTONIC, &start);
    while (gpiod_line_get_value(echo_line) == 1) {
        clock_gettime(CLOCK_MONOTONIC, &end);
        end_ns = (end.tv_sec - start.tv_sec) * 1000000000LL + (end.tv_nsec - start.tv_nsec);
        if (end_ns > TIMEOUT_US * 1000) {
            fprintf(stderr, "Timeout waiting for echo to go low.\n");
            return -1;
        }
    }

    return end_ns - start_ns;
}

// Calculate distance in centimeters
float calculate_distance(long long pulse_width) {
    if (pulse_width < 0) return -1.0; // Indicate error
    return (float)pulse_width * SPEED_OF_SOUND / 2000000.0; // Divide by 2 for one-way distance
}

// Set the LED state
void set_led_state(int state) {
    gpiod_line_set_value(led_line, state);
}

// Cleanup GPIO resources
void cleanup_gpio() {
    if (trigger_line) gpiod_line_release(trigger_line);
    if (echo_line) gpiod_line_release(echo_line);
    if (led_line) gpiod_line_release(led_line);
    if (chip) gpiod_chip_close(chip);
}

int main() {
    // Install signal handler
    signal(SIGINT, signal_handler);

    // Initialize GPIO
    if (init_gpio() < 0) {
        fprintf(stderr, "GPIO initialization failed. Exiting.\n");
        return 1;
    }

    printf("HC-SR04 Distance Sensor\n");

    // Main loop
    while (!terminate) {
        // Trigger the sensor
        trigger_pulse();

        // Measure the pulse width
        long long pulse_width = get_pulse_width();

        // Calculate the distance
        float distance = calculate_distance(pulse_width);

        // Set the LED state based on distance
        if (distance > 0 && distance < 200) {
            set_led_state(1); // Turn LED on
        } else {
            set_led_state(0); // Turn LED off
        }

        // Print the distance
        if (distance > 0) {
            printf("Distance: %.2f cm\n", distance);
        } else {
            fprintf(stderr, "Error: Invalid distance reading.\n");
        }

        // Delay before next measurement
        usleep(500000); // 0.5 seconds
    }

    // Cleanup GPIO resources before exiting
    cleanup_gpio();

    return 0;
}

#include <stdio.h>
#include <stdlib.h>
#include <gpiod.h>
#include <unistd.h>
#include <signal.h>
#include <time.h>
#include <string.h>

#define GPIO_PIN 18
#define GPIO_CHIP "gpiochip0"
#define LOG_FILE "gpio_log.txt"

static struct gpiod_chip *chip;
static struct gpiod_line *line;
static FILE *log_file;
static volatile sig_atomic_t terminate = 0;

// Function to handle signals (e.g., Ctrl+C)
void signal_handler(int sig) {
    terminate = 1;
    printf("\nCaught signal %d, exiting gracefully...\n", sig);
}

// Function to log messages to a file
void log_message(const char *message) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[26];
    strftime(timestamp, sizeof(timestamp)-1, "%Y-%m-%d %H:%M:%S", t);

    fprintf(log_file, "[%s] %s\n", timestamp, message);
    fflush(log_file); // Ensure the log is written immediately
}

// Function to export the GPIO pin
int export_gpio(int pin) {
    char buffer[64];
    int len;
    FILE *fp = fopen("/sys/class/gpio/export", "w");
    if (fp == NULL) {
        perror("Failed to open /sys/class/gpio/export");
        return -1;
    }

    len = snprintf(buffer, sizeof(buffer), "%d", pin);
    if (fwrite(buffer, 1, len, fp) != len) {
        perror("Failed to write to /sys/class/gpio/export");
        fclose(fp);
        return -1;
    }

    fclose(fp);
    return 0;
}

// Function to unexport the GPIO pin
int unexport_gpio(int pin) {
    char buffer[64];
    int len;
    FILE *fp = fopen("/sys/class/gpio/unexport", "w");
    if (fp == NULL) {
        perror("Failed to open /sys/class/gpio/unexport");
        return -1;
    }

    len = snprintf(buffer, sizeof(buffer), "%d", pin);
    if (fwrite(buffer, 1, len, fp) != len) {
        perror("Failed to write to /sys/class/gpio/unexport");
        fclose(fp);
        return -1;
    }

    fclose(fp);
    return 0;
}

// Function to set the GPIO direction
int set_gpio_direction(int pin, const char *direction) {
    char path[64];
    FILE *fp;

    snprintf(path, sizeof(path), "/sys/class/gpio/gpio%d/direction", pin);
    fp = fopen(path, "w");
    if (fp == NULL) {
        perror("Failed to open GPIO direction file");
        return -1;
    }

    if (fprintf(fp, "%s", direction) < 0) {
        perror("Failed to write to GPIO direction file");
        fclose(fp);
        return -1;
    }

    fclose(fp);
    return 0;
}

// Function to set the GPIO value
int set_gpio_value(int pin, int value) {
    char path[64];
    FILE *fp;

    snprintf(path, sizeof(path), "/sys/class/gpio/gpio%d/value", pin);
    fp = fopen(path, "w");
    if (fp == NULL) {
        perror("Failed to open GPIO value file");
        return -1;
    }

    if (fprintf(fp, "%d", value) < 0) {
        perror("Failed to write to GPIO value file");
        fclose(fp);
        return -1;
    }

    fclose(fp);
    return 0;
}

// Function to read the GPIO value
int read_gpio_value(int pin) {
    char path[64];
    FILE *fp;
    int value;

    snprintf(path, sizeof(path), "/sys/class/gpio/gpio%d/value", pin);
    fp = fopen(path, "r");
    if (fp == NULL) {
        perror("Failed to open GPIO value file for reading");
        return -1;
    }

    if (fscanf(fp, "%d", &value) != 1) {
        perror("Failed to read GPIO value");
        fclose(fp);
        return -1;
    }

    fclose(fp);
    return value;
}

int main() {
    int value;
    int retries = 3;
    int delay_ms = 100;

    // Open the log file
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        perror("Failed to open log file");
        return EXIT_FAILURE;
    }

    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Export GPIO pin
    if (export_gpio(GPIO_PIN) != 0) {
        log_message("Failed to export GPIO pin");
        fclose(log_file);
        return EXIT_FAILURE;
    }

    // Set GPIO direction to output
    if (set_gpio_direction(GPIO_PIN, "out") != 0) {
        log_message("Failed to set GPIO direction to output");
        unexport_gpio(GPIO_PIN);
        fclose(log_file);
        return EXIT_FAILURE;
    }

    // Main loop
    while (!terminate) {
        // Generate a random value between 0 and 1
        value = rand() % 2;

        // Set GPIO value
        if (set_gpio_value(GPIO_PIN, value) != 0) {
            log_message("Failed to set GPIO value");
            break;
        }

        // Read GPIO value with retries
        int read_value = -1;
        for (int i = 0; i < retries; i++) {
            read_value = read_gpio_value(GPIO_PIN);
            if (read_value != -1) {
                break; // Success
            }
            usleep(delay_ms * 1000); // Wait before retrying
            delay_ms *= 2; // Exponential backoff
        }

        if (read_value == -1) {
            log_message("Failed to read GPIO value after multiple retries");
            break;
        }

        // Validate the read value
        if (read_value != value) {
            char message[128];
            snprintf(message, sizeof(message), "Invalid GPIO read: expected %d, got %d", value, read_value);
            log_message(message);
            break;
        }

        // Report the state
        printf("GPIO %d set to %d, read back %d\n", GPIO_PIN, value, read_value);

        // Wait for a short period
        sleep(1);
    }

    // Unexport GPIO pin
    if (unexport_gpio(GPIO_PIN) != 0) {
        log_message("Failed to unexport GPIO pin");
    }

    // Close the log file
    fclose(log_file);

    return EXIT_SUCCESS;
}

#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define GPIO_PIN 18

volatile sig_atomic_t program_running = 1;

void signal_handler(int signal) {
    program_running = 0;
    printf("\nCaught signal %d, exiting gracefully...\n", signal);
}

int main() {
    int duty_cycle;

    // Register signal handler for SIGINT (Ctrl+C)
    signal(SIGINT, signal_handler);

    // Initialize pigpio library
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO 18 as output
    gpioSetMode(GPIO_PIN, PI_OUTPUT);

    printf("PWM control on GPIO %d\n", GPIO_PIN);

    while (program_running) {
        // Cycle through duty cycles from 0 to 1000
        for (duty_cycle = 0; duty_cycle <= 1000; duty_cycle += 10) {
            gpioPWM(GPIO_PIN, duty_cycle);
            printf("Duty cycle: %d\n", duty_cycle);
            usleep(200000); // 0.2 seconds
        }

        // Cycle through duty cycles from 1000 to 0
        for (duty_cycle = 1000; duty_cycle >= 0; duty_cycle -= 10) {
            gpioPWM(GPIO_PIN, duty_cycle);
            printf("Duty cycle: %d\n", duty_cycle);
            usleep(200000); // 0.2 seconds
        }
    }

    // Stop PWM output
    gpioPWM(GPIO_PIN, 0);

    // Release GPIO resources
    gpioTerminate();

    printf("Program terminated.\n");
    return 0;
}

#include <stdio.h>
#include <stdlib.h>
#include <gpiod.h>
#include <signal.h>
#include <unistd.h>

// Define GPIO pins
#define GPIO_17 17
#define GPIO_18 18

// Global variables for GPIO lines and chip
struct gpiod_line *line17 = NULL;
struct gpiod_line *line18 = NULL;
struct gpiod_chip *chip = NULL;

// Signal handler for Ctrl+C
void signal_handler(int sig) {
    printf("\nCaught signal %d, cleaning up...\n", sig);

    // Release GPIO lines
    if (line17) {
        gpiod_line_release(line17);
    }
    if (line18) {
        gpiod_line_release(line18);
    }

    // Close GPIO chip
    if (chip) {
        gpiod_chip_close(chip);
    }

    exit(0);
}

int main() {
    // Register signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    // Open GPIO chip
    chip = gpiod_chip_open_by_name("gpiochip0");
    if (!chip) {
        perror("Error opening GPIO chip");
        return 1;
    }

    // Get GPIO lines for GPIO 17 and GPIO 18
    line17 = gpiod_chip_get_line(chip, GPIO_17);
    if (!line17) {
        perror("Error getting GPIO 17 line");
        gpiod_chip_close(chip);
        return 1;
    }

    line18 = gpiod_chip_get_line(chip, GPIO_18);
    if (!line18) {
        perror("Error getting GPIO 18 line");
        gpiod_line_release(line17);
        gpiod_chip_close(chip);
        return 1;
    }

    // Request GPIO lines for output
    if (gpiod_line_request_output(line17, "gpio_output", 0) < 0) {
        perror("Error requesting GPIO 17 for output");
        gpiod_line_release(line17);
        gpiod_line_release(line18);
        gpiod_chip_close(chip);
        return 1;
    }

    if (gpiod_line_request_output(line18, "gpio_output", 1) < 0) {
        perror("Error requesting GPIO 18 for output");
        gpiod_line_release(line17);
        gpiod_line_release(line18);
        gpiod_chip_close(chip);
        return 1;
    }

    // Set GPIO 17 to HIGH and GPIO 18 to LOW
    if (gpiod_line_set_value(line17, 1) < 0) {
        perror("Error setting GPIO 17 HIGH");
        gpiod_line_release(line17);
        gpiod_line_release(line18);
        gpiod_chip_close(chip);
        return 1;
    }

    if (gpiod_line_set_value(line18, 0) < 0) {
        perror("Error setting GPIO 18 LOW");
        gpiod_line_release(line17);
        gpiod_line_release(line18);
        gpiod_chip_close(chip);
        return 1;
    }

    // Report GPIO states
    printf("GPIO 17: %d\n", gpiod_line_get_value(line17));
    printf("GPIO 18: %d\n", gpiod_line_get_value(line18));

    // Release GPIO lines
    gpiod_line_release(line17);
    gpiod_line_release(line18);

    // Close GPIO chip
    gpiod_chip_close(chip);

    return 0;
}

#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

// Define GPIO pins
#define GPIO_18 18
#define GPIO_23 23
#define GPIO_24 24

// Global variable to track program state for signal handling
volatile sig_atomic_t program_running = 1;

// Signal handler function
void signal_handler(int signal) {
    program_running = 0;
    printf("\nCaught signal %d, exiting gracefully...\n", signal);
}

int main() {
    // Register signal handlers for SIGINT and SIGTERM
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize pigpio library
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Configure GPIO pins as outputs
    gpioSetMode(GPIO_18, PI_OUTPUT);
    gpioSetMode(GPIO_23, PI_OUTPUT);
    gpioSetMode(GPIO_24, PI_OUTPUT);

    // Main loop
    while (program_running) {
        // Set GPIO 18 HIGH
        gpioWrite(GPIO_18, 1);
        printf("GPIO 18 HIGH\n");

        // Set GPIO 23 LOW
        gpioWrite(GPIO_23, 0);
        printf("GPIO 23 LOW\n");

        // Set GPIO 24 HIGH
        gpioWrite(GPIO_24, 1);
        printf("GPIO 24 HIGH\n");

        // Wait for 0.1 seconds
        gpioDelay(100000); // 100000 microseconds = 0.1 seconds

        // Set GPIO 18 LOW
        gpioWrite(GPIO_18, 0);
        printf("GPIO 18 LOW\n");

        // Set GPIO 23 HIGH
        gpioWrite(GPIO_23, 1);
        printf("GPIO 23 HIGH\n");

        // Set GPIO 24 LOW
        gpioWrite(GPIO_24, 0);
        printf("GPIO 24 LOW\n");

        // Wait for 0.1 seconds
        gpioDelay(100000); // 100000 microseconds = 0.1 seconds
    }

    // Clean up and terminate pigpio library
    gpioTerminate();
    printf("pigpio terminated\n");

    return 0;
}

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <fcntl.h>
#include <unistd.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <signal.h>
#include <errno.h>
#include <string.h>

// MPU6050 I2C address
#define MPU6050_ADDR 0x68

// MPU6050 registers
#define PWR_MGMT_1   0x6B
#define ACCEL_XOUT_H 0x3B
#define ACCEL_YOUT_H 0x3D
#define ACCEL_ZOUT_H 0x3F

// Global variable for I2C file descriptor
int i2c_fd = -1;

// Signal handler for Ctrl+C
void signal_handler(int sig) {
    printf("\nExiting program...\n");
    if (i2c_fd != -1) {
        close(i2c_fd);
    }
    exit(0);
}

// Function to read a single byte from an I2C register
int read_i2c_reg(int fd, uint8_t reg) {
    if (write(fd, &reg, 1) != 1) {
        perror("Failed to write register address");
        return -1;
    }
    uint8_t value;
    if (read(fd, &value, 1) != 1) {
        perror("Failed to read register value");
        return -1;
    }
    return value;
}

// Function to write a single byte to an I2C register
int write_i2c_reg(int fd, uint8_t reg, uint8_t value) {
    uint8_t buf[2];
    buf[0] = reg;
    buf[1] = value;
    if (write(fd, buf, 2) != 2) {
        perror("Failed to write register value");
        return -1;
    }
    return 0;
}

// Function to read accelerometer data
int read_accelerometer_data(int fd, int16_t *x, int16_t *y, int16_t *z) {
    uint8_t buffer[6];
    uint8_t reg = ACCEL_XOUT_H;

    if (write(fd, &reg, 1) != 1) {
        perror("Failed to write register address for accelerometer data");
        return -1;
    }

    if (read(fd, buffer, 6) != 6) {
        perror("Failed to read accelerometer data");
        return -1;
    }

    *x = (int16_t)((buffer[0] << 8) | buffer[1]);
    *y = (int16_t)((buffer[2] << 8) | buffer[3]);
    *z = (int16_t)((buffer[4] << 8) | buffer[5]);

    return 0;
}

int main() {
    // Register signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    // Open I2C device
    i2c_fd = open("/dev/i2c-1", O_RDWR);
    if (i2c_fd < 0) {
        perror("Failed to open I2C device");
        return 1;
    }

    // Specify the address of the slave device
    if (ioctl(i2c_fd, I2C_SLAVE, MPU6050_ADDR) < 0) {
        perror("Failed to acquire bus access and/or talk to slave");
        close(i2c_fd);
        return 1;
    }

    // Wake up the MPU6050 (clear sleep mode bit)
    if (write_i2c_reg(i2c_fd, PWR_MGMT_1, 0) < 0) {
        fprintf(stderr, "Failed to wake up MPU6050\n");
        close(i2c_fd);
        return 1;
    }

    // Main loop
    while (1) {
        int16_t x, y, z;

        // Read accelerometer data
        if (read_accelerometer_data(i2c_fd, &x, &y, &z) == 0) {
            // Print the accelerometer data
            printf("X: %d, Y: %d, Z: %d\n", x, y, z);
        } else {
            fprintf(stderr, "Failed to read accelerometer data. Retrying...\n");
        }

        // Wait for 1 second
        sleep(1);
    }

    // The program should never reach here due to the infinite loop,
    // but include close(i2c_fd) for completeness.
    close(i2c_fd);
    return 0;
}

#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define GPIO_PIN 17

volatile sig_atomic_t program_running = 1;

void signal_handler(int signal) {
    program_running = 0;
    printf("\nCaught signal %d, exiting gracefully...\n", signal);
}

int main() {
    int gpio_status;

    // Register signal handlers for SIGINT and SIGTERM
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize pigpio library
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO 17 as an output
    gpioSetMode(GPIO_PIN, PI_OUTPUT);

    printf("GPIO %d set as output.  Toggling every 0.6 seconds. Press Ctrl+C to exit.\n", GPIO_PIN);

    // Main loop
    while (program_running) {
        // Set GPIO high
        gpioWrite(GPIO_PIN, 1);
        gpio_status = gpioRead(GPIO_PIN);
        printf("GPIO %d set to HIGH (read: %d)\n", GPIO_PIN, gpio_status);

        // Wait for 600 milliseconds
        gpioDelay(600000); // 600000 microseconds = 0.6 seconds

        // Set GPIO low
        gpioWrite(GPIO_PIN, 0);
        gpio_status = gpioRead(GPIO_PIN);
        printf("GPIO %d set to LOW (read: %d)\n", GPIO_PIN, gpio_status);

        // Wait for 600 milliseconds
        gpioDelay(600000); // 600000 microseconds = 0.6 seconds
    }

    // Clean up and terminate pigpio library
    gpioTerminate();
    printf("pigpio terminated.\n");

    return 0;
}
